CREATE TABLE IF NOT EXISTS public."wa_agente_membros" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "tenant_id" uuid NOT NULL,
  "user_id" uuid NOT NULL,
  "telefone" text NOT NULL,
  "telefone_chave" text GENERATED ALWAYS AS (
CASE
    WHEN (telefone ~ '^\+55[1-9][0-9][6-9][0-9]{7}$'::text) THEN ((('55'::text || substr(telefone, 4, 2)) || '9'::text) || substr(telefone, 6))
    ELSE substr(telefone, 2)
END) STORED,
  "ativo" boolean DEFAULT true NOT NULL,
  "boas_vindas_em" timestamp with time zone,
  "created_by" uuid DEFAULT auth.uid(),
  "created_at" timestamp with time zone DEFAULT now() NOT NULL
);

