CREATE OR REPLACE FUNCTION private.atendimento_mensagem_cliente(p_tenant uuid, p_cliente uuid, p_mensagem uuid)
 RETURNS TABLE(id uuid, criado_em timestamp with time zone, autor_tipo text, tipo text, conteudo text, conversation_id uuid, autor_user_id uuid, ocorrido_em timestamp with time zone, atestada_em timestamp with time zone, registrado_em timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  SELECT m.id, m.criado_em, m.autor_tipo, m.tipo,
         CASE WHEN c.tipo = 'grupo' THEN regexp_replace(m.conteudo, '^\[[^]\n]{1,80}\] ', '') ELSE m.conteudo END,
         m.conversation_id, m.autor_user_id, original.ocorrido_em, original.atestada_em, original.registrado_em
    FROM public.chat_messages m
    JOIN private.atendimento_wa_entradas original ON original.mensagem_id = m.id
      AND original.tenant_id = m.tenant_id AND original.conversation_id = m.conversation_id
      AND original.criado_em = m.criado_em AND original.autor_tipo = m.autor_tipo
      AND original.autor_user_id IS NOT DISTINCT FROM m.autor_user_id
      AND original.texto_sha256 = encode(extensions.digest(convert_to(m.conteudo, 'UTF8'), 'sha256'), 'hex')
      -- Retornar também a prontidão: o intervalo INSERT→atestação não pode ser
      -- confundido com fonte inválida, pois o sucesso avançaria o cursor.
    JOIN public.chat_conversations cv ON cv.id = m.conversation_id AND cv.tenant_id = p_tenant
      AND cv.contact_id = original.contact_id AND cv.instance_id = original.instance_id
    JOIN public.chat_contacts ct ON ct.id = cv.contact_id AND ct.tenant_id = p_tenant
      AND ct.instance_id = original.instance_id
      AND private.canal_tipo(ct.numero_whatsapp, ct.group_size) = original.canal_tipo
      AND private.canal_chave(ct.numero_whatsapp, ct.group_size) = original.canal_chave
    JOIN public.cliente_canais c ON c.tenant_id = p_tenant AND c.client_id = p_cliente
      AND c.status = 'confirmado'
      AND c.tipo = private.canal_tipo(ct.numero_whatsapp, ct.group_size)
      AND c.chave = private.canal_chave(ct.numero_whatsapp, ct.group_size)
   WHERE m.id = p_mensagem AND m.tenant_id = p_tenant
     AND m.autor_origem = 'webhook' AND m.reply_to_id IS NULL
     AND m.enviado_por_agente IS NOT TRUE AND m.enviado_por_ia IS NOT TRUE
     AND NOT ct.restrito_admin
     AND NOT private.cliente_canal_excluido(p_tenant, c.tipo, c.chave)
     AND NOT EXISTS (SELECT 1 FROM public.cliente_canais outro
       WHERE outro.tenant_id = p_tenant AND outro.tipo = c.tipo AND outro.chave = c.chave
         AND outro.status = 'confirmado' AND outro.client_id IS DISTINCT FROM p_cliente)
   LIMIT 1;
$function$
;

CREATE OR REPLACE FUNCTION private.atendimento_resolucoes_ia_recibo_imutavel()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  RAISE EXCEPTION 'Recibos de resolução automática são imutáveis.' USING ERRCODE='42501';
END;
$function$
;

CREATE OR REPLACE FUNCTION private.atendimento_wa_capturar_entrada()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF current_user = 'service_role' AND auth.uid() IS NULL
     AND NEW.autor_origem = 'webhook' AND NEW.autor_tipo IN ('cliente', 'equipe')
     AND NEW.enviado_por_agente IS NOT TRUE AND NEW.enviado_por_ia IS NOT TRUE
     AND NEW.reply_to_id IS NULL AND NEW.conteudo IS NOT NULL
     AND NEW.tipo IN ('texto', 'text', 'chat') THEN
    INSERT INTO private.atendimento_wa_entradas
      (mensagem_id, tenant_id, conversation_id, contact_id, instance_id, canal_tipo, canal_chave,
       criado_em, autor_tipo, autor_user_id, texto_sha256)
    SELECT NEW.id, NEW.tenant_id, NEW.conversation_id, ct.id, ct.instance_id,
      private.canal_tipo(ct.numero_whatsapp, ct.group_size), private.canal_chave(ct.numero_whatsapp, ct.group_size),
      NEW.criado_em, NEW.autor_tipo, NEW.autor_user_id,
      encode(extensions.digest(convert_to(NEW.conteudo, 'UTF8'), 'sha256'), 'hex')
    FROM public.chat_conversations cv JOIN public.chat_contacts ct ON ct.id = cv.contact_id
      AND ct.tenant_id = NEW.tenant_id AND ct.instance_id = cv.instance_id
    WHERE cv.id = NEW.conversation_id AND cv.tenant_id = NEW.tenant_id
      AND private.canal_tipo(ct.numero_whatsapp, ct.group_size) IS NOT NULL
      AND private.canal_chave(ct.numero_whatsapp, ct.group_size) IS NOT NULL
    ON CONFLICT (mensagem_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.autoria_chave_nome(p text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT left(btrim(regexp_replace(
           regexp_replace(lower(extensions.unaccent('extensions.unaccent'::regdictionary, coalesce(p, ''))),
                          '[^a-z0-9 ]', ' ', 'g'),
           '\s+', ' ', 'g')), 80)
$function$
;

CREATE OR REPLACE FUNCTION private.autoria_chave_tel(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
           WHEN d = '' THEN NULL
           WHEN d ~ '^55[1-9][0-9][6-9][0-9]{7}$' THEN '55' || substr(d, 3, 2) || '9' || substr(d, 5)
           ELSE d
         END
    FROM (SELECT regexp_replace(coalesce(p, ''), '[^0-9]', '', 'g') AS d) s
$function$
;

CREATE OR REPLACE FUNCTION private.autoria_chave_tel8(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
           WHEN left(d, 2) = '55' AND length(d) IN (12, 13) THEN substr(d, 3, 2) || right(d, 8)
           WHEN length(d) IN (10, 11) THEN substr(d, 1, 2) || right(d, 8)
           ELSE NULL
         END
    FROM (SELECT ltrim(regexp_replace(coalesce(p, ''), '[^0-9]', '', 'g'), '0') AS d) s
$function$
;

CREATE OR REPLACE FUNCTION private.canal_chave(p_numero text, p_group_size integer DEFAULT NULL::integer)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v      TEXT := lower(btrim(coalesce(p_numero, '')));
  v_tipo TEXT := private.canal_tipo(p_numero, p_group_size);
  v_dig  TEXT;
BEGIN
  IF v_tipo IS NULL THEN
    RETURN NULL;
  END IF;
  IF v_tipo = 'grupo' THEN
    IF right(v, 5) = '@g.us' THEN
      v := left(v, length(v) - 5);
    END IF;
    IF length(v) <= 60 AND v ~ '^(120363[0-9]{9,15}|[1-9][0-9]{9,14}-[0-9]{9,11})$' THEN
      RETURN v;
    END IF;
    RETURN NULL;
  END IF;
  IF position('@' IN v) > 0 THEN
    v := split_part(split_part(v, '@', 1), ':', 1);
  END IF;
  v_dig := regexp_replace(v, '[^0-9]', '', 'g');
  IF v_dig ~ '^55[1-9][0-9][6-9][0-9]{7}$' THEN
    RETURN '55' || substr(v_dig, 3, 2) || '9' || substr(v_dig, 5);
  END IF;
  RETURN v_dig;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.canal_formas(p_tipo text, p_chave text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN p_chave IS NULL THEN '{}'::text[]
    WHEN p_tipo = 'grupo' THEN ARRAY[p_chave, p_chave || '@g.us']
    -- celular BR com o 9: também a forma antiga, sem o 9
    WHEN p_tipo = 'privado' AND p_chave ~ '^55[1-9][0-9]9[6-9][0-9]{7}$'
      THEN ARRAY[p_chave, '55' || substr(p_chave, 3, 2) || substr(p_chave, 6)]
    WHEN p_tipo = 'privado' THEN ARRAY[p_chave]
    ELSE '{}'::text[]
  END
$function$
;

CREATE OR REPLACE FUNCTION private.canal_tipo(p_numero text, p_group_size integer DEFAULT NULL::integer)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v     TEXT := lower(btrim(coalesce(p_numero, '')));
  v_dig TEXT;
BEGIN
  IF v = '' OR length(v) > 80 THEN
    RETURN NULL;
  END IF;
  IF right(v, 5) = '@g.us' OR coalesce(p_group_size, 0) > 0
     OR v ~ '^(120363[0-9]{9,15}|[1-9][0-9]{9,14}-[0-9]{9,11})$' THEN
    RETURN 'grupo';
  END IF;
  IF position('@' IN v) > 0 THEN
    -- Só JID de pessoa com telefone; LID ("…@lid") não é telefone.
    IF split_part(v, '@', 2) NOT IN ('s.whatsapp.net', 'c.us') THEN
      RETURN NULL;
    END IF;
    v := split_part(split_part(v, '@', 1), ':', 1);
  END IF;
  v_dig := regexp_replace(v, '[^0-9]', '', 'g');
  IF length(v_dig) > 15 THEN
    RETURN 'grupo'; -- id longo (contatoEhGrupo); sem formato conhecido a chave sai NULL
  END IF;
  IF length(v_dig) BETWEEN 8 AND 15 THEN
    RETURN 'privado';
  END IF;
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.chat_contatos_restritos_ids()
 RETURNS uuid[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH t AS (SELECT public.get_user_tenant_id() AS tid)
  SELECT COALESCE(array_agg(c.id), '{}'::uuid[])
    FROM public.chat_contacts c, t
   WHERE c.restrito_admin
     AND t.tid IS NOT NULL
     AND c.tenant_id = t.tid
$function$
;

CREATE OR REPLACE FUNCTION private.chat_conversas_restritas_ids()
 RETURNS uuid[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH t AS (SELECT public.get_user_tenant_id() AS tid)
  SELECT COALESCE(array_agg(cv.id), '{}'::uuid[])
    FROM public.chat_contacts c
    JOIN public.chat_conversations cv ON cv.contact_id = c.id
    CROSS JOIN t
   WHERE c.restrito_admin
     AND t.tid IS NOT NULL
     AND c.tenant_id = t.tid
$function$
;

CREATE OR REPLACE FUNCTION private.chat_midia_caminho(p_media_url text, p_conversation_id uuid)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN p_media_url IS NULL OR p_conversation_id IS NULL THEN NULL
    WHEN p_media_url NOT LIKE 'https://%/storage/v1/object/public/chat-media/%' THEN NULL
    WHEN position('..' IN p_media_url) > 0 OR position('?' IN p_media_url) > 0 THEN NULL
    WHEN split_part(split_part(p_media_url, '/storage/v1/object/public/chat-media/', 2), '/', 1)
         <> p_conversation_id::text THEN NULL
    WHEN length(split_part(p_media_url, '/storage/v1/object/public/chat-media/', 2)) > 300 THEN NULL
    ELSE split_part(p_media_url, '/storage/v1/object/public/chat-media/', 2)
  END
$function$
;

CREATE OR REPLACE FUNCTION private.chat_midia_enfileirar()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_tipo text;
BEGIN
  v_tipo := private.chat_midia_tipo_fila(NEW.tipo, NEW.conteudo);
  IF v_tipo IS NULL
     OR NEW.tenant_id IS NULL
     OR private.chat_midia_caminho(NEW.media_url, NEW.conversation_id) IS NULL THEN
    RETURN NULL;
  END IF;

  -- Grupo interno (relatório / assistente): nunca vai para a IA.
  IF EXISTS (
    SELECT 1
      FROM public.chat_conversations cv
      JOIN public.chat_contacts c ON c.id = cv.contact_id
     WHERE cv.id = NEW.conversation_id
       AND c.restrito_admin
  ) THEN
    RETURN NULL;
  END IF;

  -- Só empresa com o app Automações WhatsApp ligado (custo de IA).
  IF NOT EXISTS (
    SELECT 1 FROM public.app_modules a
     WHERE a.tenant_id = NEW.tenant_id AND a.slug = 'automacoes-wa' AND a.enabled
  ) THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.chat_midia_texto (message_id, tenant_id, tipo, status, mensagem_em)
  VALUES (NEW.id, NEW.tenant_id, v_tipo, 'pendente', coalesce(NEW.criado_em, now()))
  ON CONFLICT (message_id) DO NOTHING;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'chat_midia_enfileirar: falhou (%)', SQLSTATE;
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.chat_midia_texto_confere()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.tenant_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.chat_messages m WHERE m.id = NEW.message_id AND m.tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'Mensagem não encontrada nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;
  NEW.atualizado_em := now();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.chat_midia_tipo_fila(p_tipo text, p_conteudo text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN lower(coalesce(p_tipo, '')) IN ('audio', 'ptt') THEN 'transcricao'
    WHEN lower(coalesce(p_tipo, '')) IN ('imagem', 'image')
         AND length(btrim(regexp_replace(coalesce(p_conteudo, ''), '^\s*\[[^\]]{1,80}\]\s*', ''))) < 20
      THEN 'descricao'
    ELSE NULL
  END
$function$
;

CREATE OR REPLACE FUNCTION private.client_assignment_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='atribuicao_historico_imutavel'; END;
$function$
;

CREATE OR REPLACE FUNCTION private.client_assignment_auditar()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE a public.client_assignments%ROWTYPE; v_before jsonb; v_after jsonb; v_nome text;
  v_rev bigint; v_ator_nome text; v_op public.client_assignment_operations%ROWTYPE; v_ator uuid;
BEGIN
  IF TG_OP = 'UPDATE' AND to_jsonb(NEW) IS NOT DISTINCT FROM to_jsonb(OLD) THEN RETURN NEW; END IF;
  IF TG_OP = 'DELETE' THEN a := OLD; ELSE a := NEW; END IF;
  v_ator:=auth.uid();
  IF v_ator IS NULL THEN v_ator:=coalesce((private.client_assignment_report_contexto_20261105(a.client_id)->>'ator_id')::uuid,
    (private.client_assignment_iris_contexto(a.client_id)->>'ator_id')::uuid); END IF;
  SELECT nome INTO STRICT v_nome FROM public.users WHERE id = a.user_id AND tenant_id = a.tenant_id;
  SELECT nome INTO STRICT v_ator_nome FROM public.users WHERE id = v_ator AND tenant_id = a.tenant_id;
  IF TG_OP <> 'INSERT' THEN v_before := jsonb_build_object('id',OLD.id,'client_id',OLD.client_id,
    'user_id',OLD.user_id,'tipo',OLD.tipo,'ativo',OLD.ativo,'criado_em',OLD.criado_em,'usuario_nome',v_nome); END IF;
  IF TG_OP <> 'DELETE' THEN v_after := jsonb_build_object('id',NEW.id,'client_id',NEW.client_id,
    'user_id',NEW.user_id,'tipo',NEW.tipo,'ativo',NEW.ativo,'criado_em',NEW.criado_em,'usuario_nome',v_nome); END IF;
  UPDATE public.client_assignment_state SET revisao = revisao + 1
   WHERE client_id = a.client_id AND tenant_id = a.tenant_id RETURNING revisao INTO STRICT v_rev;
  SELECT * INTO v_op FROM public.client_assignment_operations
   WHERE tenant_id = a.tenant_id AND client_id = a.client_id AND ator_id = v_ator
     AND transacao = txid_current() AND resposta IS NULL;
  INSERT INTO public.client_assignment_events
    (tenant_id, client_id, revisao, operacao_id, acao, origem, motivo, ator_id, ator_nome, antes, depois)
  VALUES (a.tenant_id, a.client_id, v_rev, coalesce(v_op.id, gen_random_uuid()),
    coalesce(v_op.acao, CASE WHEN TG_OP = 'DELETE' THEN 'encerrar' ELSE 'adicionar' END),
    coalesce(v_op.origem, 'legado_dml'),
    coalesce(v_op.motivo, 'Alteração direta legada; motivo não informado pelo escritor.'),
    v_ator, v_ator_nome, v_before, v_after);
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.client_assignment_autorizar(p_client_id uuid, p_escrita boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE c jsonb; t uuid; a uuid; total boolean; ids uuid[];
BEGIN
  c:=private.client_assignment_report_contexto_20261105(p_client_id);
  IF c IS NOT NULL THEN
    IF p_escrita IS DISTINCT FROM true THEN RAISE EXCEPTION 'manutencao_somente_escrita' USING ERRCODE='42501'; END IF;
    PERFORM 1 FROM public.clients WHERE id=p_client_id AND tenant_id=(c->>'tenant_id')::uuid FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'manutencao_cliente_ausente' USING ERRCODE='42501'; END IF;
    c:=private.client_assignment_report_contexto_20261105(p_client_id);
    IF c IS NULL THEN RAISE EXCEPTION 'manutencao_contexto_ausente' USING ERRCODE='42501'; END IF;
    RETURN c;
  END IF;
  IF auth.uid() IS NOT NULL THEN RETURN private.client_assignment_autorizar_sessao(p_client_id,p_escrita); END IF;
  IF p_escrita IS DISTINCT FROM true THEN RAISE EXCEPTION 'atribuicao_sem_permissao' USING ERRCODE='42501'; END IF;
  c:=private.client_assignment_iris_contexto(p_client_id); t:=(c->>'tenant_id')::uuid; a:=(c->>'ator_id')::uuid;
  PERFORM 1 FROM public.clients WHERE id=p_client_id AND tenant_id=t FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'atribuicao_sem_permissao' USING ERRCODE='42501'; END IF;
  -- Revalidação após mutex; uma operação pendente conserva apenas o próprio
  -- acesso inicial durante a troca da última membership do autor.
  c:=private.client_assignment_iris_contexto(p_client_id);
  SELECT s.total,s.client_ids INTO total,ids FROM public.wa_agente_escopo(t,a) s;
  IF total IS NOT TRUE AND NOT (p_client_id=ANY(coalesce(ids,'{}'::uuid[]))) AND NOT EXISTS (
    SELECT 1 FROM public.client_assignment_operations op WHERE op.tenant_id=t AND op.client_id=p_client_id
      AND op.ator_id=a AND op.transacao=txid_current() AND op.resposta IS NULL
      AND op.idempotencia=(c->>'proposta_id')::uuid AND op.origem='iris_whatsapp'
  ) THEN RAISE EXCEPTION 'atribuicao_sem_permissao' USING ERRCODE='42501'; END IF;
  RETURN c;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.client_assignment_autorizar_sessao(p_client_id uuid, p_escrita boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE u record; v_cliente uuid;
BEGIN
  SELECT id, tenant_id, nome INTO u FROM public.users
   WHERE id = auth.uid() AND tenant_id = public.get_user_tenant_id()
     AND ativo IS TRUE AND perfil <> 'cliente' FOR SHARE;
  IF NOT FOUND OR (p_escrita AND NOT coalesce(public.has_permissao('clientes.atribuir','editar'), false))
    OR (NOT coalesce(public.client_assignment_pode_ler(p_client_id), false) AND NOT (
      p_escrita AND EXISTS (
        -- Só uma operação criada pela RPC, nesta tx/ator/cliente, preserva a
        -- autorização inicial ao transferir a última membership do próprio ator.
        SELECT 1 FROM public.client_assignment_operations op WHERE op.tenant_id = u.tenant_id
          AND op.client_id = p_client_id AND op.ator_id = auth.uid()
          AND op.transacao = txid_current() AND op.resposta IS NULL
      )
    )) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'atribuicao_sem_permissao';
  END IF;
  IF p_escrita THEN
    SELECT id INTO v_cliente FROM public.clients WHERE id = p_client_id AND tenant_id = u.tenant_id FOR UPDATE;
  ELSE
    SELECT id INTO v_cliente FROM public.clients WHERE id = p_client_id AND tenant_id = u.tenant_id FOR SHARE;
  END IF;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'atribuicao_sem_permissao'; END IF;
  -- A espera pelo mutex pode ter permitido a outro escritor retirar o acesso.
  IF (p_escrita AND NOT coalesce(public.has_permissao('clientes.atribuir','editar'), false))
    OR (NOT coalesce(public.client_assignment_pode_ler(p_client_id), false) AND NOT (
      p_escrita AND EXISTS (SELECT 1 FROM public.client_assignment_operations op
        WHERE op.tenant_id=u.tenant_id AND op.client_id=p_client_id AND op.ator_id=auth.uid()
          AND op.transacao=txid_current() AND op.resposta IS NULL)
    )) THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='atribuicao_sem_permissao'; END IF;
  RETURN jsonb_build_object('tenant_id', u.tenant_id, 'ator_id', u.id, 'ator_nome', u.nome);
END;
$function$
;

CREATE OR REPLACE FUNCTION private.client_assignment_elegivel(p_tenant uuid, p_user uuid, p_tipo text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT p_tipo IN ('estrategista','atendimento') AND EXISTS (
    SELECT 1 FROM public.users u WHERE u.id = p_user AND u.tenant_id = p_tenant
      AND u.ativo IS TRUE AND u.perfil <> 'cliente'
      AND (u.perfil IN ('admin','gerente')
        OR u.perfil = p_tipo
        OR EXISTS (SELECT 1 FROM public.client_assignments a
          WHERE a.tenant_id = p_tenant AND a.user_id = u.id AND a.tipo = p_tipo AND a.ativo IS TRUE))
  )
$function$
;

CREATE OR REPLACE FUNCTION private.client_assignment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_ctx jsonb; v_client uuid; v_tenant uuid; v_user uuid; v_ativo boolean; v_perfil text; v_item jsonb;
BEGIN
  v_client := CASE WHEN TG_OP = 'DELETE' THEN OLD.client_id ELSE NEW.client_id END;
  v_ctx := private.client_assignment_autorizar(v_client, true);
  v_tenant := (v_ctx->>'tenant_id')::uuid;
  IF auth.uid() IS NULL THEN
    v_item:=v_ctx->'item';
    IF NOT EXISTS (SELECT 1 FROM public.client_assignment_operations op
      WHERE op.tenant_id=v_tenant AND op.client_id=v_client AND op.ator_id=(v_ctx->>'ator_id')::uuid
        AND op.transacao=txid_current() AND op.resposta IS NULL AND op.origem=coalesce(v_ctx->>'origem','iris_whatsapp')
        AND op.idempotencia=(v_ctx->>'proposta_id')::uuid) THEN
      RAISE EXCEPTION 'atribuicao_sem_permissao' USING ERRCODE='42501';
    END IF;
    IF TG_OP='DELETE' THEN
      IF OLD.id IS DISTINCT FROM (v_item->>'assignment_id')::uuid OR OLD.tipo IS DISTINCT FROM 'estrategista'
        OR OLD.ativo IS DISTINCT FROM true THEN RAISE EXCEPTION 'atribuicao_sem_permissao' USING ERRCODE='42501'; END IF;
    ELSE
      IF NEW.tipo IS DISTINCT FROM 'estrategista' OR NEW.user_id IS DISTINCT FROM (v_item->>'user_id')::uuid
        OR NEW.ativo IS DISTINCT FROM true THEN RAISE EXCEPTION 'atribuicao_sem_permissao' USING ERRCODE='42501'; END IF;
      IF TG_OP='UPDATE' AND OLD.ativo IS DISTINCT FROM false THEN
        RAISE EXCEPTION 'atribuicao_sem_permissao' USING ERRCODE='42501';
      END IF;
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' AND (to_jsonb(NEW) - 'ativo') IS DISTINCT FROM (to_jsonb(OLD) - 'ativo') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'atribuicao_identidade_imutavel';
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD.tenant_id IS DISTINCT FROM v_tenant THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='atribuicao_sem_permissao'; END IF;
    v_user := OLD.user_id;
  ELSE
    IF NEW.tenant_id IS NOT NULL AND NEW.tenant_id IS DISTINCT FROM v_tenant THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='atribuicao_sem_permissao';
    END IF;
    NEW.tenant_id := v_tenant;
    IF NEW.ativo IS DISTINCT FROM true THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='atribuicao_use_encerrar';
    END IF;
    IF NEW.tipo NOT IN ('estrategista','atendimento') THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='atribuicao_parametros_invalidos';
    END IF;
    IF TG_OP = 'INSERT' THEN NEW.criado_em := clock_timestamp(); END IF;
    v_user := NEW.user_id;
  END IF;
  -- Mantém nome/atividade do alvo estáveis até o commit. Encerrar aceita alvo inativo.
  SELECT ativo, perfil INTO v_ativo, v_perfil FROM public.users
   WHERE id = v_user AND tenant_id = v_tenant FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='atribuicao_retencao_historico'; END IF;
  IF TG_OP <> 'DELETE' THEN
    IF v_ativo IS DISTINCT FROM true THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='atribuicao_destino_inativo'; END IF;
    IF NOT coalesce(private.client_assignment_elegivel(v_tenant, v_user, NEW.tipo), false) THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='atribuicao_destino_inelegivel';
    END IF;
  END IF;
  INSERT INTO public.client_assignment_state (client_id, tenant_id) VALUES (v_client, v_tenant) ON CONFLICT (client_id) DO NOTHING;
  PERFORM 1 FROM public.client_assignment_state WHERE client_id = v_client AND tenant_id = v_tenant FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='atribuicao_sem_permissao'; END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.client_assignment_iris_contexto(p_client_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE x private.client_assignment_iris_context%ROWTYPE; p public.wa_agente_pedidos%ROWTYPE;
  v public.wa_agente_acoes_propostas%ROWTYPE; i jsonb; u public.users%ROWTYPE;
BEGIN
  IF auth.uid() IS NOT NULL THEN RAISE EXCEPTION 'atribuicao_sem_permissao' USING ERRCODE='42501'; END IF;
  SELECT * INTO x FROM private.client_assignment_iris_context
    WHERE backend_pid=pg_backend_pid() AND transacao=txid_current() AND client_id=p_client_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'atribuicao_sem_permissao' USING ERRCODE='42501'; END IF;
  SELECT * INTO p FROM public.wa_agente_pedidos WHERE id=x.pedido_id;
  SELECT * INTO v FROM public.wa_agente_acoes_propostas WHERE id=x.proposta_id;
  IF p.id IS NULL OR v.id IS NULL OR v.acao IS DISTINCT FROM 'cliente_estrategista'
    OR v.estado IS DISTINCT FROM 'pendente' OR v.expira_em <= clock_timestamp()
    OR p.status IS DISTINCT FROM 'processando' OR p.lock_ate IS NULL OR p.lock_ate <= clock_timestamp()
    OR p.entrada_texto_sha256 IS NULL OR p.entrada_encaminhada IS TRUE
    OR p.user_id IS NULL OR p.membro_id IS NULL OR p.eh_grupo IS NOT TRUE
    OR p.tenant_id IS DISTINCT FROM v.tenant_id OR p.user_id IS DISTINCT FROM v.user_id
    OR p.membro_id IS DISTINCT FROM v.membro_id OR p.instance_uuid IS DISTINCT FROM v.instance_uuid
    OR p.chat_jid IS DISTINCT FROM v.chat_jid OR p.remetente_chave IS DISTINCT FROM v.remetente_chave
    OR p.id = v.pedido_origem_id OR p.chat_message_id = v.mensagem_origem_id THEN
    RAISE EXCEPTION 'atribuicao_sem_permissao' USING ERRCODE='42501';
  END IF;
  SELECT value INTO i FROM jsonb_array_elements(private.wa_agente_atribuicoes_itens(v.alvo,v.novo))
    WHERE (value->>'cliente_id')::uuid=p_client_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'atribuicao_sem_permissao' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM public.wa_agente_membros WHERE id=p.membro_id AND tenant_id=p.tenant_id
    AND user_id=p.user_id AND telefone_chave=p.remetente_chave AND ativo IS TRUE FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'atribuicao_sem_permissao' USING ERRCODE='42501'; END IF;
  SELECT * INTO u FROM public.users WHERE id=p.user_id AND tenant_id=p.tenant_id
    AND ativo IS TRUE AND perfil IS DISTINCT FROM 'cliente' FOR SHARE;
  IF NOT FOUND OR NOT coalesce(public.has_permissao_de(p.user_id,'automacoes-wa','admin'),false)
    OR NOT coalesce(public.has_permissao_de(p.user_id,'clientes.atribuir','editar'),false) THEN
    RAISE EXCEPTION 'atribuicao_sem_permissao' USING ERRCODE='42501';
  END IF;
  RETURN jsonb_build_object('tenant_id',p.tenant_id,'ator_id',p.user_id,'ator_nome',u.nome,
    'proposta_id',v.id,'pedido_id',p.id,'item',i,'origem','iris_whatsapp');
END;
$function$
;

CREATE OR REPLACE FUNCTION private.client_assignment_iris_operacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE c jsonb; i jsonb; esperado jsonb;
BEGIN
  IF auth.uid() IS NOT NULL THEN
    IF NEW.origem IS DISTINCT FROM 'desk_rpc' THEN RAISE EXCEPTION 'atribuicao_sem_permissao' USING ERRCODE='42501'; END IF;
    RETURN NEW;
  END IF;
  c:=private.client_assignment_report_contexto_20261105(NEW.client_id);
  IF c IS NOT NULL THEN
    i:=c->'item';
    esperado:=jsonb_build_object('acao',i->>'acao','tipo','estrategista',
      'assignment_id',(i->>'assignment_id')::uuid,'user_id',(i->>'user_id')::uuid,
      'revisao_esperada',i->'expected_revision','motivo',c->>'motivo');
    IF NEW.tenant_id IS DISTINCT FROM (c->>'tenant_id')::uuid OR NEW.ator_id IS DISTINCT FROM (c->>'ator_id')::uuid
      OR NEW.idempotencia IS DISTINCT FROM (c->>'proposta_id')::uuid OR NEW.pedido IS DISTINCT FROM esperado
      OR NEW.transacao IS DISTINCT FROM txid_current() OR NEW.resposta IS NOT NULL
      OR NEW.acao IS DISTINCT FROM (esperado->>'acao') OR NEW.motivo IS DISTINCT FROM (esperado->>'motivo') THEN
      RAISE EXCEPTION 'manutencao_operacao_fora_lote' USING ERRCODE='42501';
    END IF;
    NEW.origem:='manutencao_codex';
    RETURN NEW;
  END IF;
  c:=private.client_assignment_iris_contexto(NEW.client_id); i:=c->'item';
  esperado:=jsonb_build_object('acao',CASE WHEN i->>'assignment_id' IS NULL THEN 'adicionar' ELSE 'trocar' END,
    'tipo','estrategista','assignment_id',(i->>'assignment_id')::uuid,'user_id',(i->>'user_id')::uuid,
    'revisao_esperada',i->'expected_revision','motivo','Confirmação explícita de responsáveis pela Íris no WhatsApp.');
  IF NEW.tenant_id IS DISTINCT FROM (c->>'tenant_id')::uuid OR NEW.ator_id IS DISTINCT FROM (c->>'ator_id')::uuid
    OR NEW.idempotencia IS DISTINCT FROM (c->>'proposta_id')::uuid OR NEW.pedido IS DISTINCT FROM esperado
    OR NEW.transacao IS DISTINCT FROM txid_current() OR NEW.resposta IS NOT NULL
    OR NEW.acao IS DISTINCT FROM (esperado->>'acao') OR NEW.motivo IS DISTINCT FROM (esperado->>'motivo') THEN
    RAISE EXCEPTION 'atribuicao_sem_permissao' USING ERRCODE='42501';
  END IF;
  NEW.origem:='iris_whatsapp';
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.client_assignment_reconciliar_report_20261105()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '5s'
 SET statement_timeout TO '30s'
AS $function$
DECLARE r private.client_assignment_report_20261105%ROWTYPE; c jsonb; resultado jsonb;
  n integer; rev bigint; ids uuid[]; pessoas uuid[];
BEGIN
  IF session_user NOT IN ('postgres','supabase_admin') OR current_user NOT IN ('postgres','supabase_admin') OR auth.uid() IS NOT NULL THEN
    RAISE EXCEPTION 'manutencao_sessao_administrativa_exigida' USING ERRCODE='42501';
  END IF;
  PERFORM 1 FROM private.client_assignment_report_20261105 ORDER BY client_id FOR UPDATE;
  GET DIAGNOSTICS n=ROW_COUNT;
  IF n<>11 THEN RAISE EXCEPTION 'manutencao_lote_incompleto' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM private.client_assignment_report_20261105 WHERE backend_pid IS NOT NULL OR transacao IS NOT NULL) THEN
    RAISE EXCEPTION 'manutencao_contexto_ja_ativo' USING ERRCODE='42501';
  END IF;
  SELECT array_agg(client_id ORDER BY client_id) INTO ids FROM private.client_assignment_report_20261105;
  PERFORM id FROM public.clients WHERE tenant_id='00000000-0000-0000-0000-000000000001' AND id=ANY(ids) ORDER BY id FOR UPDATE;
  GET DIAGNOSTICS n=ROW_COUNT;
  IF n<>11 THEN RAISE EXCEPTION 'manutencao_cliente_ausente' USING ERRCODE='42501'; END IF;
  SELECT array_agg(DISTINCT pessoa) INTO pessoas FROM (
    SELECT user_id AS pessoa FROM private.client_assignment_report_20261105 WHERE user_id IS NOT NULL
    UNION ALL SELECT solicitante_id FROM private.client_assignment_report_20261105
    UNION ALL SELECT user_id FROM public.client_assignments WHERE client_id=ANY(ids)
  ) x;
  PERFORM id FROM public.users WHERE tenant_id='00000000-0000-0000-0000-000000000001' AND id=ANY(pessoas) ORDER BY id FOR SHARE;
  PERFORM client_id FROM public.client_assignment_state WHERE client_id=ANY(ids) ORDER BY client_id FOR UPDATE;
  PERFORM id FROM public.client_assignments WHERE client_id=ANY(ids) ORDER BY client_id,id FOR UPDATE;

  -- Primeiro confere o lote inteiro. Mudança concorrente falha sem aplicar subset.
  FOR r IN SELECT * FROM private.client_assignment_report_20261105 ORDER BY client_id LOOP
    UPDATE private.client_assignment_report_20261105 SET backend_pid=pg_backend_pid(),transacao=txid_current(),
      executor_sql=session_user,iniciado_em=coalesce(iniciado_em,clock_timestamp()) WHERE client_id=r.client_id AND recibo IS NULL;
    IF r.recibo IS NOT NULL THEN
      -- Retry de lote concluído devolve somente recibos que constam no ledger.
      PERFORM 1 FROM public.client_assignment_operations op WHERE op.tenant_id=r.tenant_id AND op.client_id=r.client_id
        AND op.ator_id=r.solicitante_id AND op.idempotencia=r.idempotencia AND op.origem='manutencao_codex'
        AND op.resposta=r.recibo;
      IF NOT FOUND THEN RAISE EXCEPTION 'manutencao_recibo_divergente' USING ERRCODE='40001'; END IF;
      CONTINUE;
    END IF;
    c:=private.client_assignment_report_contexto_20261105(r.client_id);
    IF c IS NULL THEN RAISE EXCEPTION 'manutencao_contexto_ausente' USING ERRCODE='42501'; END IF;
    PERFORM 1 FROM public.wa_agente_pedidos p
      JOIN public.chat_messages m ON m.id=p.chat_message_id AND m.tenant_id=p.tenant_id
      WHERE p.id=r.pedido_fonte_id AND p.tenant_id=r.tenant_id AND p.eh_grupo IS TRUE
        AND m.id=r.mensagem_fonte_id AND p.chat_jid='120363415422487266@g.us'
        AND p.chat_jid=(SELECT principal.chat_jid FROM public.wa_agente_pedidos principal
          WHERE principal.id='b24d7590-d7b8-44ec-aa9c-ad3475d5c746'::uuid
            AND principal.chat_message_id='1583771d-b531-4d0d-bfce-85668eb107c8'::uuid
            AND principal.tenant_id=r.tenant_id AND principal.eh_grupo IS TRUE
            AND principal.chat_jid='120363415422487266@g.us');
    IF NOT FOUND THEN RAISE EXCEPTION 'manutencao_fonte_ausente' USING ERRCODE='42501'; END IF;
    SELECT coalesce((SELECT revisao FROM public.client_assignment_state WHERE tenant_id=r.tenant_id AND client_id=r.client_id),0) INTO rev;
    IF rev<>r.revisao_esperada THEN RAISE EXCEPTION 'manutencao_revisao_alterada' USING ERRCODE='40001'; END IF;
    SELECT count(*) INTO n FROM public.client_assignments WHERE tenant_id=r.tenant_id AND client_id=r.client_id AND tipo='estrategista' AND ativo IS TRUE;
    IF (r.assignment_id IS NULL AND n<>0) OR (r.assignment_id IS NOT NULL AND n<>1) THEN
      RAISE EXCEPTION 'manutencao_vinculos_alterados' USING ERRCODE='40001';
    END IF;
    IF r.assignment_id IS NOT NULL THEN
      PERFORM 1 FROM public.client_assignments WHERE id=r.assignment_id AND tenant_id=r.tenant_id AND client_id=r.client_id AND tipo='estrategista' AND ativo IS TRUE;
      IF NOT FOUND THEN RAISE EXCEPTION 'manutencao_vinculo_alterado' USING ERRCODE='40001'; END IF;
    END IF;
    IF r.user_id IS NOT NULL THEN
      PERFORM 1 FROM public.users WHERE id=r.user_id AND tenant_id=r.tenant_id AND ativo IS TRUE;
      IF NOT FOUND OR NOT coalesce(private.client_assignment_elegivel(r.tenant_id,r.user_id,'estrategista'),false) THEN
        RAISE EXCEPTION 'manutencao_destino_inelegivel' USING ERRCODE='42501';
      END IF;
    END IF;
  END LOOP;
  FOR r IN SELECT * FROM private.client_assignment_report_20261105 WHERE recibo IS NULL ORDER BY client_id LOOP
    c:=private.client_assignment_report_contexto_20261105(r.client_id);
    IF c IS NULL THEN RAISE EXCEPTION 'manutencao_contexto_ausente' USING ERRCODE='42501'; END IF;
    resultado:=public.client_assignment_decidir(r.client_id,r.acao,'estrategista',r.assignment_id,r.user_id,
      r.revisao_esperada,r.idempotencia,c->>'motivo');
    IF resultado->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'manutencao_resultado_nao_confirmado' USING ERRCODE='40001'; END IF;
    UPDATE private.client_assignment_report_20261105 SET recibo=resultado,executado_em=clock_timestamp(),
      backend_pid=NULL,transacao=NULL WHERE client_id=r.client_id;
  END LOOP;
  SELECT jsonb_agg(jsonb_build_object('cliente_id',client_id,'rotulo',rotulo,'acao',acao,
    'solicitante_id',solicitante_id,'executor_sql',executor_sql,'executado_em',executado_em,'recibo',recibo) ORDER BY client_id)
    INTO resultado FROM private.client_assignment_report_20261105;
  RETURN jsonb_build_object('ok',true,'origem','manutencao_codex','itens',resultado);
END;
$function$
;

CREATE OR REPLACE FUNCTION private.client_assignment_report_contexto_20261105(p_client_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r private.client_assignment_report_20261105%ROWTYPE; u public.users%ROWTYPE;
  total boolean; ids uuid[];
BEGIN
  IF session_user NOT IN ('postgres','supabase_admin') OR auth.uid() IS NOT NULL THEN RETURN NULL; END IF;
  SELECT * INTO r FROM private.client_assignment_report_20261105
    WHERE client_id=p_client_id AND backend_pid=pg_backend_pid() AND transacao=txid_current()
      AND executor_sql=session_user AND recibo IS NULL;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT * INTO u FROM public.users WHERE id=r.solicitante_id AND tenant_id=r.tenant_id
    AND ativo IS TRUE AND perfil <> 'cliente' FOR SHARE;
  IF NOT FOUND OR NOT coalesce(public.has_permissao_de(u.id,'clientes.atribuir','editar'),false) THEN
    RAISE EXCEPTION 'manutencao_solicitante_sem_alcada' USING ERRCODE='42501';
  END IF;
  SELECT s.total,s.client_ids INTO total,ids FROM public.wa_agente_escopo(r.tenant_id,r.solicitante_id) s;
  IF total IS NOT TRUE AND NOT (r.client_id=ANY(coalesce(ids,'{}'::uuid[]))) THEN
    RAISE EXCEPTION 'manutencao_cliente_fora_escopo' USING ERRCODE='42501';
  END IF;
  RETURN jsonb_build_object('tenant_id',r.tenant_id,'ator_id',r.solicitante_id,'ator_nome',u.nome,
    'origem','manutencao_codex','proposta_id',r.idempotencia,'executor_sql',r.executor_sql,
    'motivo','Manutenção Codex autorizada por Bruno em 05/11/2026; executor SQL: '||r.executor_sql||'; pedido fonte: '||r.pedido_fonte_id::text||'; mensagem fonte: '||r.mensagem_fonte_id::text||'.',
    'item',jsonb_build_object('cliente_id',r.client_id,'acao',r.acao,'assignment_id',r.assignment_id,
      'user_id',r.user_id,'expected_revision',r.revisao_esperada));
END;
$function$
;

CREATE OR REPLACE FUNCTION private.cliente_canais_do_cliente(p_tenant uuid, p_client uuid)
 RETURNS TABLE(tipo text, chave text, rotulo text, status text)
 LANGUAGE sql
 STABLE ROWS 10
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH conf AS (
    SELECT c.tipo, c.chave, min(c.criado_em) AS desde
      FROM public.cliente_canais c
     WHERE c.tenant_id = p_tenant AND c.client_id = p_client AND c.status = 'confirmado'
     GROUP BY c.tipo, c.chave
  ),
  chat AS (
    SELECT private.canal_tipo(ct.numero_whatsapp, ct.group_size) AS tipo,
           private.canal_chave(ct.numero_whatsapp, ct.group_size) AS chave
      FROM public.chat_contacts ct
     WHERE ct.tenant_id = p_tenant AND ct.client_id = p_client
    UNION
    SELECT private.canal_tipo(ct.numero_whatsapp, ct.group_size),
           private.canal_chave(ct.numero_whatsapp, ct.group_size)
      FROM public.chat_contact_clients cc
      JOIN public.chat_contacts ct ON ct.id = cc.contact_id AND ct.tenant_id = p_tenant
     WHERE cc.tenant_id = p_tenant AND cc.client_id = p_client
  ),
  todos AS (
    SELECT conf.tipo, conf.chave, 'confirmado'::text AS status, conf.desde FROM conf
    UNION ALL
    SELECT chat.tipo, chat.chave, 'vinculo_chat'::text, NULL::timestamptz
      FROM chat
     WHERE chat.tipo IS NOT NULL AND chat.chave IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM conf WHERE conf.tipo = chat.tipo AND conf.chave = chat.chave)
       AND NOT EXISTS (
         SELECT 1 FROM public.cliente_canais r
          WHERE r.tenant_id = p_tenant AND r.tipo = chat.tipo AND r.chave = chat.chave
            AND r.client_id = p_client AND r.status = 'rejeitado')
  )
  SELECT t.tipo, t.chave,
         CASE WHEN t.tipo = 'grupo' THEN 'G' ELSE 'P' END
           || row_number() OVER (PARTITION BY t.tipo ORDER BY t.desde NULLS LAST, t.chave)::text,
         t.status
    FROM todos t
   WHERE p_tenant IS NOT NULL AND p_client IS NOT NULL
     AND NOT private.cliente_canal_excluido(p_tenant, t.tipo, t.chave)
$function$
;

CREATE OR REPLACE FUNCTION private.cliente_canal_excluido(p_tenant uuid, p_tipo text, p_chave text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT p_tenant IS NULL OR p_chave IS NULL OR p_tipo IS NULL OR p_tipo NOT IN ('grupo', 'privado')
    -- decisão do canal: grupo interno / não é cliente
    OR EXISTS (
      SELECT 1 FROM public.cliente_canais c
       WHERE c.tenant_id = p_tenant AND c.tipo = p_tipo AND c.chave = p_chave
         AND c.client_id IS NULL AND c.status IN ('interno', 'nao_cliente'))
    -- qualquer cópia do canal marcada como restrita (grupo interno) no Chat
    OR EXISTS (
      SELECT 1 FROM public.chat_contacts ct
       WHERE ct.tenant_id = p_tenant AND ct.restrito_admin
         AND ct.numero_whatsapp = ANY (private.canal_formas(p_tipo, p_chave)))
    OR (p_tipo = 'grupo' AND (
         EXISTS (SELECT 1 FROM public.chat_grupos_restritos g
                  WHERE g.tenant_id = p_tenant AND private.canal_chave(g.grupo_base, 1) = p_chave)
         OR EXISTS (SELECT 1 FROM public.wa_agente_grupos g
                     WHERE g.tenant_id = p_tenant AND private.canal_chave(g.grupo_jid, 1) = p_chave)
         OR EXISTS (SELECT 1 FROM public.wa_auto_gestores g
                     WHERE g.tenant_id = p_tenant AND g.grupo_jid IS NOT NULL
                       AND private.canal_chave(g.grupo_jid, 1) = p_chave)))
    OR (p_tipo = 'privado' AND (
         EXISTS (SELECT 1 FROM public.wa_auto_gestores g
                  WHERE g.tenant_id = p_tenant AND g.grupo_jid IS NULL
                    AND private.canal_chave(g.telefone) = p_chave)
         OR EXISTS (SELECT 1 FROM public.wa_agente_membros m
                     WHERE m.tenant_id = p_tenant AND private.canal_chave(m.telefone_chave) = p_chave)
         OR EXISTS (SELECT 1 FROM public.equipe_identidades e
                     WHERE e.tenant_id = p_tenant AND e.ativo AND e.telefone_norm = p_chave)))
$function$
;

CREATE OR REPLACE FUNCTION private.clientes_por_telefone(p_tenant uuid, p_cmp text)
 RETURNS uuid[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(array_agg(DISTINCT x.id ORDER BY x.id), '{}'::uuid[])
    FROM (
      SELECT cl.id
        FROM public.clients cl
       WHERE p_tenant IS NOT NULL AND p_cmp IS NOT NULL
         AND cl.tenant_id = p_tenant
         AND (private.tel_cmp_cadastro(cl.telefone) = p_cmp
              OR private.tel_cmp_cadastro(cl.whatsapp) = p_cmp)
      UNION
      SELECT cl.id
        FROM public.contratos co
        JOIN public.clients cl ON cl.id = co.cliente_id AND cl.tenant_id = p_tenant
       WHERE p_tenant IS NOT NULL AND p_cmp IS NOT NULL
         AND co.tenant_id = p_tenant
         AND private.tel_cmp_cadastro(co.whatsapp) = p_cmp
    ) x
$function$
;

CREATE OR REPLACE FUNCTION private.marcar_grupo_restrito(p_tenant_id uuid, p_grupo text, p_origem text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_base TEXT;
  v_n    INTEGER := 0;
BEGIN
  IF p_tenant_id IS NULL OR p_grupo IS NULL THEN
    RETURN 0;
  END IF;
  v_base := lower(btrim(p_grupo));
  IF right(v_base, 5) = '@g.us' THEN
    v_base := left(v_base, length(v_base) - 5);
  END IF;
  IF length(v_base) > 60
     OR v_base !~ '^(120363[0-9]{9,15}|[1-9][0-9]{9,14}-[0-9]{9,11})$' THEN
    RETURN 0; -- não é grupo real: nada a marcar (o CHECK de wa_auto_gestores já recusa)
  END IF;

  INSERT INTO public.chat_grupos_restritos (tenant_id, grupo_base, origem)
  VALUES (p_tenant_id, v_base, COALESCE(p_origem, 'manual'))
  ON CONFLICT (tenant_id, grupo_base) DO NOTHING;

  UPDATE public.chat_contacts c
     SET restrito_admin = true
   WHERE c.tenant_id = p_tenant_id
     AND lower(btrim(c.numero_whatsapp)) IN (v_base, v_base || '@g.us')
     AND NOT c.restrito_admin;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.tel_cmp_cadastro(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  d TEXT := ltrim(regexp_replace(coalesce(p, ''), '[^0-9]', '', 'g'), '0');
BEGIN
  IF d ~ '^55[1-9][0-9][0-9]{8,9}$' THEN
    RETURN 'br' || substr(d, 3, 2) || right(d, 8);
  END IF;
  IF d ~ '^[1-9][0-9][0-9]{8,9}$' THEN
    RETURN 'br' || left(d, 2) || right(d, 8);
  END IF;
  IF length(d) BETWEEN 12 AND 15 THEN
    RETURN 'x' || d;
  END IF;
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.tel_cmp_contato(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  d TEXT := regexp_replace(coalesce(p, ''), '[^0-9]', '', 'g');
BEGIN
  IF d ~ '^55[1-9][0-9][0-9]{8,9}$' THEN
    RETURN 'br' || substr(d, 3, 2) || right(d, 8);
  END IF;
  IF length(d) BETWEEN 8 AND 15 THEN
    RETURN 'x' || d;
  END IF;
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.tempo_resposta_agenda_fixar()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE agenda jsonb; desde timestamptz; ate timestamptz; busy jsonb; instante timestamptz:=clock_timestamp();
BEGIN
  IF OLD.estado='aberto' AND NEW.estado<>'aberto' THEN
    agenda:=private.tempo_resposta_agenda_projetar(NEW.tenant_id,NEW.responsavel_id);
    IF agenda->>'status'='connected' THEN
      IF (agenda->>'synced_at')::timestamptz<instante-interval '5 minutes'
        OR (agenda->>'synced_at')::timestamptz>instante+interval '30 seconds' THEN
        agenda:=jsonb_build_object('status','unavailable');
      ELSE
        SELECT inicio INTO desde FROM public.tempo_resposta_segmentos
          WHERE tenant_id=NEW.tenant_id AND episodio_id=NEW.id AND id=NEW.segmento_atual_id;
        desde:=coalesce(desde,NEW.inicio); ate:=coalesce(NEW.resposta_em,NEW.atualizado_em,instante);
        -- Armazena só os blocos que intersectam a responsabilidade encerrada.
        SELECT coalesce(jsonb_agg(jsonb_build_object('start',greatest((q->>'start')::timestamptz,desde),
          'end',least((q->>'end')::timestamptz,ate)) ORDER BY (q->>'start')::timestamptz),'[]'::jsonb) INTO busy
          FROM jsonb_array_elements(agenda->'busy') q WHERE (q->>'start')::timestamptz<ate AND (q->>'end')::timestamptz>desde;
        agenda:=jsonb_set(agenda,'{busy}',busy);
      END IF;
    END IF;
    NEW.agenda_no_encerramento:=agenda;
  ELSIF NEW.agenda_no_encerramento IS DISTINCT FROM OLD.agenda_no_encerramento THEN
    RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='tempo_resposta_agenda_historico_imutavel';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.tempo_resposta_agenda_projetar(p_tenant uuid, p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE linhas jsonb; qtd integer; a jsonb;
BEGIN
  SELECT coalesce(jsonb_agg(to_jsonb(g)),'[]'::jsonb),count(*) INTO linhas,qtd
    FROM public.tempo_resposta_agendas g JOIN public.iris_gt3_connections c ON c.id=g.connection_id AND c.tenant_id=g.tenant_id
    JOIN public.iris_gt3_recipients r ON r.id=g.recipient_id AND r.connection_id=c.id AND r.tenant_id=c.tenant_id
    WHERE g.tenant_id=p_tenant AND g.desk_user_id=p_user AND r.desk_user_id=p_user AND r.gt3_user_id=g.gt3_user_id
      AND r.revisao=g.recipient_revisao AND r.ativo AND NOT r.modo_teste AND c.ativo AND c.revoked_at IS NULL AND c.expires_at>clock_timestamp();
  IF qtd=0 THEN RETURN jsonb_build_object('status','not_connected'); END IF;
  IF qtd<>1 THEN RETURN jsonb_build_object('status','incomplete'); END IF;
  a:=linhas->0;
  IF a->>'status'='disconnected' AND (a->>'ja_conectada')::boolean IS NOT TRUE THEN RETURN jsonb_build_object('status','not_connected'); END IF;
  IF a->>'status'='disconnected' THEN RETURN jsonb_build_object('status','disconnected','disconnected_at',a->'desconectado_em'); END IF;
  IF a->>'status'<>'connected' THEN RETURN jsonb_build_object('status','unavailable'); END IF;
  RETURN jsonb_build_object('status','connected','from',a->'inicio','to',a->'fim','synced_at',a->'sincronizado_em','busy',a->'ocupados');
END;
$function$
;

CREATE OR REPLACE FUNCTION private.tempo_resposta_alerta_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF TG_OP='UPDATE' AND (to_jsonb(NEW)-ARRAY['status','texto','delivery_id','updated_at']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['status','texto','delivery_id','updated_at']) THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='tempo_resposta_alerta_identidade_imutavel';
  END IF;
  IF TG_OP='INSERT' AND NOT EXISTS (SELECT 1 FROM public.iris_gt3_connections c JOIN public.iris_gt3_recipients r
    ON r.connection_id=c.id AND r.tenant_id=c.tenant_id
    JOIN public.tempo_resposta_segmentos s ON s.tenant_id=c.tenant_id AND s.id=NEW.segmento_id AND s.episodio_id=NEW.episodio_id
    WHERE c.id=NEW.connection_id AND c.tenant_id=NEW.tenant_id AND r.id=NEW.recipient_id
      AND r.gt3_user_id=NEW.gt3_user_id AND r.desk_user_id=s.user_id) THEN
    RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='tempo_resposta_alerta_incoerente';
  END IF;
  IF TG_OP='UPDATE' AND OLD.delivery_id IS NOT NULL AND NEW.delivery_id IS DISTINCT FROM OLD.delivery_id THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='tempo_resposta_delivery_imutavel';
  END IF;
  IF TG_OP='UPDATE' AND OLD.status IN ('enviado','sem_alertas')
    AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.texto IS DISTINCT FROM OLD.texto OR NEW.delivery_id IS DISTINCT FROM OLD.delivery_id) THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='tempo_resposta_recibo_imutavel';
  END IF;
  -- Uma resposta/troca pode cancelar no Desk após o GT3 já ter commitado. O
  -- recibo autenticado do serviço registra a entrega real, sem reabrir o caso.
  IF TG_OP='UPDATE' AND OLD.status='cancelado' AND NEW.status<>'cancelado'
    AND NOT (NEW.status='enviado' AND NEW.delivery_id IS NOT NULL AND length(trim(coalesce(NEW.texto,'')))>0) THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='tempo_resposta_recibo_imutavel';
  END IF;
  NEW.updated_at:=clock_timestamp();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.tempo_resposta_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='tempo_resposta_historico_imutavel';
END;
$function$
;

CREATE OR REPLACE FUNCTION private.tempo_resposta_assignment_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.client_assignments;
BEGIN
  IF TG_OP='DELETE' THEN a:=OLD; ELSE a:=NEW; END IF;
  IF a.tipo='estrategista' THEN PERFORM private.tempo_resposta_sincronizar_titular(a.tenant_id,a.client_id); END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.tempo_resposta_autorizar()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u record;
BEGIN
  SELECT id,tenant_id,nome INTO u FROM public.users
   WHERE id=auth.uid() AND tenant_id=public.get_user_tenant_id() AND ativo IS TRUE
     AND perfil IN ('admin','gerente') FOR SHARE;
  IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.user_id=u.id AND p.tenant_id=u.tenant_id)
    OR NOT coalesce(public.has_permissao('automacoes-wa','admin'),false) THEN
    RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='tempo_resposta_sem_permissao';
  END IF;
  RETURN jsonb_build_object('tenant_id',u.tenant_id,'ator_id',u.id,'ator_nome',u.nome);
END;
$function$
;

CREATE OR REPLACE FUNCTION private.tempo_resposta_instancia_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.status IS DISTINCT FROM 'conectado' OR NEW.ativo IS DISTINCT FROM true THEN
    UPDATE public.tempo_resposta_episodios SET qualidade='inconclusiva',motivo='conexao_interrompida',atualizado_em=clock_timestamp()
      WHERE tenant_id=NEW.tenant_id AND instance_id=NEW.id AND estado='aberto';
    UPDATE public.tempo_resposta_alertas a SET status='cancelado',updated_at=clock_timestamp()
      WHERE a.tenant_id=NEW.tenant_id AND a.status IN ('pendente','falhou') AND EXISTS
        (SELECT 1 FROM public.tempo_resposta_episodios e WHERE e.tenant_id=NEW.tenant_id AND e.id=a.episodio_id AND e.instance_id=NEW.id AND e.estado='aberto');
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.tempo_resposta_projetar(p_tenant uuid, p_episodio uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE ep public.tempo_resposta_episodios; cv public.chat_conversations; qualidade text; motivo text; segmentos jsonb; alertas jsonb;
BEGIN
  SELECT * INTO ep FROM public.tempo_resposta_episodios WHERE tenant_id=p_tenant AND id=p_episodio;
  IF NOT FOUND THEN RETURN NULL; END IF;
  qualidade:=ep.qualidade; motivo:=ep.motivo;
  SELECT * INTO cv FROM public.chat_conversations WHERE tenant_id=p_tenant AND id=ep.conversation_id;
  IF ep.estado='aberto' AND (cv.id IS NULL OR ep.instance_id IS DISTINCT FROM cv.instance_id OR cv.status='encerrada' OR cv.arquivada IS TRUE
    OR ep.client_id IS DISTINCT FROM private.tempo_resposta_resolver_cliente(p_tenant,cv.contact_id)
    OR (ep.client_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.clients c WHERE c.id=ep.client_id AND c.tenant_id=p_tenant AND c.ativo IS TRUE))) THEN
    qualidade:='inconclusiva'; motivo:='conversa_ou_vinculo_alterado';
  END IF;
  IF ep.estado='aberto' AND (ep.responsavel_id IS NULL OR ep.responsavel_id IS DISTINCT FROM private.tempo_resposta_resolver_titular(p_tenant,ep.client_id)) THEN
    qualidade:='inconclusiva'; motivo:='titular_indefinido';
  END IF;
  IF ep.estado='aberto' AND NOT EXISTS (SELECT 1 FROM public.whatsapp_instances w WHERE w.tenant_id=p_tenant
    AND w.id=ep.instance_id AND w.status='conectado' AND w.ativo IS TRUE) THEN
    qualidade:='inconclusiva'; motivo:='conexao_interrompida';
  END IF;
  IF EXISTS (SELECT 1 FROM public.chat_messages m WHERE m.tenant_id=p_tenant AND m.conversation_id=ep.conversation_id
    AND m.criado_em>=ep.inicio AND m.criado_em<=coalesce(ep.resposta_em,clock_timestamp())
    AND coalesce(m.tipo,'') NOT IN ('sistema','reacao','reaction') AND coalesce(m.autor_tipo,'') NOT IN ('ia','sistema')
    AND m.enviado_por_ia IS DISTINCT FROM true AND coalesce(m.status_envio,'') NOT IN ('enviando','falha')
    AND NOT EXISTS (SELECT 1 FROM public.tempo_resposta_ingressos i WHERE i.tenant_id=p_tenant AND i.mensagem_id=m.id AND i.confiavel)) THEN
    qualidade:='inconclusiva'; motivo:='mensagem_sem_comprovacao';
  END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.inicio,s.id),'[]'::jsonb) INTO segmentos
    FROM public.tempo_resposta_segmentos s WHERE s.tenant_id=p_tenant AND s.episodio_id=ep.id;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'etapa',a.etapa,'status',a.status,'created_at',a.created_at,'texto',a.texto) ORDER BY a.created_at,a.id),'[]'::jsonb)
    INTO alertas FROM public.tempo_resposta_alertas a WHERE a.tenant_id=p_tenant AND a.episodio_id=ep.id;
  RETURN (to_jsonb(ep)-'agenda_no_encerramento')||jsonb_build_object('cliente',coalesce(ep.cliente_nome,'Conversa sem cliente confirmado'),
    'responsavel',ep.responsavel_nome,'respondente',ep.respondente_nome,'qualidade',qualidade,'motivo',motivo,'segmentos',segmentos,'historico_alertas',alertas,
    'agenda',CASE WHEN ep.estado='aberto' THEN private.tempo_resposta_agenda_projetar(p_tenant,ep.responsavel_id)
      ELSE coalesce(ep.agenda_no_encerramento,jsonb_build_object('status','not_connected')) END);
END;
$function$
;

CREATE OR REPLACE FUNCTION private.tempo_resposta_resolver_cliente(p_tenant uuid, p_contact uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE ct record; ids uuid[]; tp text; ch text;
BEGIN
  SELECT * INTO ct FROM public.chat_contacts WHERE id=p_contact AND tenant_id=p_tenant;
  IF NOT FOUND THEN RETURN NULL; END IF;
  tp:=private.canal_tipo(ct.numero_whatsapp,ct.group_size); ch:=private.canal_chave(ct.numero_whatsapp,ct.group_size);
  IF coalesce(ct.restrito_admin,false) OR private.cliente_canal_excluido(p_tenant,tp,ch) THEN RETURN NULL; END IF;
  SELECT array_agg(DISTINCT c.client_id) INTO ids FROM public.cliente_canais c
   WHERE c.tenant_id=p_tenant AND c.tipo=tp AND c.chave=ch AND c.status='confirmado';
  IF cardinality(ids)>0 THEN
    IF cardinality(ids)=1 THEN RETURN ids[1]; END IF;
    RETURN NULL;
  END IF;
  SELECT array_agg(DISTINCT v.client_id) INTO ids FROM (
    SELECT ct.client_id WHERE ct.client_id IS NOT NULL
    UNION SELECT cc.client_id FROM public.chat_contact_clients cc WHERE cc.tenant_id=p_tenant AND cc.contact_id=p_contact
  ) v WHERE NOT EXISTS (SELECT 1 FROM public.cliente_canais r WHERE r.tenant_id=p_tenant
    AND r.client_id=v.client_id AND r.tipo=tp AND r.chave=ch AND r.status='rejeitado');
  IF cardinality(ids)=1 THEN RETURN ids[1]; END IF;
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.tempo_resposta_resolver_titular(p_tenant uuid, p_client uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  WITH candidatos AS (
    SELECT DISTINCT a.user_id FROM public.client_assignments a JOIN public.users u
      ON u.id=a.user_id AND u.tenant_id=a.tenant_id AND u.ativo IS TRUE AND u.perfil<>'cliente'
     WHERE a.tenant_id=p_tenant AND a.client_id=p_client AND a.tipo='estrategista' AND a.ativo IS TRUE
  ), escolhido AS (
    SELECT t.user_id FROM public.tempo_resposta_titulares t JOIN candidatos c ON c.user_id=t.user_id
     WHERE t.tenant_id=p_tenant AND t.client_id=p_client
  )
  SELECT coalesce((SELECT user_id FROM escolhido),
    (SELECT (array_agg(user_id))[1] FROM candidatos HAVING count(*)=1))
$function$
;

CREATE OR REPLACE FUNCTION private.tempo_resposta_sincronizar_titular(p_tenant uuid, p_client uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE ep public.tempo_resposta_episodios; titular uuid; nome text; sid uuid; instante timestamptz:=clock_timestamp(); rev bigint; ator uuid:=auth.uid(); ctx jsonb;
BEGIN
  IF ator IS NULL THEN
    ctx:=private.client_assignment_report_contexto_20261105(p_client);
    IF ctx IS NOT NULL THEN
      IF (ctx->>'tenant_id')::uuid IS DISTINCT FROM p_tenant THEN
        RAISE EXCEPTION 'manutencao_cliente_fora_escopo' USING ERRCODE='42501';
      END IF;
      ator:=(ctx->>'ator_id')::uuid;
    END IF;
  END IF;
  -- Só a ponte confirmada fornece ator para chamada sem sessão. Rotinas
  -- automáticas sem contexto mantêm sua auditoria anterior, sem impersonação.
  IF ator IS NULL AND EXISTS (SELECT 1 FROM private.client_assignment_iris_context
    WHERE backend_pid=pg_backend_pid() AND transacao=txid_current()) THEN
    ctx:=private.client_assignment_iris_contexto(p_client);
    IF (ctx->>'tenant_id')::uuid IS DISTINCT FROM p_tenant THEN
      RAISE EXCEPTION 'atribuicao_sem_permissao' USING ERRCODE='42501';
    END IF;
    ator:=(ctx->>'ator_id')::uuid;
  END IF;
  titular:=private.tempo_resposta_resolver_titular(p_tenant,p_client);
  SELECT u.nome INTO nome FROM public.users u WHERE u.tenant_id=p_tenant AND u.id=titular;
  SELECT revisao INTO rev FROM public.client_assignment_state WHERE tenant_id=p_tenant AND client_id=p_client;
  FOR ep IN SELECT * FROM public.tempo_resposta_episodios
    WHERE tenant_id=p_tenant AND client_id=p_client AND estado='aberto' ORDER BY id FOR UPDATE LOOP
    IF ep.responsavel_id IS NOT DISTINCT FROM titular THEN CONTINUE; END IF;
    UPDATE public.tempo_resposta_segmentos SET fim=greatest(inicio,instante)
     WHERE tenant_id=p_tenant AND episodio_id=ep.id AND fim IS NULL;
    UPDATE public.tempo_resposta_alertas SET status='cancelado',updated_at=instante
     WHERE tenant_id=p_tenant AND episodio_id=ep.id AND status IN ('pendente','falhou');
    sid:=NULL;
    IF titular IS NOT NULL THEN
      INSERT INTO public.tempo_resposta_segmentos(tenant_id,episodio_id,user_id,nome,inicio,assignment_revision)
        VALUES(p_tenant,ep.id,titular,coalesce(nome,'Estrategista'),greatest(ep.inicio,instante),coalesce(rev,0)) RETURNING id INTO sid;
    END IF;
    UPDATE public.tempo_resposta_episodios SET responsavel_id=titular,responsavel_nome=nome,
      segmento_atual_id=sid,atualizado_em=instante,
      qualidade=CASE WHEN motivo='titular_indefinido' AND titular IS NOT NULL THEN 'confiavel' ELSE qualidade END,
      motivo=CASE WHEN motivo='titular_indefinido' AND titular IS NOT NULL THEN NULL ELSE motivo END
      WHERE tenant_id=p_tenant AND id=ep.id;
    INSERT INTO public.tempo_resposta_auditoria(tenant_id,ator_id,acao,dados)
      VALUES(p_tenant,ator,'troca_titular',jsonb_build_object('episodio_id',ep.id,'anterior',ep.responsavel_id,'novo',titular,'segmento_id',sid)
        || CASE WHEN ctx IS NULL THEN '{}'::jsonb
        WHEN ctx->>'origem'='manutencao_codex' THEN jsonb_build_object('origem','manutencao_codex',
          'operacao_manutencao_id',ctx->'proposta_id','executor_sql',ctx->'executor_sql')
        ELSE jsonb_build_object('origem','iris_whatsapp',
          'proposta_id',ctx->'proposta_id','pedido_confirmacao_id',ctx->'pedido_id') END);
  END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.vinculo_do_chat(p_contato uuid, p_cliente uuid, p_ligar boolean)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid    UUID := auth.uid();
  v_ct     RECORD;
  v_tipo   TEXT;
  v_chave  TEXT;
  v_formas TEXT[];
  v_neg    BOOLEAN;
  v_gestor BOOLEAN;
  v_total  BOOLEAN;
  v_atual  TEXT;
BEGIN
  IF v_uid IS NULL OR p_contato IS NULL OR p_cliente IS NULL THEN
    RETURN 'nada';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.users u
     WHERE u.id = v_uid AND u.ativo IS TRUE AND u.perfil IS DISTINCT FROM 'cliente'
  ) THEN
    RETURN 'nada';
  END IF;

  SELECT ct.tenant_id, ct.instance_id, ct.numero_whatsapp, ct.group_size, ct.restrito_admin INTO v_ct
    FROM public.chat_contacts ct WHERE ct.id = p_contato;
  -- Contato apagado (cascata), restrito ou de outra empresa → nada.
  IF NOT FOUND OR v_ct.restrito_admin OR v_ct.tenant_id IS DISTINCT FROM public.get_user_tenant_id() THEN
    RETURN 'nada';
  END IF;
  -- Cliente apagado (cascata) ou de outra empresa → nada.
  IF NOT EXISTS (SELECT 1 FROM public.clients cl WHERE cl.id = p_cliente AND cl.tenant_id = v_ct.tenant_id) THEN
    RETURN 'nada';
  END IF;
  IF NOT COALESCE(public.user_can_access_client(p_cliente), false)
     OR NOT COALESCE(public.user_can_access_instance(v_ct.instance_id), false) THEN
    RETURN 'nada';
  END IF;

  v_tipo := private.canal_tipo(v_ct.numero_whatsapp, v_ct.group_size);
  v_chave := private.canal_chave(v_ct.numero_whatsapp, v_ct.group_size);
  IF v_chave IS NULL THEN
    RETURN 'nada';
  END IF;
  v_formas := private.canal_formas(v_tipo, v_chave);

  v_neg := EXISTS (
    SELECT 1 FROM public.cliente_canais c
     WHERE c.tenant_id = v_ct.tenant_id AND c.tipo = v_tipo AND c.chave = v_chave
       AND c.client_id IS NULL AND c.status IN ('interno', 'nao_cliente')
  );
  v_gestor := COALESCE(public.vinculos_pode_gerir(), false);
  v_total := v_gestor OR (
    NOT EXISTS (
      SELECT 1 FROM public.chat_contacts ct
       WHERE ct.tenant_id = v_ct.tenant_id
         AND ct.numero_whatsapp = ANY (v_formas)
         AND private.canal_tipo(ct.numero_whatsapp, ct.group_size) = v_tipo
         AND (ct.restrito_admin
              OR NOT COALESCE(public.user_can_access_instance(ct.instance_id), false)
              OR NOT COALESCE(public.user_can_access_client(ct.client_id), false))
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.cliente_canais c
       WHERE c.tenant_id = v_ct.tenant_id AND c.tipo = v_tipo AND c.chave = v_chave
         AND c.status = 'confirmado' AND NOT COALESCE(public.user_can_access_client(c.client_id), false)
    )
  );

  SELECT c.status INTO v_atual
    FROM public.cliente_canais c
   WHERE c.tenant_id = v_ct.tenant_id AND c.tipo = v_tipo AND c.chave = v_chave AND c.client_id = p_cliente;

  IF p_ligar THEN
    IF v_atual = 'confirmado' THEN
      RETURN 'confirmado';
    END IF;
    IF v_atual = 'rejeitado' AND NOT v_gestor THEN
      RETURN 'nada'; -- recusado na tela: só quem gere vínculos volta atrás
    END IF;
    IF v_neg OR NOT v_total THEN
      INSERT INTO public.cliente_canais (tenant_id, client_id, tipo, chave, status, origem, evidencias)
      VALUES (v_ct.tenant_id, p_cliente, v_tipo, v_chave, 'sugerido', 'manual', '{"pedido_chat":true}'::jsonb)
      ON CONFLICT (tenant_id, tipo, chave, (COALESCE(client_id, '00000000-0000-0000-0000-000000000000'::uuid)))
      DO UPDATE SET evidencias = public.cliente_canais.evidencias || '{"pedido_chat":true}'::jsonb
              WHERE public.cliente_canais.status = 'sugerido';
      RETURN 'sugerido';
    END IF;
    INSERT INTO public.cliente_canais
      (tenant_id, client_id, tipo, chave, status, origem, revisado_por, revisado_em)
    VALUES (v_ct.tenant_id, p_cliente, v_tipo, v_chave, 'confirmado', 'manual', v_uid, now())
    ON CONFLICT (tenant_id, tipo, chave, (COALESCE(client_id, '00000000-0000-0000-0000-000000000000'::uuid)))
    DO UPDATE SET status = 'confirmado', revisado_por = EXCLUDED.revisado_por, revisado_em = EXCLUDED.revisado_em;
    RETURN 'confirmado';
  END IF;

  -- Desligar
  IF v_neg OR NOT v_total OR v_atual = 'rejeitado' THEN
    RETURN 'nada';
  END IF;
  INSERT INTO public.cliente_canais
    (tenant_id, client_id, tipo, chave, status, origem, revisado_por, revisado_em)
  VALUES (v_ct.tenant_id, p_cliente, v_tipo, v_chave, 'rejeitado', 'manual', v_uid, now())
  ON CONFLICT (tenant_id, tipo, chave, (COALESCE(client_id, '00000000-0000-0000-0000-000000000000'::uuid)))
  DO UPDATE SET status = 'rejeitado', revisado_por = EXCLUDED.revisado_por, revisado_em = EXCLUDED.revisado_em;
  RETURN 'rejeitado';
END;
$function$
;

CREATE OR REPLACE FUNCTION private.vinculo_evidencias_limpas(p jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  SELECT COALESCE(jsonb_object_agg(e.k, e.v), '{}'::jsonb)
    FROM jsonb_each(CASE WHEN jsonb_typeof(p) = 'object' THEN p ELSE '{}'::jsonb END) AS e(k, v)
   WHERE (e.k = 'nome_grupo' AND jsonb_typeof(e.v) = 'string'
          AND (e.v #>> '{}') IN ('completo', 'primeiro_ultimo', 'empresa', 'razao_social', 'instagram'))
      OR (e.k = 'fonte' AND jsonb_typeof(e.v) = 'string' AND (e.v #>> '{}') IN ('cadastro', 'contrato'))
      OR (e.k = 'telefone' AND jsonb_typeof(e.v) = 'string' AND (e.v #>> '{}') IN ('unico', 'ambiguo'))
      OR (e.k IN ('membro_com_nome_do_cliente', 'instancias', 'contatos') AND jsonb_typeof(e.v) = 'number'
          AND (e.v #>> '{}')::numeric BETWEEN 0 AND 9999)
      OR (e.k IN ('contrato_vigente', 'ambiguo', 'pedido_chat') AND jsonb_typeof(e.v) = 'boolean')
$function$
;

CREATE OR REPLACE FUNCTION private.vinculo_sincronizar(p_tenant uuid, p_tipo text, p_chave text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_prev   TEXT := current_setting('omnx.vinculo_sync', true);
  v_formas TEXT[] := private.canal_formas(p_tipo, p_chave);
  v_conf   UUID[];
  v_rej    UUID[];
  v_neg    BOOLEAN;
  v_alvo   UUID[];
  v_n      INTEGER := 0;
BEGIN
  IF p_tenant IS NULL OR p_chave IS NULL OR cardinality(v_formas) = 0 THEN
    RETURN 0;
  END IF;

  SELECT COALESCE(array_agg(c.client_id ORDER BY COALESCE(c.revisado_em, c.criado_em), c.id), '{}'::uuid[])
    INTO v_conf
    FROM public.cliente_canais c
   WHERE c.tenant_id = p_tenant AND c.tipo = p_tipo AND c.chave = p_chave
     AND c.status = 'confirmado' AND c.client_id IS NOT NULL;
  SELECT COALESCE(array_agg(c.client_id), '{}'::uuid[])
    INTO v_rej
    FROM public.cliente_canais c
   WHERE c.tenant_id = p_tenant AND c.tipo = p_tipo AND c.chave = p_chave
     AND c.status = 'rejeitado' AND c.client_id IS NOT NULL;
  v_neg := EXISTS (
    SELECT 1 FROM public.cliente_canais c
     WHERE c.tenant_id = p_tenant AND c.tipo = p_tipo AND c.chave = p_chave
       AND c.client_id IS NULL AND c.status IN ('interno', 'nao_cliente')
  );
  IF v_neg THEN
    v_conf := '{}'::uuid[];
  END IF;

  SELECT COALESCE(array_agg(ct.id), '{}'::uuid[])
    INTO v_alvo
    FROM public.chat_contacts ct
   WHERE ct.tenant_id = p_tenant
     AND ct.numero_whatsapp = ANY (v_formas)
     AND NOT ct.restrito_admin
     AND private.canal_tipo(ct.numero_whatsapp, ct.group_size) = p_tipo;
  IF cardinality(v_alvo) = 0 THEN
    RETURN 0;
  END IF;

  PERFORM set_config('omnx.vinculo_sync', 'on', true);

  DELETE FROM public.chat_contact_clients cc
   WHERE cc.tenant_id = p_tenant
     AND cc.contact_id = ANY (v_alvo)
     AND (v_neg OR cc.client_id = ANY (v_rej));

  INSERT INTO public.chat_contact_clients (contact_id, client_id, tenant_id)
  SELECT a.id, c.id, p_tenant
    FROM unnest(v_alvo) AS a(id)
   CROSS JOIN unnest(v_conf) AS c(id)
  ON CONFLICT (contact_id, client_id) DO NOTHING;

  UPDATE public.chat_contacts ct
     SET client_id = x.novo
    FROM (
      SELECT ct2.id,
             CASE
               WHEN v_neg THEN NULL
               WHEN ct2.client_id IS NULL OR ct2.client_id = ANY (v_rej) THEN v_conf[1]
               ELSE ct2.client_id
             END AS novo
        FROM public.chat_contacts ct2
       WHERE ct2.id = ANY (v_alvo)
    ) x
   WHERE ct.id = x.id
     AND ct.client_id IS DISTINCT FROM x.novo;
  GET DIAGNOSTICS v_n = ROW_COUNT;

  PERFORM set_config('omnx.vinculo_sync', COALESCE(NULLIF(v_prev, ''), 'off'), true);
  RETURN v_n;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.wa_agente_acoes_estado(p wa_agente_pedidos, p_acao text, p_alvo uuid, p_novo jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_acao='cliente_estrategista' THEN RETURN private.wa_agente_atribuicoes_estado(p,p_alvo,p_novo); END IF;
  RETURN private.wa_agente_acoes_estado_cadastro(p,p_acao,p_alvo,p_novo);
END;
$function$
;

CREATE OR REPLACE FUNCTION private.wa_agente_acoes_estado_cadastro(p wa_agente_pedidos, p_acao text, p_alvo uuid, p_novo jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c public.clients%ROWTYPE;
  k public.contratos%ROWTYPE;
  v_cliente uuid;
  v_total boolean;
  v_ids uuid[];
  v_nome text;
  v_antes jsonb;
  v_depois jsonb;
  v_esperado jsonb;
BEGIN
  IF p_acao NOT IN ('cliente_ativo', 'vincular_contrato_cliente') OR p_acao IS NULL OR p_alvo IS NULL
    OR p_novo IS NULL OR jsonb_typeof(p_novo) <> 'object' THEN
    RAISE EXCEPTION 'Ação ou valor inválido.' USING ERRCODE = '22023';
  END IF;
  IF NOT coalesce(public.has_permissao_de(p.user_id, CASE p_acao WHEN 'cliente_ativo' THEN 'clientes' ELSE 'contratos' END, 'editar'), false) THEN
    RAISE EXCEPTION 'Sem permissão atual para esta operação.' USING ERRCODE = '42501';
  END IF;
  IF p_acao = 'cliente_ativo' THEN
    IF p_novo - 'ativo' <> '{}'::jsonb OR jsonb_typeof(p_novo -> 'ativo') IS DISTINCT FROM 'boolean' THEN
      RAISE EXCEPTION 'Informe somente ativo como booleano.' USING ERRCODE = '22023';
    END IF;
    v_cliente := p_alvo;
  ELSE
    IF p_novo - 'cliente_id' <> '{}'::jsonb OR jsonb_typeof(p_novo -> 'cliente_id') IS DISTINCT FROM 'string'
      OR (p_novo ->> 'cliente_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'Informe somente um cliente válido.' USING ERRCODE = '22023';
    END IF;
    v_cliente := (p_novo ->> 'cliente_id')::uuid;
  END IF;
  SELECT total, client_ids INTO v_total, v_ids FROM public.wa_agente_escopo(p.tenant_id, p.user_id);
  IF v_total IS NOT TRUE AND NOT (v_cliente = ANY(coalesce(v_ids, '{}'::uuid[]))) THEN
    RAISE EXCEPTION 'Registro fora da carteira autorizada.' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO c FROM public.clients WHERE id = v_cliente AND tenant_id = p.tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Registro não encontrado nesta empresa.' USING ERRCODE = '42501'; END IF;
  v_nome := private.wa_agente_acoes_nome(c.nome);
  IF p_acao = 'cliente_ativo' THEN
    IF c.ativo IS NOT DISTINCT FROM (p_novo ->> 'ativo')::boolean THEN
      RAISE EXCEPTION 'O cliente já está nesse estado.' USING ERRCODE = '22023';
    END IF;
    -- Inclui FK e contrato antigo sem FK pelo nome. Ambiguidade recusa a ação,
    -- em vez de considerar que o contrato não pertence a ninguém.
    IF (p_novo ->> 'ativo')::boolean IS FALSE THEN
      PERFORM id FROM public.contratos WHERE tenant_id = p.tenant_id
        AND (cliente_id = c.id OR EXISTS (SELECT 1 FROM public.contrato_clientes cc WHERE cc.contrato_id = contratos.id AND cc.tenant_id = p.tenant_id AND cc.cliente_id = c.id) OR (cliente_id IS NULL AND v_nome <> '' AND private.wa_agente_acoes_nome(cliente_nome) = v_nome))
        ORDER BY id FOR UPDATE;
      IF EXISTS (
        SELECT 1 FROM public.contratos WHERE tenant_id = p.tenant_id
          AND (cliente_id = c.id OR EXISTS (SELECT 1 FROM public.contrato_clientes cc WHERE cc.contrato_id = contratos.id AND cc.tenant_id = p.tenant_id AND cc.cliente_id = c.id) OR (cliente_id IS NULL AND v_nome <> '' AND private.wa_agente_acoes_nome(cliente_nome) = v_nome))
          AND private.wa_agente_acoes_nome(status) NOT IN ('cancelado','concluido','encerrado','distrato','finalizado','rescindido')
      ) THEN RAISE EXCEPTION 'Cliente possui contrato não encerrado; inativação recusada.' USING ERRCODE = '22023'; END IF;
    END IF;
    v_antes := jsonb_build_object('ativo', c.ativo);
    v_depois := p_novo;
    v_esperado := jsonb_build_object('cliente_id', c.id, 'ativo', c.ativo, 'nome', c.nome, 'atualizado_em', c.atualizado_em);
  ELSE
    SELECT * INTO k FROM public.contratos WHERE id = p_alvo AND tenant_id = p.tenant_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Registro não encontrado nesta empresa.' USING ERRCODE = '42501'; END IF;
    IF k.cliente_id IS NOT NULL THEN RAISE EXCEPTION 'O contrato já tem cliente vinculado.' USING ERRCODE = '22023'; END IF;
    IF c.ativo IS NOT TRUE AND private.wa_agente_acoes_nome(k.status) NOT IN ('cancelado','concluido','encerrado','distrato','finalizado','rescindido') THEN
      RAISE EXCEPTION 'Contrato não encerrado exige cliente ativo.' USING ERRCODE = '22023';
    END IF;
    -- Contrato sem FK não fornece carteira canônica. Quem não pode ver carteira
    -- inteira precisa ser o estrategista atual do contrato E possuir o destino.
    IF v_total IS NOT TRUE AND k.estrategista_id IS DISTINCT FROM p.user_id THEN
      RAISE EXCEPTION 'Contrato fora da carteira autorizada.' USING ERRCODE = '42501';
    END IF;
    v_antes := jsonb_build_object('cliente_id', NULL);
    v_depois := jsonb_build_object('cliente_id', c.id, 'cliente_nome', c.nome);
    v_esperado := jsonb_build_object('contrato_id', k.id, 'cliente_id', k.cliente_id, 'status', k.status,
      'cliente_nome', k.cliente_nome, 'atualizado_em', k.atualizado_em,
      'destino_id', c.id, 'destino_nome', c.nome, 'destino_ativo', c.ativo, 'destino_atualizado_em', c.atualizado_em);
  END IF;
  RETURN jsonb_build_object('esperado', v_esperado, 'previa', jsonb_build_object('acao', p_acao,
    'alvo_nome', CASE p_acao WHEN 'cliente_ativo' THEN c.nome ELSE k.cliente_nome END, 'antes', v_antes, 'depois', v_depois));
END;
$function$
;

CREATE OR REPLACE FUNCTION private.wa_agente_acoes_nome(p_nome text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT btrim(regexp_replace(lower(extensions.unaccent('extensions.unaccent'::regdictionary, coalesce(p_nome, ''))), '\s+', ' ', 'g'))
$function$
;

CREATE OR REPLACE FUNCTION private.wa_agente_acoes_pedido(p_pedido uuid, p_exigir_lock boolean)
 RETURNS wa_agente_pedidos
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  p public.wa_agente_pedidos%ROWTYPE;
  m public.wa_agente_membros%ROWTYPE;
  u public.users%ROWTYPE;
  cfg public.wa_auto_config%ROWTYPE;
  wi public.whatsapp_instances%ROWTYPE;
  msg public.chat_messages%ROWTYPE;
  cv public.chat_conversations%ROWTYPE;
  ct public.chat_contacts%ROWTYPE;
  g public.wa_agente_grupos%ROWTYPE;
  v_base text;
  v_texto text;
  cv_origem public.chat_conversations%ROWTYPE;
  ct_origem public.chat_contacts%ROWTYPE;
BEGIN
  IF auth.uid() IS NOT NULL THEN
    RAISE EXCEPTION 'Ação não autorizada para este pedido.' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO p FROM public.wa_agente_pedidos WHERE id = p_pedido FOR UPDATE;
  IF NOT FOUND OR p.user_id IS NULL OR p.membro_id IS NULL OR p.chat_message_id IS NULL
     OR p.conversation_id IS NULL OR p.instance_uuid IS NULL OR p.eh_grupo IS NOT TRUE
     OR p.entrada_texto_sha256 IS NULL OR p.entrada_encaminhada IS TRUE
     OR (p_exigir_lock AND (p.status <> 'processando' OR p.lock_ate IS NULL OR p.lock_ate <= clock_timestamp())) THEN
    RAISE EXCEPTION 'Pedido indisponível ou sem processamento exclusivo.' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO m FROM public.wa_agente_membros
    WHERE id = p.membro_id AND tenant_id = p.tenant_id AND user_id = p.user_id AND ativo IS TRUE FOR SHARE;
  IF NOT FOUND OR m.telefone_chave IS DISTINCT FROM p.remetente_chave THEN
    RAISE EXCEPTION 'Ação não autorizada para este pedido.' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO u FROM public.users
    WHERE id = p.user_id AND tenant_id = p.tenant_id AND ativo IS TRUE AND perfil IS DISTINCT FROM 'cliente' FOR SHARE;
  IF NOT FOUND OR NOT coalesce(public.has_permissao_de(p.user_id, 'automacoes-wa', 'admin'), false) THEN
    RAISE EXCEPTION 'Ação não autorizada para este pedido.' USING ERRCODE = '42501';
  END IF;
  PERFORM 1 FROM public.app_modules
    WHERE tenant_id = p.tenant_id AND slug = 'automacoes-wa' AND enabled IS TRUE FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Assistente indisponível.' USING ERRCODE = '42501'; END IF;
  SELECT * INTO cfg FROM public.wa_auto_config WHERE tenant_id = p.tenant_id AND agente_ativo IS TRUE FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Assistente indisponível.' USING ERRCODE = '42501'; END IF;
  SELECT * INTO wi FROM public.whatsapp_instances
    WHERE id = p.instance_uuid AND tenant_id = p.tenant_id AND ativo IS TRUE AND status = 'conectado' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Canal indisponível.' USING ERRCODE = '42501'; END IF;
  SELECT * INTO msg FROM public.chat_messages
    WHERE id = p.chat_message_id AND tenant_id = p.tenant_id AND message_id_wpp = p.message_id_wpp FOR SHARE;
  IF NOT FOUND OR msg.tipo IS DISTINCT FROM 'texto'
     OR msg.enviado_por_agente IS TRUE OR msg.enviado_por_ia IS TRUE
     OR msg.autor_origem IS DISTINCT FROM 'webhook' OR msg.autor_chave IS DISTINCT FROM p.remetente_chave
     OR (msg.conversation_id = p.conversation_id AND (
       msg.autor_tipo IS DISTINCT FROM 'equipe' OR msg.autor_user_id IS DISTINCT FROM p.user_id))
     OR p.gatilho NOT IN ('nome', 'mencao', 'quote') THEN
    RAISE EXCEPTION 'Use o texto próprio de uma mensagem autenticada.' USING ERRCODE = '42501';
  END IF;
  -- Somente o corpo próprio atual; reply_to_id/quotedMessage nunca fornecem intenção.
  v_texto := regexp_replace(msg.conteudo, '^\[[^\]\r\n]{1,100}\] ', '');
  IF nullif(btrim(v_texto), '') IS NULL OR encode(extensions.digest(convert_to(v_texto, 'UTF8'), 'sha256'), 'hex') IS DISTINCT FROM p.entrada_texto_sha256 THEN
    RAISE EXCEPTION 'A entrada original não pôde ser conferida.' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO cv FROM public.chat_conversations
    WHERE id = p.conversation_id AND tenant_id = p.tenant_id AND instance_id = p.instance_uuid FOR SHARE;
  IF NOT FOUND OR cv.is_group IS DISTINCT FROM p.eh_grupo THEN
    RAISE EXCEPTION 'Canal indisponível.' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO ct FROM public.chat_contacts
    WHERE id = cv.contact_id AND tenant_id = p.tenant_id AND instance_id = p.instance_uuid AND bloqueado IS NOT TRUE FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Canal indisponível.' USING ERRCODE = '42501'; END IF;
  IF p.eh_grupo THEN
    IF cfg.agente_grupos IS NOT TRUE OR p.gatilho NOT IN ('nome', 'mencao', 'quote')
       OR p.chat_jid !~ '^(120363[0-9]{9,15}|[1-9][0-9]{9,14}-[0-9]{9,11})@g\.us$' THEN
      RAISE EXCEPTION 'Grupo não autorizado.' USING ERRCODE = '42501';
    END IF;
    SELECT * INTO g FROM public.wa_agente_grupos
      WHERE tenant_id = p.tenant_id AND grupo_jid = p.chat_jid AND ativo IS TRUE FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Grupo não autorizado.' USING ERRCODE = '42501'; END IF;
    IF wi.instance_id IS DISTINCT FROM cfg.uazapi_instance_id AND NOT EXISTS (
      SELECT 1 FROM public.wa_agente_grupo_numeros n
        WHERE n.tenant_id = p.tenant_id AND n.grupo_id = g.id AND n.instance_uuid = p.instance_uuid
    ) THEN RAISE EXCEPTION 'Número não autorizado neste grupo.' USING ERRCODE = '42501'; END IF;
    v_base := left(p.chat_jid, length(p.chat_jid) - 5);
    -- A mensagem pode ter sido deduplicada pela primeira conexão a recebê-la.
    -- Esta segunda cadeia só comprova conteúdo/canal; não concede identidade.
    SELECT * INTO cv_origem FROM public.chat_conversations
      WHERE id=msg.conversation_id AND tenant_id=p.tenant_id AND is_group IS TRUE FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Canal de origem indisponível.' USING ERRCODE='42501'; END IF;
    PERFORM 1 FROM public.whatsapp_instances WHERE id=cv_origem.instance_id AND tenant_id=p.tenant_id FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Canal de origem indisponível.' USING ERRCODE='42501'; END IF;
    SELECT * INTO ct_origem FROM public.chat_contacts
      WHERE id=cv_origem.contact_id AND tenant_id=p.tenant_id AND instance_id=cv_origem.instance_id
        AND bloqueado IS NOT TRUE FOR SHARE;
    IF NOT FOUND OR lower(btrim(ct_origem.numero_whatsapp)) NOT IN (v_base,p.chat_jid)
      OR ct_origem.numero_whatsapp IS NULL THEN
      RAISE EXCEPTION 'Canal de origem indisponível.' USING ERRCODE='42501';
    END IF;
    IF ct.numero_whatsapp IS NULL OR lower(btrim(ct.numero_whatsapp)) NOT IN (v_base, p.chat_jid) OR EXISTS (
      SELECT 1 FROM public.chat_contacts c
      WHERE c.tenant_id = p.tenant_id AND lower(btrim(c.numero_whatsapp)) IN (v_base, p.chat_jid)
        AND (c.client_id IS NOT NULL OR EXISTS (
          SELECT 1 FROM public.chat_contact_clients cc WHERE cc.tenant_id = p.tenant_id AND cc.contact_id = c.id
        ) OR EXISTS (
          SELECT 1 FROM public.clients cl WHERE cl.tenant_id = p.tenant_id AND cl.ativo IS DISTINCT FROM false
            AND private.wa_agente_acoes_nome(cl.nome) <> ''
            AND private.wa_agente_acoes_nome(cl.nome) = private.wa_agente_acoes_nome(c.nome)
        ))
    ) THEN RAISE EXCEPTION 'O grupo não é mais interno.' USING ERRCODE = '42501'; END IF;
  END IF;
  -- Mesmo critério temporal de lerPergunta, mas aqui a concatenação é recusada.
  IF EXISTS (
    SELECT 1 FROM public.wa_agente_pedidos q WHERE q.tenant_id = p.tenant_id AND q.chat_jid = p.chat_jid
      AND q.membro_id = p.membro_id AND q.id <> p.id AND q.status = 'agrupado'
      AND q.created_at >= clock_timestamp() - interval '2 minutes'
  ) THEN RAISE EXCEPTION 'Envie a confirmação sozinha em uma nova mensagem.' USING ERRCODE = '42501'; END IF;
  RETURN p;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.wa_agente_atribuicoes_estado(p wa_agente_pedidos, p_alvo uuid, p_novo jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE itens jsonb; i jsonb; c public.clients%ROWTYPE; u public.users%ROWTYPE;
  a public.client_assignments%ROWTYPE; ids uuid[]; usuarios uuid[]; carteira uuid[]; total boolean;
  rev bigint; n integer; nome_anterior text; antes jsonb:='[]'; depois jsonb:='[]'; esperado jsonb:='[]';
BEGIN
  itens:=private.wa_agente_atribuicoes_itens(p_alvo,p_novo);
  IF NOT coalesce(public.has_permissao_de(p.user_id,'clientes.atribuir','editar'),false) THEN
    RAISE EXCEPTION 'Sem permissão atual para esta operação.' USING ERRCODE='42501';
  END IF;
  SELECT array_agg((value->>'cliente_id')::uuid),array_agg((value->>'user_id')::uuid)
    INTO ids,usuarios FROM jsonb_array_elements(itens);
  SELECT s.total,s.client_ids INTO total,carteira FROM public.wa_agente_escopo(p.tenant_id,p.user_id) s;
  IF total IS NOT TRUE AND NOT (ids <@ coalesce(carteira,'{}'::uuid[])) THEN
    RAISE EXCEPTION 'Registro fora da carteira autorizada.' USING ERRCODE='42501';
  END IF;
  -- Todos os mutexes do lote precedem a primeira escrita; ordem global UUID.
  PERFORM id FROM public.clients WHERE tenant_id=p.tenant_id AND id=ANY(ids) ORDER BY id FOR UPDATE;
  GET DIAGNOSTICS n=ROW_COUNT;
  IF n<>cardinality(ids) THEN RAISE EXCEPTION 'Registro não encontrado nesta empresa.' USING ERRCODE='42501'; END IF;
  SELECT array_agg(DISTINCT pessoa) INTO usuarios FROM (
    SELECT unnest(usuarios) AS pessoa
    UNION ALL
    SELECT user_id FROM public.client_assignments WHERE tenant_id=p.tenant_id
      AND client_id=ANY(ids) AND tipo='estrategista' AND ativo IS TRUE
  ) nomes;
  PERFORM id FROM public.users WHERE tenant_id=p.tenant_id AND id=ANY(usuarios) ORDER BY id FOR SHARE;
  PERFORM client_id FROM public.client_assignment_state WHERE tenant_id=p.tenant_id AND client_id=ANY(ids) ORDER BY client_id FOR UPDATE;
  PERFORM id FROM public.client_assignments WHERE tenant_id=p.tenant_id AND client_id=ANY(ids) ORDER BY client_id,id FOR UPDATE;
  SELECT s.total,s.client_ids INTO total,carteira FROM public.wa_agente_escopo(p.tenant_id,p.user_id) s;
  IF NOT coalesce(public.has_permissao_de(p.user_id,'clientes.atribuir','editar'),false)
    OR (total IS NOT TRUE AND NOT (ids <@ coalesce(carteira,'{}'::uuid[]))) THEN
    RAISE EXCEPTION 'Sem permissão atual para esta operação.' USING ERRCODE='42501';
  END IF;
  FOR i IN SELECT value FROM jsonb_array_elements(itens) LOOP
    SELECT * INTO STRICT c FROM public.clients WHERE tenant_id=p.tenant_id AND id=(i->>'cliente_id')::uuid;
    SELECT * INTO u FROM public.users WHERE tenant_id=p.tenant_id AND id=(i->>'user_id')::uuid;
    IF NOT FOUND OR u.ativo IS DISTINCT FROM true THEN RAISE EXCEPTION 'atribuicao_destino_inativo' USING ERRCODE='22023'; END IF;
    IF NOT coalesce(private.client_assignment_elegivel(p.tenant_id,u.id,'estrategista'),false) THEN
      RAISE EXCEPTION 'atribuicao_destino_inelegivel' USING ERRCODE='22023';
    END IF;
    SELECT count(*) INTO n FROM public.client_assignments
      WHERE tenant_id=p.tenant_id AND client_id=c.id AND tipo='estrategista' AND ativo IS TRUE;
    IF n>1 THEN RAISE EXCEPTION 'Cliente com mais de um estrategista ativo; escolha o vínculo no cadastro.' USING ERRCODE='22023'; END IF;
    a:=NULL; nome_anterior:=NULL;
    SELECT * INTO a FROM public.client_assignments
      WHERE tenant_id=p.tenant_id AND client_id=c.id AND tipo='estrategista' AND ativo IS TRUE;
    IF a.id IS DISTINCT FROM (i->>'assignment_id')::uuid THEN RAISE EXCEPTION 'atribuicao_estado_alterado' USING ERRCODE='40001'; END IF;
    IF a.user_id=u.id THEN RAISE EXCEPTION 'atribuicao_ja_ativa' USING ERRCODE='22023'; END IF;
    SELECT nome INTO nome_anterior FROM public.users WHERE id=a.user_id AND tenant_id=p.tenant_id;
    SELECT coalesce((SELECT revisao FROM public.client_assignment_state WHERE tenant_id=p.tenant_id AND client_id=c.id),0) INTO rev;
    IF rev<>(i->>'expected_revision')::bigint THEN RAISE EXCEPTION 'atribuicao_estado_alterado' USING ERRCODE='40001'; END IF;
    antes:=antes||jsonb_build_array(jsonb_build_object('cliente_id',c.id,'cliente_nome',c.nome,
      'assignment_id',a.id,'estrategista_id',a.user_id,'estrategista_nome',nome_anterior,'revisao',rev));
    depois:=depois||jsonb_build_array(jsonb_build_object('cliente_id',c.id,'cliente_nome',c.nome,'user_id',u.id,'estrategista_nome',u.nome));
    esperado:=esperado||jsonb_build_array(jsonb_build_object('cliente_id',c.id,'cliente_nome',c.nome,
      'cliente_ativo',c.ativo,'cliente_atualizado_em',c.atualizado_em,'revisao',rev,'assignment',to_jsonb(a),
      'estrategista_nome',nome_anterior,'destino_id',u.id,'destino_nome',u.nome,'destino_perfil',u.perfil,'destino_ativo',u.ativo));
  END LOOP;
  RETURN jsonb_build_object('esperado',jsonb_build_object('itens',esperado),
    'previa',jsonb_build_object('acao','cliente_estrategista','alvo_nome','Responsáveis operacionais',
      'antes',jsonb_build_object('itens',antes),'depois',jsonb_build_object('itens',depois)));
END;
$function$
;

CREATE OR REPLACE FUNCTION private.wa_agente_atribuicoes_itens(p_alvo uuid, p_novo jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE i jsonb; ids uuid[] := '{}'; v_id uuid;
BEGIN
  IF p_alvo IS NULL OR p_novo IS NULL OR jsonb_typeof(p_novo) IS DISTINCT FROM 'object'
    OR p_novo - 'itens' <> '{}'::jsonb OR jsonb_typeof(p_novo->'itens') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Informe somente a lista de atribuições.' USING ERRCODE='22023';
  END IF;
  IF jsonb_array_length(p_novo->'itens') NOT BETWEEN 1 AND 10 THEN
    RAISE EXCEPTION 'Informe de uma a dez atribuições.' USING ERRCODE='22023';
  END IF;
  FOR i IN SELECT value FROM jsonb_array_elements(p_novo->'itens') LOOP
    IF jsonb_typeof(i) IS DISTINCT FROM 'object'
      OR i - ARRAY['cliente_id','user_id','assignment_id','expected_revision'] <> '{}'::jsonb
      OR NOT (i ?& ARRAY['cliente_id','user_id','assignment_id','expected_revision'])
      OR jsonb_typeof(i->'cliente_id') IS DISTINCT FROM 'string'
      OR jsonb_typeof(i->'user_id') IS DISTINCT FROM 'string'
      OR coalesce(i->>'cliente_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      OR coalesce(i->>'user_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      OR (i->'assignment_id' <> 'null'::jsonb AND (
        jsonb_typeof(i->'assignment_id') IS DISTINCT FROM 'string'
        OR coalesce(i->>'assignment_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'))
      OR jsonb_typeof(i->'expected_revision') IS DISTINCT FROM 'number'
      OR coalesce(i->>'expected_revision','') !~ '^[0-9]{1,19}$' THEN
      RAISE EXCEPTION 'Atribuição inválida ou incompleta.' USING ERRCODE='22023';
    END IF;
    IF (i->>'expected_revision')::numeric > 9223372036854775807 THEN
      RAISE EXCEPTION 'Revisão inválida.' USING ERRCODE='22023';
    END IF;
    v_id := (i->>'cliente_id')::uuid;
    IF v_id = ANY(ids) THEN RAISE EXCEPTION 'Um cliente não pode aparecer duas vezes.' USING ERRCODE='22023'; END IF;
    ids := array_append(ids, v_id);
  END LOOP;
  IF ids[1] IS DISTINCT FROM p_alvo THEN RAISE EXCEPTION 'Alvo incompatível com a lista.' USING ERRCODE='22023'; END IF;
  RETURN p_novo->'itens';
END;
$function$
;

CREATE OR REPLACE FUNCTION private.wa_agente_fatos_equipe_confere()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  p public.wa_agente_pedidos%ROWTYPE;
  esperado public.wa_agente_fatos_equipe%ROWTYPE;
  v_texto text;
  v_nome text;
  v_total boolean;
  v_ids uuid[];
BEGIN
  IF TG_OP = 'INSERT' AND NEW.origem = 'manutencao_codex' THEN
    IF current_user NOT IN ('postgres','supabase_admin') OR session_user <> current_user OR auth.uid() IS NOT NULL THEN
      RAISE EXCEPTION 'Importação administrativa indisponível neste canal.' USING ERRCODE = '42501';
    END IF;
    SELECT * INTO esperado FROM private.wa_agente_fatos_fontes_20261105() f WHERE f.id = NEW.id;
    IF NOT FOUND OR (to_jsonb(NEW) - 'criado_em') IS DISTINCT FROM (to_jsonb(esperado) - 'criado_em') THEN
      RAISE EXCEPTION 'A importação aceita somente as duas declarações autorizadas.' USING ERRCODE = '42501';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtext('wa_agente_fatos:' || NEW.tenant_id::text || ':' || NEW.grupo_jid));
    IF (SELECT count(*) FROM public.wa_agente_fatos_equipe f WHERE f.tenant_id = NEW.tenant_id AND f.grupo_jid = NEW.grupo_jid AND f.ativo AND f.id <> NEW.id) >= 100 THEN
      RAISE EXCEPTION 'Limite de 100 fatos ativos neste grupo; esqueça um antes.' USING ERRCODE = '23514';
    END IF;
    RETURN esperado;
  END IF;
  p := private.wa_agente_acoes_pedido(CASE WHEN TG_OP = 'INSERT' THEN NEW.pedido_id ELSE NEW.pedido_desativacao_id END, true);
  IF p.tenant_id IS DISTINCT FROM NEW.tenant_id OR p.chat_jid IS DISTINCT FROM NEW.grupo_jid THEN
    RAISE EXCEPTION 'Memória fora do grupo autorizado.' USING ERRCODE = '42501';
  END IF;
  SELECT regexp_replace(m.conteudo, '^\[[^\]\r\n]{1,100}\] ', '') INTO v_texto
    FROM public.chat_messages m WHERE m.tenant_id = p.tenant_id AND m.id = p.chat_message_id;
  IF TG_OP = 'INSERT' THEN
    IF NOT NEW.ativo OR NEW.autor_id IS DISTINCT FROM p.user_id
      OR NEW.mensagem_id IS DISTINCT FROM p.chat_message_id OR NEW.entrada_sha256 IS DISTINCT FROM p.entrada_texto_sha256
      OR coalesce(strpos(v_texto, NEW.trecho), 0) = 0
      OR encode(extensions.digest(convert_to(NEW.trecho,'UTF8'),'sha256'),'hex') IS DISTINCT FROM NEW.trecho_sha256 THEN
      RAISE EXCEPTION 'Fonte da declaração não conferida.' USING ERRCODE = '42501';
    END IF;
    SELECT left(u.nome,120) INTO NEW.autor_nome FROM public.users u WHERE u.tenant_id = p.tenant_id AND u.id = p.user_id;
    NEW.criado_em := clock_timestamp();
    IF NEW.sujeito_tipo = 'pessoa' THEN
      SELECT u.nome INTO v_nome FROM public.users u WHERE u.tenant_id = p.tenant_id AND u.id = NEW.sujeito_id FOR SHARE;
    ELSIF NEW.sujeito_tipo = 'cliente' THEN
      SELECT c.nome INTO v_nome FROM public.clients c WHERE c.tenant_id = p.tenant_id AND c.id = NEW.sujeito_id FOR SHARE;
    END IF;
    IF v_nome IS NULL OR v_nome IS DISTINCT FROM NEW.sujeito_nome THEN
      RAISE EXCEPTION 'Sujeito da declaração não conferido.' USING ERRCODE = '42501';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtext('wa_agente_fatos:' || NEW.tenant_id::text || ':' || NEW.grupo_jid));
    IF (SELECT count(*) FROM public.wa_agente_fatos_equipe f WHERE f.tenant_id = NEW.tenant_id AND f.grupo_jid = NEW.grupo_jid AND f.ativo AND f.id <> NEW.id) >= 100 THEN
      RAISE EXCEPTION 'Limite de 100 fatos ativos neste grupo; esqueça um antes.' USING ERRCODE = '23514';
    END IF;
  ELSE
    IF (to_jsonb(NEW) - ARRAY['ativo','desativado_em','desativado_por','pedido_desativacao_id']) IS DISTINCT FROM
       (to_jsonb(OLD) - ARRAY['ativo','desativado_em','desativado_por','pedido_desativacao_id'])
       OR OLD.ativo IS NOT TRUE OR NEW.ativo IS NOT FALSE OR NEW.desativado_por IS DISTINCT FROM p.user_id
       OR strpos(lower(v_texto), 'f' || left(replace(OLD.id::text,'-',''),7)) = 0 THEN
      RAISE EXCEPTION 'Só é permitido esquecer um fato identificado na mensagem atual.' USING ERRCODE = '42501';
    END IF;
    NEW.desativado_em := clock_timestamp();
  END IF;
  -- Texto livre não recebe classificação de carteira confiável do modelo.
  SELECT total, client_ids INTO v_total, v_ids FROM public.wa_agente_escopo(p.tenant_id,p.user_id);
  IF v_total IS NOT TRUE THEN
    RAISE EXCEPTION 'A memória compartilhada exige acesso à carteira completa.' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.wa_agente_fatos_fontes_20261105()
 RETURNS SETOF wa_agente_fatos_equipe
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  a record;
  p public.wa_agente_pedidos%ROWTYPE;
  m public.chat_messages%ROWTYPE;
  f public.wa_agente_fatos_equipe%ROWTYPE;
  v_tenant constant uuid := '00000000-0000-0000-0000-000000000001';
  v_grupo constant text := '120363415422487266@g.us';
  v_autorizador constant uuid := '0295d401-6270-4fbe-be47-ee9b6a9ed9c9';
  v_total boolean;
  v_texto text;
BEGIN
  IF current_user NOT IN ('postgres','supabase_admin') OR session_user <> current_user OR auth.uid() IS NOT NULL THEN
    RAISE EXCEPTION 'Importação limitada à sessão administrativa real.' USING ERRCODE = '42501';
  END IF;
  PERFORM 1 FROM public.users u WHERE u.id = v_autorizador AND u.tenant_id = v_tenant AND u.ativo IS TRUE AND u.perfil IS DISTINCT FROM 'cliente' FOR SHARE;
  IF NOT FOUND OR NOT coalesce(public.has_permissao_de(v_autorizador,'automacoes-wa','admin'),false) THEN
    RAISE EXCEPTION 'Autorizador da manutenção não tem administração atual.' USING ERRCODE = '42501';
  END IF;
  SELECT total INTO v_total FROM public.wa_agente_escopo(v_tenant,v_autorizador);
  IF v_total IS NOT TRUE THEN
    RAISE EXCEPTION 'Autorizador sem carteira completa atual.' USING ERRCODE = '42501';
  END IF;
  PERFORM 1 FROM public.wa_agente_grupos g WHERE g.tenant_id = v_tenant AND g.grupo_jid = v_grupo AND g.ativo IS TRUE FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Grupo da manutenção indisponível.' USING ERRCODE = '42501'; END IF;

  FOR a IN SELECT * FROM (VALUES
    ('b4e5ce68-6609-5c15-bc2b-5ab69b63bf22'::uuid, '683eb4c0-a057-4af0-b412-7e37066c2714'::uuid,
     '3cad0870-b074-41d1-bb8d-567ded016b4d'::uuid, '849a0faa-f08d-43a5-b381-7164363c8c68'::uuid,
     '0295d401-6270-4fbe-be47-ee9b6a9ed9c9'::uuid, '@255748827312232 virendra é um estrategista que já saiu.'::text),
    ('766e894f-7741-5911-ad30-4eda5c40bfbf'::uuid, 'c461c73d-2979-46ca-89ea-5af5e24277e5'::uuid,
     'b24d7590-d7b8-44ec-aa9c-ad3475d5c746'::uuid, '1583771d-b531-4d0d-bfce-85668eb107c8'::uuid,
     'efa3729e-de6e-4515-905d-f5fdd11dd679'::uuid, 'Herilly prado não é mais estrategista da empresa.'::text)
  ) AS alvos(id,sujeito,pedido,mensagem,autor,trecho)
  LOOP
    SELECT * INTO p FROM public.wa_agente_pedidos q WHERE q.id = a.pedido AND q.tenant_id = v_tenant FOR SHARE;
    IF NOT FOUND OR p.chat_jid IS DISTINCT FROM v_grupo OR p.eh_grupo IS NOT TRUE
      OR p.user_id IS DISTINCT FROM a.autor OR p.chat_message_id IS DISTINCT FROM a.mensagem
      OR p.entrada_encaminhada IS TRUE THEN
      RAISE EXCEPTION 'Pedido histórico não corresponde ao alvo autorizado.' USING ERRCODE = '42501';
    END IF;
    PERFORM 1 FROM public.wa_agente_membros mb WHERE mb.id = p.membro_id AND mb.tenant_id = v_tenant
      AND mb.user_id = a.autor AND mb.telefone_chave = p.remetente_chave FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Ator histórico sem vínculo conferível com o pedido.' USING ERRCODE = '42501'; END IF;
    SELECT * INTO m FROM public.chat_messages x WHERE x.id = a.mensagem AND x.tenant_id = v_tenant FOR SHARE;
    IF NOT FOUND OR m.tipo IS DISTINCT FROM 'texto' OR m.autor_origem IS DISTINCT FROM 'webhook'
      OR m.autor_chave IS DISTINCT FROM p.remetente_chave OR m.message_id_wpp IS DISTINCT FROM p.message_id_wpp
      OR m.enviado_por_agente IS TRUE OR m.enviado_por_ia IS TRUE OR m.criado_em IS NULL
      OR (m.conversation_id = p.conversation_id AND (m.autor_tipo IS DISTINCT FROM 'equipe' OR m.autor_user_id IS DISTINCT FROM a.autor)) THEN
      RAISE EXCEPTION 'Autoria histórica não pôde ser conferida.' USING ERRCODE = '42501';
    END IF;
    v_texto := regexp_replace(m.conteudo, '^\[[^\]\r\n]{1,100}\] ', '');
    IF coalesce(strpos(v_texto,a.trecho),0) = 0 THEN
      RAISE EXCEPTION 'A declaração literal não consta da fonte histórica.' USING ERRCODE = '42501';
    END IF;
    IF p.entrada_texto_sha256 IS NOT NULL AND p.entrada_texto_sha256 IS DISTINCT FROM encode(extensions.digest(convert_to(v_texto,'UTF8'),'sha256'),'hex') THEN
      RAISE EXCEPTION 'O digest histórico existente diverge do corpo próprio.' USING ERRCODE = '42501';
    END IF;
    -- Identidade vem do pedido/membro autenticados; a mensagem canônica de
    -- outra conexão comprova o conteúdo/autor_chave, sem reescrever sua autoria.
    PERFORM 1 FROM public.chat_conversations cv
      JOIN public.chat_contacts ct ON ct.id = cv.contact_id AND ct.tenant_id = cv.tenant_id AND ct.instance_id = cv.instance_id
      JOIN public.whatsapp_instances wi ON wi.id = cv.instance_id AND wi.tenant_id = cv.tenant_id
      WHERE cv.id = p.conversation_id AND cv.instance_id = p.instance_uuid AND cv.tenant_id = v_tenant AND cv.is_group IS TRUE
        AND lower(btrim(ct.numero_whatsapp)) IN (v_grupo,left(v_grupo,length(v_grupo)-5)) FOR SHARE OF cv,ct,wi;
    IF NOT FOUND THEN RAISE EXCEPTION 'Conversa do pedido fora do grupo autorizado.' USING ERRCODE = '42501'; END IF;
    -- Conferir o grupo da mensagem, inclusive se a fila veio de outra instância.
    PERFORM 1 FROM public.chat_conversations cv
      JOIN public.chat_contacts ct ON ct.id = cv.contact_id AND ct.tenant_id = cv.tenant_id AND ct.instance_id = cv.instance_id
      JOIN public.whatsapp_instances wi ON wi.id = cv.instance_id AND wi.tenant_id = cv.tenant_id
      WHERE cv.id = m.conversation_id AND cv.tenant_id = v_tenant AND cv.is_group IS TRUE
        AND lower(btrim(ct.numero_whatsapp)) IN (v_grupo,left(v_grupo,length(v_grupo)-5)) FOR SHARE OF cv,ct,wi;
    IF NOT FOUND THEN RAISE EXCEPTION 'Fonte histórica fora do grupo autorizado.' USING ERRCODE = '42501'; END IF;
    f := NULL;
    f.id := a.id; f.tenant_id := v_tenant; f.grupo_jid := v_grupo;
    f.sujeito_tipo := 'pessoa'; f.sujeito_id := a.sujeito;
    SELECT u.nome INTO f.sujeito_nome FROM public.users u WHERE u.id = a.sujeito AND u.tenant_id = v_tenant FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Sujeito histórico não cadastrado no tenant.' USING ERRCODE = '42501'; END IF;
    f.trecho := a.trecho;
    f.trecho_sha256 := encode(extensions.digest(convert_to(a.trecho,'UTF8'),'sha256'),'hex');
    f.autor_id := a.autor;
    SELECT left(u.nome,120) INTO f.autor_nome FROM public.users u WHERE u.id = a.autor AND u.tenant_id = v_tenant FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Autor histórico não cadastrado no tenant.' USING ERRCODE = '42501'; END IF;
    f.pedido_id := a.pedido; f.mensagem_id := a.mensagem;
    f.entrada_sha256 := encode(extensions.digest(convert_to(v_texto,'UTF8'),'sha256'),'hex');
    f.criado_em := clock_timestamp(); f.ativo := true;
    f.origem := 'manutencao_codex'; f.executor_bd := session_user;
    f.autorizado_por := v_autorizador; f.fonte_criada_em := m.criado_em;
    RETURN NEXT f;
  END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.wa_agente_fatos_importar_20261105()
 RETURNS TABLE(fato_id uuid, sujeito text, resultado text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  esperado public.wa_agente_fatos_equipe%ROWTYPE;
  existente public.wa_agente_fatos_equipe%ROWTYPE;
BEGIN
  -- O helper também valida sessão real, autorização e ambas as fontes.
  FOR esperado IN SELECT * FROM private.wa_agente_fatos_fontes_20261105() LOOP
    PERFORM pg_advisory_xact_lock(hashtext('wa_agente_fatos:' || esperado.tenant_id::text || ':' || esperado.grupo_jid));
    SELECT * INTO existente FROM public.wa_agente_fatos_equipe f WHERE f.id = esperado.id FOR SHARE;
    IF FOUND THEN
      IF existente.origem IS DISTINCT FROM 'manutencao_codex' OR existente.tenant_id IS DISTINCT FROM esperado.tenant_id
        OR existente.grupo_jid IS DISTINCT FROM esperado.grupo_jid OR existente.sujeito_id IS DISTINCT FROM esperado.sujeito_id
        OR existente.pedido_id IS DISTINCT FROM esperado.pedido_id OR existente.mensagem_id IS DISTINCT FROM esperado.mensagem_id
        OR existente.autor_id IS DISTINCT FROM esperado.autor_id OR existente.trecho IS DISTINCT FROM esperado.trecho
        OR existente.autorizado_por IS DISTINCT FROM esperado.autorizado_por THEN
        RAISE EXCEPTION 'Identificador ocupado por outra memória; nada importado.' USING ERRCODE = '23505';
      END IF;
      RETURN QUERY SELECT existente.id, existente.sujeito_nome, CASE WHEN existente.ativo THEN 'ja_importado' ELSE 'ja_desativado_preservado' END;
    ELSE
      INSERT INTO public.wa_agente_fatos_equipe SELECT (esperado).*;
      RETURN QUERY SELECT esperado.id, esperado.sujeito_nome, 'importado'::text;
    END IF;
  END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.api_externa_limpar_antigos()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_log bigint;
  v_rl bigint;
BEGIN
  DELETE FROM api_request_log WHERE criado_em < now() - interval '90 days';
  GET DIAGNOSTICS v_log = ROW_COUNT;
  DELETE FROM api_rate_limit WHERE janela_inicio < now() - interval '7 days';
  GET DIAGNOSTICS v_rl = ROW_COUNT;
  RETURN jsonb_build_object('api_request_log', v_log, 'api_rate_limit', v_rl);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.api_rate_limit_hit(p_key_id uuid, p_limite integer, p_janela_seg integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_inicio timestamptz;
  v_conta integer;
BEGIN
  IF p_limite < 1 OR p_janela_seg < 1 THEN
    RAISE EXCEPTION 'parametros invalidos';
  END IF;
  v_inicio := to_timestamp(floor(extract(epoch FROM now()) / p_janela_seg) * p_janela_seg);
  INSERT INTO api_rate_limit AS r (key_id, janela_inicio, contagem)
  VALUES (p_key_id, v_inicio, 1)
  ON CONFLICT (key_id, janela_inicio) DO UPDATE SET contagem = r.contagem + 1
  RETURNING r.contagem INTO v_conta;
  -- limpeza oportunista de janelas antigas desta chave
  DELETE FROM api_rate_limit WHERE key_id = p_key_id AND janela_inicio < v_inicio - make_interval(secs => p_janela_seg * 5);
  RETURN jsonb_build_object(
    'permitido', v_conta <= p_limite,
    'restante', greatest(p_limite - v_conta, 0),
    'reset_seg', greatest(ceil(extract(epoch FROM (v_inicio + make_interval(secs => p_janela_seg) - now())))::int, 1)
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.app_chave_anon()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v text;
BEGIN
  SELECT decrypted_secret INTO v FROM vault.decrypted_secrets WHERE name = 'anon_key' LIMIT 1;
  IF v IS NULL OR length(v) < 20 THEN
    v := 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Ind1em1ja2F0Ym1scGtkeHRmaHFyIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzMxNjUxNzEsImV4cCI6MjA4ODc0MTE3MX0.dL8LHbCJv69zJtt-aA3iAEO6PMcJBHlDC1HAEu9O9Ho';
  END IF;
  RETURN v;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.app_url_funcoes(p_funcao text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_base text;
BEGIN
  IF p_funcao IS NULL OR p_funcao !~ '^[a-z0-9][a-z0-9-]{0,62}$' THEN
    RAISE EXCEPTION 'nome de função inválido';
  END IF;
  SELECT rtrim(decrypted_secret, '/') INTO v_base
    FROM vault.decrypted_secrets
   WHERE name = 'project_url'
   LIMIT 1;
  IF v_base IS NULL OR v_base !~ '^https://' THEN
    -- Reserva: o endereço deste projeto (o empacotador troca pelo do cliente).
    v_base := 'https://wuzmckatbmlpkdxtfhqr.supabase.co';
  END IF;
  RETURN v_base || '/functions/v1/' || p_funcao;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.aprovar_extrato_mes(p_estrategista_id uuid, p_mes date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid UUID := auth.uid();
  v_perfil TEXT;
  v_tenant UUID;
  v_extrato_id UUID;
  v_total NUMERIC(12,2);
  v_qtd INTEGER;
  u RECORD;
begin
  -- GUARDA DE CONTA ATIVA
  IF auth.uid() IS NULL OR public.get_user_tenant_id() IS NULL THEN
    RAISE EXCEPTION 'Conta sem acesso ativo' USING ERRCODE = '42501';
  END IF;
  -- FIM DA GUARDA
  select perfil, tenant_id into v_perfil, v_tenant from public.users where id = v_uid;
  if not (coalesce(v_perfil,'') in ('admin','gerente') or public.is_comissoes_gestor()) then
    raise exception 'Sem permissão para fechar extratos de comissão';
  end if;

  select * into u from public.users where id = p_estrategista_id;
  if not found then raise exception 'Estrategista não encontrado'; end if;

  if v_tenant is null or u.tenant_id is distinct from v_tenant then
    raise exception 'Estrategista não pertence à sua empresa';
  end if;

  select coalesce(sum(valor_final), 0), count(*)
    into v_total, v_qtd
    from public.comissoes
   where estrategista_id = p_estrategista_id
     and tenant_id = v_tenant
     and mes_referencia = date_trunc('month', p_mes)::date
     and status = 'aprovada'
     and extrato_id is null;

  if v_qtd = 0 then
    raise exception 'Aprove ao menos uma comissão antes de fechar o mês';
  end if;

  insert into public.extratos_mensais (
    estrategista_id, estrategista_nome, estrategista_doc, estrategista_pix,
    mes_referencia, total_bruto, total_liquido,
    status, aprovado_por, aprovado_em, tenant_id
  ) values (
    p_estrategista_id, u.nome, u.cnpj_cpf, u.chave_pix,
    date_trunc('month', p_mes)::date, v_total, v_total,
    'aprovado', v_uid, now(), v_tenant
  )
  on conflict (estrategista_id, mes_referencia) do update
    set total_bruto = EXCLUDED.total_bruto,
        total_liquido = EXCLUDED.total_liquido,
        estrategista_doc = EXCLUDED.estrategista_doc,
        estrategista_pix = EXCLUDED.estrategista_pix,
        status = 'aprovado',
        aprovado_por = v_uid,
        aprovado_em = now()
  returning id into v_extrato_id;

  update public.comissoes
     set extrato_id = v_extrato_id
   where estrategista_id = p_estrategista_id
     and tenant_id = v_tenant
     and mes_referencia = date_trunc('month', p_mes)::date
     and status = 'aprovada'
     and extrato_id is null;

  return v_extrato_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.atendimento_atestar_entrada_whatsapp(p_tenant uuid, p_mensagem uuid, p_conversa uuid, p_texto_sha256 text, p_ocorrido_em timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_linhas integer;
BEGIN
  IF auth.uid() IS NOT NULL OR p_texto_sha256 !~ '^[0-9a-f]{64}$' OR p_ocorrido_em IS NULL
    OR p_ocorrido_em < clock_timestamp() - interval '5 minutes'
    OR p_ocorrido_em > clock_timestamp() + interval '1 minute' THEN RETURN false; END IF;
  UPDATE private.atendimento_wa_entradas e
     SET atestada_em = COALESCE(e.atestada_em, clock_timestamp()), ocorrido_em = COALESCE(e.ocorrido_em, p_ocorrido_em)
    FROM public.chat_messages m
   WHERE e.mensagem_id = p_mensagem AND e.tenant_id = p_tenant AND e.conversation_id = p_conversa
     AND (e.atestada_em IS NULL OR e.ocorrido_em = p_ocorrido_em)
     AND e.registrado_em > clock_timestamp() - interval '5 minutes'
     AND e.texto_sha256 = p_texto_sha256
     AND m.id = e.mensagem_id AND m.tenant_id = e.tenant_id AND m.conversation_id = e.conversation_id
     AND m.criado_em = e.criado_em AND m.autor_tipo = e.autor_tipo
     AND m.autor_user_id IS NOT DISTINCT FROM e.autor_user_id
     AND m.autor_origem = 'webhook' AND m.reply_to_id IS NULL
     AND m.enviado_por_agente IS NOT TRUE AND m.enviado_por_ia IS NOT TRUE
     AND encode(extensions.digest(convert_to(m.conteudo, 'UTF8'), 'sha256'), 'hex') = p_texto_sha256;
  GET DIAGNOSTICS v_linhas = ROW_COUNT;
  RETURN v_linhas = 1;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.atendimento_contexto_tickets_ia(p_tenant uuid, p_cliente uuid, p_offset integer, p_limite integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_total integer; v_itens jsonb;
BEGIN
  IF current_user <> 'service_role' OR NOT EXISTS (SELECT 1 FROM public.clients WHERE id = p_cliente AND tenant_id = p_tenant) THEN
    RAISE EXCEPTION 'Contexto não autorizado.' USING ERRCODE = '42501';
  END IF;
  IF p_offset IS NULL OR p_offset < 0 OR p_offset > 100 OR p_limite IS NULL OR p_limite < 1 OR p_limite > 50 THEN
    RAISE EXCEPTION 'Página inválida.' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM public.app_modules WHERE tenant_id = p_tenant AND slug = 'atendimento' AND enabled IS FALSE) THEN
    RETURN jsonb_build_object('desativado', true);
  END IF;
  SELECT count(*) INTO v_total FROM public.atendimento_demandas d
    WHERE d.tenant_id = p_tenant AND d.cliente_id = p_cliente AND d.wa_origem_mensagem_id IS NOT NULL AND d.concluida_em IS NULL;
  SELECT COALESCE(jsonb_agg(x.item ORDER BY x.created_at, x.id), '[]'::jsonb) INTO v_itens FROM (
    SELECT d.id, d.created_at, jsonb_build_object('id', d.id, 'codigo', d.codigo, 'titulo', left(d.titulo,160),
      'origem_mensagem_id', d.wa_origem_mensagem_id, 'revisao', d.updated_at, 'reaberta_em', d.wa_reaberta_em,
      'canal_rotulo', COALESCE(canal.rotulo, '?'), 'origem_texto', left(fonte.conteudo,400),
      'origem_em', COALESCE(fonte.criado_em, origem.criado_em, d.created_at),
      'origem_pronta', fonte.atestada_em IS NOT NULL AND fonte.ocorrido_em IS NOT NULL) AS item
    FROM public.atendimento_demandas d
    LEFT JOIN private.atendimento_wa_entradas origem ON origem.mensagem_id = d.wa_origem_mensagem_id AND origem.tenant_id = p_tenant
    LEFT JOIN LATERAL private.atendimento_mensagem_cliente(p_tenant,p_cliente,d.wa_origem_mensagem_id) fonte ON true
    LEFT JOIN LATERAL (SELECT k.rotulo FROM private.cliente_canais_do_cliente(p_tenant,p_cliente) k
      WHERE k.tipo = origem.canal_tipo AND k.chave = origem.canal_chave LIMIT 1) canal ON true
    WHERE d.tenant_id = p_tenant AND d.cliente_id = p_cliente AND d.wa_origem_mensagem_id IS NOT NULL AND d.concluida_em IS NULL
    ORDER BY d.created_at,d.id OFFSET p_offset LIMIT p_limite
  ) x;
  RETURN jsonb_build_object('total',v_total,'tickets',v_itens);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.atendimento_sincronizar_whatsapp(p_tenant uuid, p_cliente uuid, p_pendencias jsonb, p_resolucoes uuid[], p_anterior_ate timestamp with time zone, p_analisado_ate timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  p jsonb; v_origem uuid; v_msg uuid; m record; d public.atendimento_demandas%ROWTYPE;
  v_aberta uuid; v_final uuid; v_codigo text; v_saida jsonb := '[]'::jsonb;
BEGIN
  IF current_user <> 'service_role' THEN RAISE EXCEPTION 'Worker autorizado obrigatório.' USING ERRCODE = '42501'; END IF;
  IF p_tenant IS NULL OR p_cliente IS NULL OR p_anterior_ate IS NULL
    OR p_analisado_ate IS NULL OR p_analisado_ate < p_anterior_ate
    OR p_analisado_ate > now() + interval '5 minutes'
    OR jsonb_typeof(p_pendencias) IS DISTINCT FROM 'array' OR jsonb_array_length(p_pendencias) > 5
    OR octet_length(p_pendencias::text) > 10000 OR COALESCE(cardinality(p_resolucoes), 0) > 2000 THEN
    RAISE EXCEPTION 'Entrada de sincronização inválida.' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.clients c WHERE c.id = p_cliente AND c.tenant_id = p_tenant) THEN
    RAISE EXCEPTION 'Cliente não pertence à empresa.' USING ERRCODE = '42501';
  END IF;
  IF EXISTS (SELECT 1 FROM public.app_modules WHERE tenant_id = p_tenant AND slug = 'atendimento' AND enabled IS FALSE) THEN
    RETURN jsonb_build_object('desativado', true);
  END IF;
  -- Mesmo cliente: serializa workers. A edição manual só trava sua demanda;
  -- este procedimento não escreve na memória e não cria ordem inversa de locks.
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_tenant::text || ':' || p_cliente::text, 0));
  SELECT id INTO v_aberta FROM public.atendimento_etapas WHERE tenant_id = p_tenant AND NOT is_final ORDER BY ordem, id LIMIT 1;
  SELECT id INTO v_final FROM public.atendimento_etapas WHERE tenant_id = p_tenant AND is_final ORDER BY ordem, id LIMIT 1;
  IF v_aberta IS NULL OR v_final IS NULL THEN
    RAISE EXCEPTION 'Configure etapas aberta e final antes de sincronizar tickets.' USING ERRCODE = '23514';
  END IF;

  FOR p IN SELECT value FROM jsonb_array_elements(p_pendencias) ORDER BY value->>'ticket_origem' LOOP
    IF p->>'ticket_origem' IS NULL THEN CONTINUE; END IF;
    IF p->>'ticket_origem' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      OR p->>'status' NOT IN ('aberta', 'em_andamento', 'resolvida')
      OR NULLIF(btrim(p->>'tema_curto'), '') IS NULL OR length(p->>'tema_curto') > 200 THEN
      RAISE EXCEPTION 'Pendência inválida.' USING ERRCODE = '22023';
    END IF;
    v_origem := (p->>'ticket_origem')::uuid;
    SELECT * INTO d FROM public.atendimento_demandas WHERE tenant_id = p_tenant AND cliente_id = p_cliente
      AND wa_origem_mensagem_id = v_origem FOR UPDATE;
    IF NOT FOUND THEN
      SELECT * INTO m FROM private.atendimento_mensagem_cliente(p_tenant, p_cliente, v_origem);
      IF NOT FOUND OR m.autor_tipo IS DISTINCT FROM 'cliente' OR m.criado_em <= p_anterior_ate OR m.criado_em > p_analisado_ate THEN
        CONTINUE; -- fonte antiga/inválida: não criar; a memória antiga permanece útil
      END IF;
      IF m.atestada_em IS NULL OR m.ocorrido_em IS NULL THEN
        IF m.registrado_em > clock_timestamp() - interval '5 minutes' THEN
          -- Atestação ainda pode chegar/repetir. Abortar TODA a sincronização
          -- conserva o cursor no analisador; nenhum ticket parcial é confirmado.
          RAISE EXCEPTION 'Entrada WhatsApp aguardando atestação.' USING ERRCODE = '55P03';
        END IF;
        CONTINUE; -- janela encerrada: sem prova não cria e não adia indefinidamente
      END IF;
      INSERT INTO public.atendimento_demandas (tenant_id, cliente_id, etapa_id, titulo, descricao, wa_origem_mensagem_id, wa_ultima_analise)
        VALUES (p_tenant, p_cliente, v_aberta, p->>'tema_curto', 'Solicitação identificada em mensagem do cliente no WhatsApp.', v_origem, p_analisado_ate)
        ON CONFLICT ON CONSTRAINT atendimento_demanda_wa_origem_unique DO NOTHING;
    END IF;
    UPDATE public.atendimento_demandas SET wa_ultima_analise = greatest(wa_ultima_analise, p_analisado_ate)
      WHERE tenant_id = p_tenant AND cliente_id = p_cliente AND wa_origem_mensagem_id = v_origem;
    -- Nunca sobrescrever título, dono, prazo ou etapa de trabalho definida pela equipe.
  END LOOP;

  FOREACH v_msg IN ARRAY COALESCE(p_resolucoes, ARRAY[]::uuid[]) LOOP
    SELECT * INTO m FROM private.atendimento_mensagem_cliente(p_tenant, p_cliente, v_msg);
    IF NOT FOUND OR m.autor_tipo IS DISTINCT FROM 'equipe' OR COALESCE(m.tipo, '') NOT IN ('texto', 'text', 'chat', '')
      OR m.criado_em <= p_anterior_ate OR m.criado_em > p_analisado_ate
      OR btrim(m.conteudo) !~* '^resolvido[[:space:]]+DEM-[0-9]{5,}[.!]?$' THEN CONTINUE; END IF;
    -- Nome, eco e autoria heurística não autorizam a baixa. A pessoa identificada
    -- precisa continuar ativa nesta empresa e poder editar atendimento agora.
    IF m.autor_user_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.users u
      WHERE u.id = m.autor_user_id AND u.tenant_id = p_tenant AND u.ativo IS TRUE AND u.perfil IS DISTINCT FROM 'cliente')
      OR NOT COALESCE(public.has_permissao_de(m.autor_user_id, 'atendimento', 'editar'), false) THEN CONTINUE; END IF;
    v_codigo := upper(substring(btrim(m.conteudo) FROM '(?i)DEM-[0-9]{5,}'));
    SELECT * INTO d FROM public.atendimento_demandas WHERE tenant_id = p_tenant AND cliente_id = p_cliente
      AND codigo = v_codigo AND wa_origem_mensagem_id IS NOT NULL FOR UPDATE;
    IF NOT FOUND OR d.concluida_em IS NOT NULL OR (d.wa_reaberta_em IS NOT NULL AND m.ocorrido_em <= d.wa_reaberta_em) THEN CONTINUE; END IF;
    IF NOT EXISTS (SELECT 1 FROM private.atendimento_wa_entradas origem
      WHERE origem.mensagem_id = d.wa_origem_mensagem_id AND origem.tenant_id = p_tenant
        AND origem.conversation_id = m.conversation_id) THEN CONTINUE; END IF;
    IF m.atestada_em IS NULL OR m.ocorrido_em IS NULL THEN
      IF m.registrado_em > clock_timestamp() - interval '5 minutes' THEN
        RAISE EXCEPTION 'Comando WhatsApp aguardando atestação.' USING ERRCODE = '55P03';
      END IF;
      CONTINUE; -- nunca resolver sem prova, inclusive após expirar a espera
    END IF;
    UPDATE public.atendimento_demandas SET etapa_id = v_final, wa_resolucao_mensagem_id = v_msg,
      wa_ultima_analise = greatest(wa_ultima_analise, p_analisado_ate)
      WHERE id = d.id AND tenant_id = p_tenant;
  END LOOP;

  -- Ausência no top-5 nunca encerra demanda; memória ligada segue o ticket.
  FOR p IN SELECT value FROM jsonb_array_elements(p_pendencias) LOOP
    IF p->>'ticket_origem' IS NOT NULL THEN
      SELECT * INTO d FROM public.atendimento_demandas WHERE tenant_id = p_tenant AND cliente_id = p_cliente
        AND wa_origem_mensagem_id = (p->>'ticket_origem')::uuid;
      IF FOUND THEN
        p := jsonb_set(p, '{status}', to_jsonb(CASE WHEN d.concluida_em IS NOT NULL THEN 'resolvida'::text
          WHEN p->>'status' = 'em_andamento' THEN 'em_andamento' ELSE 'aberta' END));
        IF d.concluida_em IS NOT NULL THEN p := p - 'criticidade'; END IF;
      ELSE p := p - 'ticket_origem'; END IF;
    END IF;
    v_saida := v_saida || jsonb_build_array(p - 'origem_ref');
  END LOOP;
  RETURN jsonb_build_object('pendencias', v_saida);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.atendimento_sincronizar_whatsapp_ia(p_tenant uuid, p_cliente uuid, p_pendencias jsonb, p_resolucoes uuid[], p_anterior_ate timestamp with time zone, p_analisado_ate timestamp with time zone, p_resolucoes_ia jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  r jsonb; e jsonb; v_aprovadas jsonb := '[]'::jsonb; v_base jsonb; v_pendencias jsonb := '[]'::jsonb; p jsonb;
  d public.atendimento_demandas%ROWTYPE; origem record; m record; anterior record;
  v_evidencias uuid[]; v_valida boolean; v_primeira timestamptz; v_primeira_id uuid;
  v_final uuid; v_total integer := 0; v_conf numeric; v_motivo text;
BEGIN
  IF current_user <> 'service_role' THEN RAISE EXCEPTION 'Worker autorizado obrigatório.' USING ERRCODE='42501'; END IF;
  IF p_tenant IS NULL OR p_cliente IS NULL OR p_anterior_ate IS NULL OR p_analisado_ate IS NULL
    OR p_analisado_ate < p_anterior_ate OR p_analisado_ate > now() + interval '5 minutes'
    OR jsonb_typeof(p_resolucoes_ia) IS DISTINCT FROM 'array' OR jsonb_array_length(p_resolucoes_ia) > 20
    OR octet_length(p_resolucoes_ia::text) > 30000 THEN
    RAISE EXCEPTION 'Propostas inválidas.' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.clients WHERE id=p_cliente AND tenant_id=p_tenant) THEN
    RAISE EXCEPTION 'Cliente não pertence à empresa.' USING ERRCODE='42501';
  END IF;
  IF EXISTS (SELECT 1 FROM public.app_modules WHERE tenant_id=p_tenant AND slug='atendimento' AND enabled IS FALSE) THEN
    RETURN jsonb_build_object('desativado',true);
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_tenant::text || ':' || p_cliente::text,0));

  -- Fixar/revalidar a revisão ANTES de a ponte tocar updated_at. Locks duram
  -- até o final: alterações manuais anteriores vencem; posteriores esperam.
  FOR r IN SELECT value FROM jsonb_array_elements(p_resolucoes_ia) ORDER BY value->>'origem_mensagem_id' LOOP
    IF r->>'origem_mensagem_id' IS NULL OR r->'vinculo_inequivoco' IS DISTINCT FROM 'true'::jsonb
      OR r->'solucao_completa' IS DISTINCT FROM 'true'::jsonb OR jsonb_typeof(r->'evidencias') IS DISTINCT FROM 'array'
      OR jsonb_array_length(r->'evidencias') NOT BETWEEN 1 AND 3 THEN CONTINUE; END IF;
    SELECT * INTO d FROM public.atendimento_demandas WHERE tenant_id=p_tenant AND cliente_id=p_cliente
      AND wa_origem_mensagem_id=(r->>'origem_mensagem_id')::uuid FOR UPDATE;
    IF r->>'ticket_id' IS NOT NULL THEN
      IF NOT FOUND OR d.id IS DISTINCT FROM (r->>'ticket_id')::uuid OR d.concluida_em IS NOT NULL
        OR d.updated_at IS DISTINCT FROM (r->>'revisao')::timestamptz THEN CONTINUE; END IF;
    ELSE
      -- Pedido+solução na mesma análise: só candidato realmente novo. A ponte
      -- cria e esta mesma transação fecha; não aguarda outra fala do cliente.
      IF FOUND OR r->>'revisao' IS NOT NULL OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p_pendencias) novo
        WHERE novo->>'ticket_origem'=r->>'origem_mensagem_id') THEN CONTINUE; END IF;
    END IF;
    v_aprovadas := v_aprovadas || jsonb_build_array(r);
  END LOOP;

  v_base := public.atendimento_sincronizar_whatsapp(p_tenant,p_cliente,p_pendencias,p_resolucoes,p_anterior_ate,p_analisado_ate);
  IF v_base->>'desativado'='true' THEN RETURN v_base; END IF;
  SELECT id INTO v_final FROM public.atendimento_etapas WHERE tenant_id=p_tenant AND is_final ORDER BY ordem,id LIMIT 1;

  FOR r IN SELECT value FROM jsonb_array_elements(v_aprovadas) LOOP
    v_conf := (r->>'confianca')::numeric; v_motivo := btrim(r->>'motivo');
    IF v_conf IS NULL OR v_conf < 0.93 OR v_conf > 1 OR v_motivo IS NULL OR length(v_motivo) NOT BETWEEN 12 AND 180
      OR v_motivo ~ '[@0-9<>]' OR v_motivo ~* '(https?:|www\.|R\$)'
      OR r->>'modelo' IS NULL OR r->>'modelo' !~ '^anthropic/claude-[a-z0-9.-]{1,40}$'
      OR r->>'versao' IS NULL OR length(r->>'versao') NOT BETWEEN 1 AND 100 THEN CONTINUE; END IF;
    SELECT * INTO d FROM public.atendimento_demandas WHERE tenant_id=p_tenant AND cliente_id=p_cliente
      AND wa_origem_mensagem_id=(r->>'origem_mensagem_id')::uuid FOR UPDATE;
    IF NOT FOUND OR d.concluida_em IS NOT NULL THEN CONTINUE; END IF;
    SELECT * INTO origem FROM private.atendimento_mensagem_cliente(p_tenant,p_cliente,d.wa_origem_mensagem_id);
    IF NOT FOUND OR origem.atestada_em IS NULL OR origem.ocorrido_em IS NULL THEN CONTINUE; END IF;
    v_evidencias := '{}'::uuid[]; v_valida := true; v_primeira := NULL; v_primeira_id := NULL;
    FOR e IN SELECT value FROM jsonb_array_elements(r->'evidencias') LOOP
      SELECT * INTO m FROM private.atendimento_mensagem_cliente(p_tenant,p_cliente,(e->>'mensagem_id')::uuid);
      IF NOT FOUND OR m.autor_tipo NOT IN ('cliente','equipe') OR m.tipo NOT IN ('texto','text','chat')
        OR m.conversation_id IS DISTINCT FROM origem.conversation_id OR m.id=d.wa_origem_mensagem_id
        OR m.criado_em <= p_anterior_ate OR m.criado_em > p_analisado_ate OR m.criado_em <= origem.criado_em
        OR e->>'trecho' IS NULL OR length(e->>'trecho') NOT BETWEEN 6 AND 160
        OR strpos(m.conteudo,e->>'trecho')=0 THEN v_valida:=false; EXIT; END IF;
      IF m.autor_tipo='equipe' AND (m.autor_user_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.users u
        WHERE u.id=m.autor_user_id AND u.tenant_id=p_tenant AND u.ativo IS TRUE AND u.perfil IS DISTINCT FROM 'cliente')) THEN
        v_valida:=false; EXIT;
      END IF;
      IF m.atestada_em IS NULL OR m.ocorrido_em IS NULL THEN
        IF m.registrado_em > clock_timestamp()-interval '5 minutes' THEN
          RAISE EXCEPTION 'Evidência natural aguardando atestação.' USING ERRCODE='55P03';
        END IF;
        v_valida:=false; EXIT;
      END IF;
      IF m.ocorrido_em <= origem.ocorrido_em OR (d.wa_reaberta_em IS NOT NULL AND m.ocorrido_em <= d.wa_reaberta_em)
        OR m.id=ANY(v_evidencias) THEN v_valida:=false; EXIT; END IF;
      v_evidencias:=array_append(v_evidencias,m.id);
      IF v_primeira IS NULL OR m.criado_em<v_primeira THEN v_primeira:=m.criado_em; v_primeira_id:=m.id; END IF;
    END LOOP;
    IF NOT v_valida THEN CONTINUE; END IF;
    IF r->>'antecedente_mensagem_id' IS NOT NULL THEN
      SELECT * INTO anterior FROM private.atendimento_mensagem_cliente(p_tenant,p_cliente,(r->>'antecedente_mensagem_id')::uuid);
      IF NOT FOUND OR anterior.conversation_id IS DISTINCT FROM origem.conversation_id OR anterior.autor_tipo NOT IN ('cliente','equipe')
        OR anterior.criado_em>=v_primeira OR anterior.criado_em<v_primeira-interval '30 minutes' THEN CONTINUE; END IF;
      IF anterior.atestada_em IS NULL OR anterior.ocorrido_em IS NULL THEN
        IF anterior.registrado_em>clock_timestamp()-interval '5 minutes' THEN
          RAISE EXCEPTION 'Antecedente aguardando atestação.' USING ERRCODE='55P03';
        END IF;
        CONTINUE;
      END IF;
      IF EXISTS (SELECT 1 FROM public.chat_messages outra WHERE outra.tenant_id=p_tenant
        AND outra.conversation_id=origem.conversation_id AND outra.criado_em>anterior.criado_em AND outra.criado_em<v_primeira) THEN CONTINUE; END IF;
    END IF;
    UPDATE public.atendimento_demandas SET etapa_id=v_final, wa_resolucao_mensagem_id=v_primeira_id,
      wa_resolucao_metodo='ia', wa_resolucao_motivo=v_motivo, wa_resolucao_confianca=v_conf,
      wa_resolucao_evidencias=v_evidencias, wa_ultima_analise=greatest(wa_ultima_analise,p_analisado_ate)
      ,wa_resolucao_modelo=r->>'modelo',wa_resolucao_versao=r->>'versao'
      WHERE id=d.id AND tenant_id=p_tenant RETURNING * INTO d;
    -- Mesma transação da baixa: qualquer falha no recibo também desfaz a baixa.
    -- Valores vêm da decisão validada pelo worker, não de edição do navegador.
    INSERT INTO private.atendimento_resolucoes_ia_recibos
      (tenant_id,cliente_id,demanda_id,origem_mensagem_id,evidencia_mensagem_ids,
       antecedente_mensagem_id,motivo,modelo,versao,confianca,revisao_observada,concluida_em)
    VALUES(p_tenant,p_cliente,d.id,d.wa_origem_mensagem_id,v_evidencias,
      (r->>'antecedente_mensagem_id')::uuid,v_motivo,r->>'modelo',r->>'versao',v_conf,
      (r->>'revisao')::timestamptz,d.concluida_em);
    v_total:=v_total+1;
  END LOOP;
  -- A memória recebe o resultado transacional, não a sugestão bruta do modelo.
  FOR p IN SELECT value FROM jsonb_array_elements(v_base->'pendencias') LOOP
    IF p->>'ticket_origem' IS NOT NULL AND EXISTS (SELECT 1 FROM public.atendimento_demandas
      WHERE tenant_id=p_tenant AND cliente_id=p_cliente AND wa_origem_mensagem_id=(p->>'ticket_origem')::uuid AND concluida_em IS NOT NULL) THEN
      p:=jsonb_set(p-'criticidade','{status}','"resolvida"'::jsonb);
    END IF;
    v_pendencias:=v_pendencias||jsonb_build_array(p);
  END LOOP;
  RETURN jsonb_build_object('pendencias',v_pendencias,'resolvidas_ia',v_total);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.atendimento_sugerir_resolucao_ia(p_tenant uuid, p_cliente uuid, p_sugestoes jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  r jsonb; e jsonb; d public.atendimento_demandas%ROWTYPE; origem record; m record;
  v_evidencias uuid[]; v_valida boolean; v_total integer := 0; v_conf numeric; v_motivo text;
  c_uuid constant text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
BEGIN
  IF current_user <> 'service_role' THEN RAISE EXCEPTION 'Worker autorizado obrigatório.' USING ERRCODE = '42501'; END IF;
  IF p_tenant IS NULL OR p_cliente IS NULL OR jsonb_typeof(p_sugestoes) IS DISTINCT FROM 'array'
    OR jsonb_array_length(p_sugestoes) > 20 OR octet_length(p_sugestoes::text) > 30000 THEN
    RAISE EXCEPTION 'Sugestões inválidas.' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.clients WHERE id = p_cliente AND tenant_id = p_tenant) THEN
    RAISE EXCEPTION 'Cliente não pertence à empresa.' USING ERRCODE = '42501';
  END IF;
  IF EXISTS (SELECT 1 FROM public.app_modules WHERE tenant_id = p_tenant AND slug = 'atendimento' AND enabled IS FALSE) THEN
    RETURN 0;
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_tenant::text || ':' || p_cliente::text, 0));

  FOR r IN SELECT value FROM jsonb_array_elements(p_sugestoes) LOOP
    IF jsonb_typeof(r) IS DISTINCT FROM 'object' OR COALESCE(r->>'origem_mensagem_id', '') !~ c_uuid
      OR (r->>'ticket_id' IS NOT NULL AND r->>'ticket_id' !~ c_uuid)
      OR jsonb_typeof(r->'confianca') IS DISTINCT FROM 'number'
      OR r->>'razao' IS NULL OR r->>'razao' NOT IN ('confianca_media','vinculo_ambiguo','so_equipe','generica_ambigua','evidencia_compartilhada','pedido_cliente')
      OR jsonb_typeof(r->'evidencias') IS DISTINCT FROM 'array' OR jsonb_array_length(r->'evidencias') NOT BETWEEN 1 AND 3
      OR r->>'modelo' IS NULL OR r->>'modelo' !~ '^anthropic/claude-[a-z0-9.-]{1,40}$'
      OR r->>'versao' IS NULL OR length(r->>'versao') NOT BETWEEN 1 AND 100 THEN CONTINUE; END IF;
    v_conf := (r->>'confianca')::numeric; v_motivo := btrim(r->>'motivo');
    IF v_conf < 0.6 OR v_conf > 1 OR v_motivo IS NULL OR length(v_motivo) NOT BETWEEN 12 AND 180
      OR v_motivo ~ '[@0-9<>]' OR v_motivo ~* '(https?:|www\.|R\$)' THEN CONTINUE; END IF;
    SELECT * INTO d FROM public.atendimento_demandas WHERE tenant_id = p_tenant AND cliente_id = p_cliente
      AND wa_origem_mensagem_id = (r->>'origem_mensagem_id')::uuid FOR UPDATE;
    IF NOT FOUND OR d.concluida_em IS NOT NULL
      OR (r->>'ticket_id' IS NOT NULL AND d.id IS DISTINCT FROM (r->>'ticket_id')::uuid) THEN CONTINUE; END IF;
    SELECT * INTO origem FROM private.atendimento_mensagem_cliente(p_tenant, p_cliente, d.wa_origem_mensagem_id);
    IF NOT FOUND OR origem.atestada_em IS NULL OR origem.ocorrido_em IS NULL THEN CONTINUE; END IF;
    v_evidencias := '{}'::uuid[]; v_valida := true;
    FOR e IN SELECT value FROM jsonb_array_elements(r->'evidencias') LOOP
      IF COALESCE(e->>'mensagem_id', '') !~ c_uuid THEN v_valida := false; EXIT; END IF;
      SELECT * INTO m FROM private.atendimento_mensagem_cliente(p_tenant, p_cliente, (e->>'mensagem_id')::uuid);
      IF NOT FOUND OR m.autor_tipo NOT IN ('cliente','equipe') OR m.tipo NOT IN ('texto','text','chat')
        OR m.conversation_id IS DISTINCT FROM origem.conversation_id OR m.id = d.wa_origem_mensagem_id
        OR m.atestada_em IS NULL OR m.ocorrido_em IS NULL OR m.ocorrido_em <= origem.ocorrido_em
        OR (d.wa_reaberta_em IS NOT NULL AND m.ocorrido_em <= d.wa_reaberta_em)
        OR e->>'trecho' IS NULL OR length(e->>'trecho') NOT BETWEEN 6 AND 160 OR strpos(m.conteudo, e->>'trecho') = 0
        OR m.id = ANY(v_evidencias) THEN v_valida := false; EXIT; END IF;
      IF m.autor_tipo = 'equipe' AND (m.autor_user_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.users u
        WHERE u.id = m.autor_user_id AND u.tenant_id = p_tenant AND u.ativo IS TRUE AND u.perfil IS DISTINCT FROM 'cliente')) THEN
        v_valida := false; EXIT;
      END IF;
      v_evidencias := array_append(v_evidencias, m.id);
    END LOOP;
    IF NOT v_valida THEN CONTINUE; END IF;
    -- A mesma sugestão (mesmas provas) não reescreve a fila nem o histórico.
    IF d.wa_sugestao_em IS NOT NULL AND d.wa_sugestao_evidencias = v_evidencias THEN CONTINUE; END IF;
    UPDATE public.atendimento_demandas SET wa_sugestao_em = clock_timestamp(), wa_sugestao_razao = r->>'razao',
      wa_sugestao_motivo = v_motivo, wa_sugestao_confianca = round(v_conf, 3), wa_sugestao_evidencias = v_evidencias,
      wa_sugestao_modelo = r->>'modelo', wa_sugestao_versao = r->>'versao'
      WHERE id = d.id AND tenant_id = p_tenant;
    v_total := v_total + 1;
  END LOOP;
  RETURN v_total;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.audit_contratos()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID;
  v_campos TEXT[] := ARRAY[
    'cliente_nome','empresa','cpf_cnpj','whatsapp','email','instagram',
    'nicho','faturamento','endereco','posicionamento','resumo',
    'produto_nome','status','status_secundario','data_fechamento','vencimento',
    'plano_dias','semanas','renovacao',
    'valor_total','valor_parcela','num_parcelas','percentual_aplicado',
    'entrada','pg_entrada','forma_pagamento','fat_bruto','bonus','link_clicksign',
    'venda_interna','venda_diretoria',
    'estrategista_id','estrategista_nome_raw','vendedor','treinador',
    'seguidores_inicio','seguidores_fim','crescimento_seguidores',
    'videos_postados','entregas_no_prazo','entregas_totais','nps_vip',
    'observacoes','cliente_id','vigencia_fim','vigencia_motivo'
  ];
  v_campo TEXT;
  v_old  TEXT;
  v_new  TEXT;
BEGIN
  v_user := COALESCE(auth.uid(), NULL);

  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.contratos_audit_log (contrato_id, operacao, alterado_por, tenant_id)
    VALUES (NEW.id, 'INSERT', v_user, NEW.tenant_id);
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    INSERT INTO public.contratos_audit_log (contrato_id, operacao, alterado_por, tenant_id)
    VALUES (OLD.id, 'DELETE', v_user, OLD.tenant_id);
    RETURN OLD;
  END IF;

  FOREACH v_campo IN ARRAY v_campos LOOP
    EXECUTE format('SELECT ($1).%I::text, ($2).%I::text', v_campo, v_campo)
      INTO v_old, v_new USING OLD, NEW;
    IF v_old IS DISTINCT FROM v_new THEN
      INSERT INTO public.contratos_audit_log
        (contrato_id, operacao, campo, valor_antigo, valor_novo, alterado_por, tenant_id)
      VALUES (NEW.id, 'UPDATE', v_campo, v_old, v_new, v_user, NEW.tenant_id);
    END IF;
  END LOOP;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.auto_add_admins_to_dept_group()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.tipo = 'department' THEN
    INSERT INTO internal_conversation_members (conversation_id, user_id, role, tenant_id)
    SELECT NEW.id, u.id, 'admin', NEW.tenant_id
    FROM users u
    WHERE u.perfil = 'admin' AND u.ativo = true
      AND u.tenant_id = NEW.tenant_id
    ON CONFLICT (conversation_id, user_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.auto_match_contacts_to_clients()
 RETURNS TABLE(contact_id uuid, contact_nome text, client_id uuid, client_nome text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  WITH normalized_clients AS (
    SELECT c.id, c.nome, REGEXP_REPLACE(c.telefone, '[^0-9]', '', 'g') as phone_digits
    FROM clients c
    WHERE c.telefone IS NOT NULL AND c.telefone != ''
  ),
  matches AS (
    SELECT DISTINCT ON (cc.id)
      cc.id as contact_id, cc.nome as contact_nome,
      nc.id as matched_client_id, nc.nome as client_nome
    FROM chat_contacts cc
    JOIN normalized_clients nc ON (
      RIGHT(REGEXP_REPLACE(cc.numero_whatsapp, '[^0-9]', '', 'g'), 11) = RIGHT(nc.phone_digits, 11)
    )
    WHERE cc.client_id IS NULL
    ORDER BY cc.id, nc.nome
  )
  UPDATE chat_contacts SET client_id = m.matched_client_id
  FROM matches m
  WHERE chat_contacts.id = m.contact_id
  RETURNING chat_contacts.id, chat_contacts.nome, chat_contacts.client_id, m.client_nome;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calcular_comissoes_contrato(p_contrato_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c RECORD;
  pc RECORD;
  v_offset INT;
  v_primeiro_mes DATE;
  v_valor_parcela NUMERIC(12,2);
  v_valor_comissao NUMERIC(12,2);
  v_mes_bonus DATE;
  i INT;
BEGIN
  SELECT * INTO c FROM public.contratos WHERE id = p_contrato_id;
  IF NOT FOUND THEN RETURN; END IF;

  IF c.notion_page_id IS NOT NULL THEN
    IF c.estrategista_id IS NOT NULL THEN
      UPDATE public.comissoes
         SET estrategista_id = c.estrategista_id,
             cliente_nome    = c.cliente_nome
       WHERE contrato_id = p_contrato_id
         AND status = 'prevista'
         AND estrategista_id IS DISTINCT FROM c.estrategista_id;
    END IF;
    RETURN;
  END IF;

  DELETE FROM public.comissoes
   WHERE contrato_id = p_contrato_id AND status = 'prevista';

  IF c.status <> 'ativo' THEN RETURN; END IF;
  IF c.num_parcelas IS NULL OR c.num_parcelas < 1 THEN RETURN; END IF;
  IF c.estrategista_id IS NULL THEN RETURN; END IF;

  IF c.data_fechamento IS NULL OR c.data_fechamento <= DATE '1900-01-01' THEN
    RETURN;
  END IF;

  v_offset := CASE WHEN EXTRACT(DAY FROM c.data_fechamento) <= 15 THEN 1 ELSE 2 END;
  v_primeiro_mes := date_trunc('month', c.data_fechamento + (v_offset || ' months')::interval)::date;

  v_valor_parcela := round(c.valor_total / c.num_parcelas, 2);

  SELECT tipo_comissao, valor_comissao_padrao, percentual_padrao, valor_bonus, bonus_condicional
    INTO pc
    FROM public.produtos_comissao
   WHERE produto_id = c.produto_id
     AND tenant_id = c.tenant_id;

  IF FOUND AND pc.tipo_comissao = 'valor_fixo' THEN
    v_valor_comissao := pc.valor_comissao_padrao;
  ELSIF FOUND AND pc.tipo_comissao = 'valor_total' THEN
    v_valor_comissao := round(pc.valor_comissao_padrao / c.num_parcelas, 2);
  ELSIF FOUND AND pc.tipo_comissao = 'percentual' THEN
    v_valor_comissao := round(v_valor_parcela * (pc.percentual_padrao / 100.0), 2);
  ELSE
    v_valor_comissao := round(v_valor_parcela * (c.percentual_aplicado / 100.0), 2);
  END IF;

  FOR i IN 1..c.num_parcelas LOOP
    INSERT INTO public.comissoes (
      contrato_id, estrategista_id, cliente_nome,
      parcela_num, total_parcelas, mes_referencia,
      valor_calculado, valor_final, status, eh_bonus, tenant_id
    ) VALUES (
      c.id, c.estrategista_id, c.cliente_nome,
      i, c.num_parcelas,
      (v_primeiro_mes + ((i - 1) || ' months')::interval)::date,
      v_valor_comissao, v_valor_comissao, 'prevista', false, c.tenant_id
    );
  END LOOP;

  IF FOUND AND COALESCE(pc.valor_bonus, 0) > 0 THEN
    v_mes_bonus := (v_primeiro_mes + ((c.num_parcelas - 1) || ' months')::interval)::date;
    INSERT INTO public.comissoes (
      contrato_id, estrategista_id, cliente_nome,
      parcela_num, total_parcelas, mes_referencia,
      valor_calculado, valor_final, status, eh_bonus, tenant_id
    ) VALUES (
      c.id, c.estrategista_id, c.cliente_nome,
      c.num_parcelas + 1, c.num_parcelas, v_mes_bonus,
      pc.valor_bonus, pc.valor_bonus, 'prevista', true, c.tenant_id
    );
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.chat_contact_clients_para_canal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR current_setting('omnx.vinculo_sync', true) = 'on' THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'INSERT' THEN
    PERFORM private.vinculo_do_chat(NEW.contact_id, NEW.client_id, true);
  ELSE
    PERFORM private.vinculo_do_chat(OLD.contact_id, OLD.client_id, false);
  END IF;
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.chat_contacts_client_para_canal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR current_setting('omnx.vinculo_sync', true) = 'on' OR NEW.client_id IS NULL THEN
    RETURN NULL;
  END IF;
  PERFORM private.vinculo_do_chat(NEW.id, NEW.client_id, true);
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.chat_contacts_herda_restrito()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_tenant UUID := NEW.tenant_id;
  v_base   TEXT;
BEGIN
  -- Usuário logado não desmarca (nem admin): só o banco, sem sessão.
  IF TG_OP = 'UPDATE' AND OLD.restrito_admin AND NOT NEW.restrito_admin
     AND auth.uid() IS NOT NULL THEN
    NEW.restrito_admin := true;
  END IF;

  IF NEW.restrito_admin THEN
    RETURN NEW;
  END IF;

  IF v_tenant IS NULL AND NEW.instance_id IS NOT NULL THEN
    SELECT wi.tenant_id INTO v_tenant FROM public.whatsapp_instances wi WHERE wi.id = NEW.instance_id;
  END IF;
  IF v_tenant IS NULL OR NEW.numero_whatsapp IS NULL THEN
    RETURN NEW;
  END IF;

  v_base := lower(btrim(NEW.numero_whatsapp));
  IF right(v_base, 5) = '@g.us' THEN
    v_base := left(v_base, length(v_base) - 5);
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.chat_grupos_restritos g
     WHERE g.tenant_id = v_tenant AND g.grupo_base = v_base
  ) THEN
    NEW.restrito_admin := true;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.chat_contacts_herda_vinculo()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_tipo  TEXT;
  v_chave TEXT;
  v_cli   UUID;
  v_ids   UUID[];
BEGIN
  IF NEW.restrito_admin OR NEW.client_id IS NOT NULL OR NEW.tenant_id IS NULL THEN
    RETURN NEW;
  END IF;
  v_tipo := private.canal_tipo(NEW.numero_whatsapp, NEW.group_size);
  v_chave := private.canal_chave(NEW.numero_whatsapp, NEW.group_size);
  IF v_chave IS NULL THEN
    RETURN NEW;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.cliente_canais c
     WHERE c.tenant_id = NEW.tenant_id AND c.tipo = v_tipo AND c.chave = v_chave
       AND c.client_id IS NULL AND c.status IN ('interno', 'nao_cliente')
  ) THEN
    RETURN NEW;
  END IF;

  SELECT c.client_id INTO v_cli
    FROM public.cliente_canais c
   WHERE c.tenant_id = NEW.tenant_id AND c.tipo = v_tipo AND c.chave = v_chave
     AND c.status = 'confirmado' AND c.client_id IS NOT NULL
   ORDER BY COALESCE(c.revisado_em, c.criado_em), c.id
   LIMIT 1;

  IF v_cli IS NULL AND v_tipo = 'privado' THEN
    v_ids := ARRAY(
      SELECT u FROM unnest(private.clientes_por_telefone(NEW.tenant_id, private.tel_cmp_contato(v_chave))) AS u
      EXCEPT
      SELECT c.client_id FROM public.cliente_canais c
       WHERE c.tenant_id = NEW.tenant_id AND c.tipo = v_tipo AND c.chave = v_chave AND c.status = 'rejeitado'
    );
    IF cardinality(v_ids) = 1 THEN
      v_cli := v_ids[1];
    END IF;
  END IF;

  -- Usuário logado só recebe aqui cliente que ele enxerga (senão a RLS do Chat
  -- recusaria o INSERT); o vínculo do canal chega depois pela sincronização.
  IF v_cli IS NOT NULL AND (auth.uid() IS NULL OR COALESCE(public.user_can_access_client(v_cli), false)) THEN
    NEW.client_id := v_cli;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.chat_contacts_vinculo_pos()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_tipo   TEXT;
  v_chave  TEXT;
  v_ids    UUID[];
  v_origem TEXT;
BEGIN
  IF NEW.restrito_admin OR NEW.tenant_id IS NULL THEN
    RETURN NULL;
  END IF;
  v_tipo := private.canal_tipo(NEW.numero_whatsapp, NEW.group_size);
  v_chave := private.canal_chave(NEW.numero_whatsapp, NEW.group_size);
  IF v_chave IS NULL THEN
    RETURN NULL;
  END IF;

  -- Contato criado por uma PESSOA já com cliente: mesmas regras do Chat.
  IF NEW.client_id IS NOT NULL AND auth.uid() IS NOT NULL THEN
    PERFORM private.vinculo_do_chat(NEW.id, NEW.client_id, true);
    IF EXISTS (
      SELECT 1 FROM public.cliente_canais c
       WHERE c.tenant_id = NEW.tenant_id AND c.tipo = v_tipo AND c.chave = v_chave AND c.status = 'confirmado'
    ) THEN
      PERFORM private.vinculo_sincronizar(NEW.tenant_id, v_tipo, v_chave);
    END IF;
    RETURN NULL;
  END IF;

  -- Servidor (webhook, sem sessão): telefone único ou client_id enviado.
  IF NEW.client_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.clients cl WHERE cl.id = NEW.client_id AND cl.tenant_id = NEW.tenant_id)
     AND NOT EXISTS (
       SELECT 1 FROM public.cliente_canais c
        WHERE c.tenant_id = NEW.tenant_id AND c.tipo = v_tipo AND c.chave = v_chave
          AND (c.client_id = NEW.client_id OR (c.client_id IS NULL AND c.status IN ('interno', 'nao_cliente')))
     ) THEN
    v_origem := 'legado';
    IF v_tipo = 'privado' THEN
      v_ids := private.clientes_por_telefone(NEW.tenant_id, private.tel_cmp_contato(v_chave));
      IF v_ids = ARRAY[NEW.client_id] THEN
        v_origem := 'telefone';
      END IF;
    END IF;
    INSERT INTO public.cliente_canais
      (tenant_id, client_id, tipo, chave, status, origem, score, evidencias, revisado_por, revisado_em)
    VALUES (
      NEW.tenant_id, NEW.client_id, v_tipo, v_chave, 'confirmado', v_origem, 1,
      CASE WHEN v_origem = 'telefone' THEN '{"telefone":"unico"}'::jsonb ELSE '{}'::jsonb END,
      NULL, NULL
    )
    ON CONFLICT (tenant_id, tipo, chave, (COALESCE(client_id, '00000000-0000-0000-0000-000000000000'::uuid)))
    DO NOTHING; -- o gatilho de cliente_canais sincroniza
  ELSIF EXISTS (
    SELECT 1 FROM public.cliente_canais c
     WHERE c.tenant_id = NEW.tenant_id AND c.tipo = v_tipo AND c.chave = v_chave AND c.status = 'confirmado'
  ) THEN
    PERFORM private.vinculo_sincronizar(NEW.tenant_id, v_tipo, v_chave);
  END IF;
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.chat_grupos_restritos_vinculo()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.tenant_id IS NOT NULL AND private.canal_chave(NEW.grupo_base, 1) IS NOT NULL THEN
    INSERT INTO public.cliente_canais (tenant_id, client_id, tipo, chave, status, origem, evidencias)
    VALUES (NEW.tenant_id, NULL, 'grupo', private.canal_chave(NEW.grupo_base, 1), 'interno', 'manual', '{}'::jsonb)
    ON CONFLICT (tenant_id, tipo, chave, (COALESCE(client_id, '00000000-0000-0000-0000-000000000000'::uuid)))
    DO NOTHING;
  END IF;
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.chat_messages_autor_padrao()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  -- Sessão de usuário (front): a autoria vem das flags, nunca do navegador.
  IF v_uid IS NOT NULL THEN
    NEW.autor_tipo := NULL;
    NEW.autor_user_id := NULL;
    NEW.autor_chave := NULL;
    NEW.autor_nome := NULL;
    NEW.autor_origem := NULL;
  END IF;
  IF NEW.autor_tipo IS NULL THEN
    IF NEW.enviado_por_ia IS TRUE THEN
      NEW.autor_tipo := 'ia';
      NEW.autor_origem := 'plataforma';
    ELSIF NEW.enviado_por_agente IS TRUE THEN
      NEW.autor_tipo := 'equipe';
      NEW.autor_user_id := coalesce(v_uid, NEW.agente_id);
      NEW.autor_origem := 'plataforma';
    END IF;
    -- Sem flag e sem autor: fica NULL (ex.: webhook antigo) e o gatilho de
    -- "aguardando" usa a regra antiga.
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.chat_messages_autor_protege()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF auth.uid() IS NOT NULL THEN
    NEW.autor_tipo := OLD.autor_tipo;
    NEW.autor_user_id := OLD.autor_user_id;
    NEW.autor_chave := OLD.autor_chave;
    NEW.autor_nome := OLD.autor_nome;
    NEW.autor_origem := OLD.autor_origem;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.chat_midia_reivindicar(p_limite integer DEFAULT 20, p_max_tenant_dia integer DEFAULT 300)
 RETURNS TABLE(message_id uuid, tenant_id uuid, tipo text, tentativas smallint, conversation_id uuid, media_url text, caminho text, tamanho bigint, mimetype text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
#variable_conflict use_column
DECLARE
  v_limite int := least(greatest(coalesce(p_limite, 20), 1), 50);
  v_max int := least(greatest(coalesce(p_max_tenant_dia, 300), 0), 5000);
  v_inicio_dia timestamptz := date_trunc('day', now() AT TIME ZONE 'America/Sao_Paulo') AT TIME ZONE 'America/Sao_Paulo';
BEGIN
  -- a) Travados: a função caiu no meio da 3ª tentativa (aluguel vencido).
  UPDATE public.chat_midia_texto q
     SET status = 'falhou', erro_code = 'tempo_esgotado', reivindicado_em = NULL, processado_em = now()
   WHERE q.status = 'pendente' AND q.tentativas >= 3
     AND q.reivindicado_em < now() - interval '10 minutes';

  -- b) A conversa virou grupo interno depois de entrar na fila.
  UPDATE public.chat_midia_texto q
     SET status = 'ignorado', erro_code = 'restrito', reivindicado_em = NULL, processado_em = now()
   WHERE q.status = 'pendente'
     AND EXISTS (
       SELECT 1
         FROM public.chat_messages m
         JOIN public.chat_conversations cv ON cv.id = m.conversation_id
         JOIN public.chat_contacts c ON c.id = cv.contact_id
        WHERE m.id = q.message_id AND c.restrito_admin
     );

  -- c) A empresa desligou o app.
  UPDATE public.chat_midia_texto q
     SET status = 'ignorado', erro_code = 'app_desligado', reivindicado_em = NULL, processado_em = now()
   WHERE q.status = 'pendente'
     AND NOT EXISTS (
       SELECT 1 FROM public.app_modules a
        WHERE a.tenant_id = q.tenant_id AND a.slug = 'automacoes-wa' AND a.enabled
     );

  -- d) Lote: pendentes vencidos, sem aluguel ativo, com menos de 3 tentativas,
  --    de empresas abaixo do limite do dia (reivindicações desde 00:00 BRT; o lote
  --    pode passar do limite em até p_limite − 1). Mais novas primeiro.
  RETURN QUERY
  WITH uso AS (
    SELECT u.tenant_id, count(*) AS n
      FROM public.chat_midia_texto u
     WHERE u.reivindicado_em >= v_inicio_dia
     GROUP BY u.tenant_id
  ),
  cand AS (
    SELECT q.message_id
      FROM public.chat_midia_texto q
      LEFT JOIN uso ON uso.tenant_id = q.tenant_id
     WHERE q.status = 'pendente'
       AND q.proxima_tentativa_em <= now()
       AND q.tentativas < 3
       AND (q.reivindicado_em IS NULL OR q.reivindicado_em < now() - interval '10 minutes')
       AND coalesce(uso.n, 0) < v_max
     ORDER BY q.mensagem_em DESC
     LIMIT v_limite
     FOR UPDATE OF q SKIP LOCKED
  ),
  marcados AS (
    UPDATE public.chat_midia_texto q
       SET reivindicado_em = now(), tentativas = q.tentativas + 1
      FROM cand
     WHERE q.message_id = cand.message_id
    RETURNING q.message_id, q.tenant_id, q.tipo, q.tentativas
  )
  SELECT mk.message_id, mk.tenant_id, mk.tipo, mk.tentativas,
         m.conversation_id, m.media_url,
         private.chat_midia_caminho(m.media_url, m.conversation_id) AS caminho,
         (o.metadata ->> 'size')::bigint AS tamanho,
         (o.metadata ->> 'mimetype') AS mimetype
    FROM marcados mk
    JOIN public.chat_messages m ON m.id = mk.message_id AND m.tenant_id = mk.tenant_id
    LEFT JOIN storage.objects o
      ON o.bucket_id = 'chat-media'
     AND o.name = private.chat_midia_caminho(m.media_url, m.conversation_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.check_employee_self_management()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.manager_id = NEW.id THEN
    RAISE EXCEPTION 'Um funcionário não pode ser seu próprio gestor';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.check_position_cycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  visited_ids UUID[];
  current_id  UUID;
BEGIN
  IF NEW.reports_to_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.reports_to_id = NEW.id THEN
    RAISE EXCEPTION 'Um cargo não pode reportar para si mesmo';
  END IF;

  visited_ids := ARRAY[NEW.id];
  current_id  := NEW.reports_to_id;

  WHILE current_id IS NOT NULL LOOP
    IF current_id = ANY(visited_ids) THEN
      RAISE EXCEPTION 'Ciclo detectado na hierarquia de cargos';
    END IF;
    visited_ids := array_append(visited_ids, current_id);
    SELECT reports_to_id INTO current_id FROM public.positions WHERE id = current_id;
  END LOOP;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.clean_stale_typing()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  DELETE FROM internal_typing_indicators WHERE started_at < now() - interval '10 seconds';
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.client_assignment_contexto(p_client_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_ctx jsonb; v_tenant uuid; v_rev bigint := 0; v_desde timestamptz; v_atuais jsonb; v_inativos jsonb;
  v_elegiveis jsonb := '[]'::jsonb; v_historico jsonb;
BEGIN
  v_ctx := private.client_assignment_autorizar(p_client_id,false); v_tenant := (v_ctx->>'tenant_id')::uuid;
  SELECT revisao,historico_desde INTO v_rev,v_desde FROM public.client_assignment_state WHERE client_id=p_client_id AND tenant_id=v_tenant;
  IF NOT FOUND THEN v_rev:=0; v_desde:=NULL; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.tipo,a.usuario_nome,a.id) FILTER (WHERE a.ativo),'[]'::jsonb),
    coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.tipo,a.usuario_nome,a.id) FILTER (WHERE NOT a.ativo),'[]'::jsonb)
    INTO v_atuais,v_inativos FROM (
      SELECT a.id,a.client_id,a.user_id,a.tipo,a.ativo,a.criado_em,u.nome AS usuario_nome,u.ativo AS usuario_ativo
       FROM public.client_assignments a JOIN public.users u ON u.id=a.user_id AND u.tenant_id=v_tenant
       WHERE a.client_id=p_client_id AND a.tenant_id=v_tenant
    ) a;
  IF coalesce(public.has_permissao('clientes.atribuir','editar'),false) THEN
    SELECT coalesce(jsonb_agg(to_jsonb(u) ORDER BY u.nome,u.id),'[]'::jsonb) INTO v_elegiveis FROM (
      SELECT u.id,u.nome,array_remove(ARRAY[
        CASE WHEN private.client_assignment_elegivel(v_tenant,u.id,'estrategista') THEN 'estrategista' END,
        CASE WHEN private.client_assignment_elegivel(v_tenant,u.id,'atendimento') THEN 'atendimento' END],NULL) AS tipos
       FROM public.users u WHERE u.tenant_id=v_tenant AND u.ativo IS TRUE AND u.perfil<>'cliente'
        AND (private.client_assignment_elegivel(v_tenant,u.id,'estrategista') OR private.client_assignment_elegivel(v_tenant,u.id,'atendimento'))
       ORDER BY u.nome,u.id LIMIT 201
    ) u;
    IF jsonb_array_length(v_elegiveis)>200 THEN RAISE EXCEPTION USING ERRCODE='54000', MESSAGE='atribuicao_lista_limite'; END IF;
  END IF;
  v_historico := public.client_assignment_historico(p_client_id,NULL);
  RETURN jsonb_build_object('client_id',p_client_id,'revisao',v_rev,'historico_desde',v_desde,
    'atuais',coalesce(v_atuais,'[]'::jsonb),'legados_inativos',coalesce(v_inativos,'[]'::jsonb),
    'usuarios_elegiveis',v_elegiveis,'historico',v_historico->'eventos','historico_proximo_cursor',v_historico->'proximo_cursor');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.client_assignment_decidir(p_client_id uuid, p_acao text, p_tipo text, p_assignment_id uuid, p_user_id uuid, p_revisao_esperada bigint, p_idempotencia uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_ctx jsonb; v_tenant uuid; v_ator uuid; v_pedido jsonb; v_op public.client_assignment_operations%ROWTYPE;
  v_old public.client_assignments%ROWTYPE; v_new public.client_assignments%ROWTYPE; v_rev bigint; v_eventos jsonb; v_resposta jsonb;
BEGIN
  v_ctx := private.client_assignment_autorizar(p_client_id, true);
  v_tenant := (v_ctx->>'tenant_id')::uuid; v_ator := (v_ctx->>'ator_id')::uuid;
  IF p_acao IS NULL OR p_acao NOT IN ('adicionar','trocar','encerrar')
    OR p_tipo IS NULL OR p_tipo NOT IN ('estrategista','atendimento')
    OR p_revisao_esperada IS NULL OR p_revisao_esperada < 0 OR p_idempotencia IS NULL
    OR p_motivo IS NULL OR length(btrim(p_motivo)) NOT BETWEEN 3 AND 500
    OR (p_acao = 'adicionar' AND (p_assignment_id IS NOT NULL OR p_user_id IS NULL))
    OR (p_acao = 'trocar' AND (p_assignment_id IS NULL OR p_user_id IS NULL))
    OR (p_acao = 'encerrar' AND (p_assignment_id IS NULL OR p_user_id IS NOT NULL)) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='atribuicao_parametros_invalidos';
  END IF;
  v_pedido := jsonb_build_object('acao',p_acao,'tipo',p_tipo,'assignment_id',p_assignment_id,'user_id',p_user_id,
    'revisao_esperada',p_revisao_esperada,'motivo',btrim(p_motivo));
  -- Autorização atual já relida sob o mesmo mutex ANTES de devolver recibo de retry.
  SELECT * INTO v_op FROM public.client_assignment_operations WHERE tenant_id = v_tenant
    AND client_id = p_client_id AND ator_id = v_ator AND idempotencia = p_idempotencia;
  IF FOUND THEN
    IF v_op.pedido IS DISTINCT FROM v_pedido THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='atribuicao_idempotencia_incompativel'; END IF;
    IF v_op.resposta IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='atribuicao_estado_alterado'; END IF;
    RETURN v_op.resposta || jsonb_build_object('repetida',true);
  END IF;
  INSERT INTO public.client_assignment_state (client_id,tenant_id) VALUES (p_client_id,v_tenant) ON CONFLICT (client_id) DO NOTHING;
  SELECT revisao INTO STRICT v_rev FROM public.client_assignment_state WHERE client_id=p_client_id AND tenant_id=v_tenant FOR UPDATE;
  IF v_rev <> p_revisao_esperada THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='atribuicao_estado_alterado'; END IF;
  IF p_assignment_id IS NOT NULL THEN
    SELECT * INTO v_old FROM public.client_assignments WHERE id=p_assignment_id AND client_id=p_client_id AND tenant_id=v_tenant FOR UPDATE;
    IF NOT FOUND OR v_old.tipo <> p_tipo THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='atribuicao_estado_alterado'; END IF;
    IF p_acao='trocar' AND v_old.user_id=p_user_id THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='atribuicao_parametros_invalidos'; END IF;
  END IF;
  IF p_user_id IS NOT NULL THEN
    PERFORM 1 FROM public.users WHERE id=p_user_id AND tenant_id=v_tenant AND ativo IS TRUE FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='atribuicao_destino_inativo'; END IF;
    IF NOT coalesce(private.client_assignment_elegivel(v_tenant,p_user_id,p_tipo),false) THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='atribuicao_destino_inelegivel';
    END IF;
    SELECT * INTO v_new FROM public.client_assignments WHERE tenant_id=v_tenant AND client_id=p_client_id
      AND user_id=p_user_id AND tipo=p_tipo FOR UPDATE;
    IF FOUND AND v_new.ativo IS TRUE THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='atribuicao_ja_ativa'; END IF;
  END IF;
  INSERT INTO public.client_assignment_operations (tenant_id,client_id,ator_id,idempotencia,pedido,acao,motivo)
    VALUES (v_tenant,p_client_id,v_ator,p_idempotencia,v_pedido,p_acao,btrim(p_motivo)) RETURNING * INTO v_op;
  IF p_assignment_id IS NOT NULL THEN
    DELETE FROM public.client_assignments WHERE id=v_old.id AND tenant_id=v_tenant AND client_id=p_client_id;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='atribuicao_estado_alterado'; END IF;
  END IF;
  IF p_user_id IS NOT NULL THEN
    IF v_new.id IS NOT NULL THEN
      UPDATE public.client_assignments SET ativo=true WHERE id=v_new.id AND tenant_id=v_tenant AND client_id=p_client_id;
    ELSE
      INSERT INTO public.client_assignments (client_id,user_id,tipo,ativo,tenant_id) VALUES (p_client_id,p_user_id,p_tipo,true,v_tenant);
    END IF;
  END IF;
  SELECT revisao INTO STRICT v_rev FROM public.client_assignment_state WHERE client_id=p_client_id AND tenant_id=v_tenant;
  SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.revisao),'[]'::jsonb) INTO v_eventos
    FROM public.client_assignment_events e WHERE tenant_id=v_tenant AND client_id=p_client_id AND operacao_id=v_op.id;
  v_resposta := jsonb_build_object('ok',true,'operacao_id',v_op.id,'revisao',v_rev,'eventos',v_eventos,'repetida',false);
  UPDATE public.client_assignment_operations SET resposta=v_resposta WHERE id=v_op.id AND tenant_id=v_tenant AND ator_id=v_ator;
  RETURN v_resposta;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.client_assignment_historico(p_client_id uuid, p_antes_revisao bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_ctx jsonb; v_itens jsonb; v_cursor bigint;
BEGIN
  v_ctx := private.client_assignment_autorizar(p_client_id,false);
  IF p_antes_revisao IS NOT NULL AND p_antes_revisao < 1 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='atribuicao_parametros_invalidos';
  END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.revisao DESC),'[]'::jsonb) INTO v_itens FROM (
    SELECT id,revisao,operacao_id,acao,origem,motivo,ator_id,ator_nome,ocorrido_em,antes,depois
      FROM public.client_assignment_events WHERE client_id=p_client_id AND tenant_id=(v_ctx->>'tenant_id')::uuid
        AND (p_antes_revisao IS NULL OR revisao < p_antes_revisao) ORDER BY revisao DESC LIMIT 31
  ) e;
  IF jsonb_array_length(v_itens)>30 THEN v_cursor := (v_itens->29->>'revisao')::bigint; v_itens := v_itens - 30; END IF;
  RETURN jsonb_build_object('eventos',v_itens,'proximo_cursor',v_cursor);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.client_assignment_pode_ler(p_client_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT auth.uid() IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.users u JOIN public.clients c ON c.tenant_id = u.tenant_id
     WHERE u.id = auth.uid() AND u.tenant_id = public.get_user_tenant_id()
       AND u.ativo IS TRUE AND u.perfil <> 'cliente' AND c.id = p_client_id
  ) AND (public.has_permissao('clientes','ver') OR public.has_permissao('clientes.atribuir','editar'))
    AND coalesce(public.user_can_access_client(p_client_id), false)
$function$
;

CREATE OR REPLACE FUNCTION public.cliente_canais_confere()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.tenant_id IS NULL THEN
    RAISE EXCEPTION 'Empresa não identificada.' USING ERRCODE = 'check_violation';
  END IF;
  IF auth.uid() IS NOT NULL AND NEW.tenant_id IS DISTINCT FROM public.get_user_tenant_id() THEN
    RAISE EXCEPTION 'Registro não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.tipo IS DISTINCT FROM OLD.tipo
       OR NEW.chave IS DISTINCT FROM OLD.chave OR NEW.client_id IS DISTINCT FROM OLD.client_id THEN
      RAISE EXCEPTION 'Canal e cliente não mudam: crie outro registro.' USING ERRCODE = 'check_violation';
    END IF;
    NEW.criado_em := OLD.criado_em;
  ELSE
    NEW.criado_em := now();
  END IF;
  IF NEW.client_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.clients cl WHERE cl.id = NEW.client_id AND cl.tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'Cliente não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;
  NEW.atualizado_em := now();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cliente_canais_resumo(p_tenant uuid, p_client uuid, p_instancias uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(canal_rotulo text, canal_tipo text, status text, ultima_msg timestamp with time zone, instancias integer, msgs_30d integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
#variable_conflict use_column
DECLARE
  v_30d TIMESTAMPTZ := now() - interval '30 days';
BEGIN
  IF p_tenant IS NULL OR p_client IS NULL
     OR NOT EXISTS (SELECT 1 FROM public.clients cl WHERE cl.id = p_client AND cl.tenant_id = p_tenant) THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH canais AS (
    SELECT k.tipo, k.chave, k.rotulo, k.status FROM private.cliente_canais_do_cliente(p_tenant, p_client) k
  ),
  sugeridos AS (
    SELECT DISTINCT c.tipo, c.chave
      FROM public.cliente_canais c
     WHERE c.tenant_id = p_tenant AND c.client_id = p_client AND c.status = 'sugerido'
       AND NOT EXISTS (SELECT 1 FROM canais k WHERE k.tipo = c.tipo AND k.chave = c.chave)
       AND NOT private.cliente_canal_excluido(p_tenant, c.tipo, c.chave)
     LIMIT 50
  ),
  todos AS (
    SELECT k.tipo, k.chave, k.rotulo, k.status FROM canais k
    UNION ALL
    SELECT s.tipo, s.chave, NULL::text, 'sugerido'::text FROM sugeridos s
  )
  SELECT t.rotulo, t.tipo, t.status, a.ult, COALESCE(a.ninst, 0), COALESCE(a.n30, 0)
    FROM todos t
    LEFT JOIN LATERAL (
      SELECT max(mm.ult) AS ult,
             count(DISTINCT ct.instance_id)::int AS ninst,
             COALESCE(sum(mm.n30), 0)::int AS n30
        FROM public.chat_contacts ct
        LEFT JOIN public.chat_conversations cv ON cv.contact_id = ct.id AND cv.tenant_id = p_tenant
        LEFT JOIN LATERAL (
          SELECT (SELECT m.criado_em FROM public.chat_messages m
                   WHERE m.tenant_id = p_tenant AND m.conversation_id = cv.id
                     AND COALESCE(m.tipo, '') <> 'nota_interna'
                   ORDER BY m.criado_em DESC LIMIT 1) AS ult,
                 (SELECT count(*) FROM public.chat_messages m
                   WHERE m.tenant_id = p_tenant AND m.conversation_id = cv.id
                     AND m.criado_em >= v_30d
                     AND COALESCE(m.tipo, '') <> 'nota_interna') AS n30
        ) mm ON cv.id IS NOT NULL
       WHERE ct.tenant_id = p_tenant
         AND ct.numero_whatsapp = ANY (private.canal_formas(t.tipo, t.chave))
         AND NOT ct.restrito_admin
         AND private.canal_tipo(ct.numero_whatsapp, ct.group_size) = t.tipo
         AND (p_instancias IS NULL OR ct.instance_id = ANY (p_instancias))
    ) a ON true
   -- Com instâncias limitadas: só canais com alguma cópia numa instância permitida.
   WHERE p_instancias IS NULL OR COALESCE(a.ninst, 0) > 0
   ORDER BY (t.status = 'sugerido'), t.tipo, length(t.rotulo), t.rotulo, a.ult DESC NULLS LAST;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cliente_canais_sincroniza()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'sugerido' THEN
      PERFORM private.vinculo_sincronizar(OLD.tenant_id, OLD.tipo, OLD.chave);
    END IF;
    RETURN NULL;
  END IF;
  -- Sugestão não mexe no Chat; mudança só de score/evidências também não.
  IF NEW.status = 'sugerido' AND (TG_OP = 'INSERT' OR OLD.status = 'sugerido') THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NULL;
  END IF;
  PERFORM private.vinculo_sincronizar(NEW.tenant_id, NEW.tipo, NEW.chave);
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cliente_relacionamento_confere()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.tenant_id IS NULL OR NEW.client_id IS NULL THEN
    RAISE EXCEPTION 'Empresa ou cliente não identificado.' USING ERRCODE = 'check_violation';
  END IF;
  -- Usuário logado nunca grava aqui (sem GRANT); mesmo assim, recusa outra empresa.
  IF auth.uid() IS NOT NULL AND NEW.tenant_id IS DISTINCT FROM public.get_user_tenant_id() THEN
    RAISE EXCEPTION 'Registro não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.client_id IS DISTINCT FROM OLD.client_id THEN
      RAISE EXCEPTION 'Empresa e cliente não mudam.' USING ERRCODE = 'check_violation';
    END IF;
    IF TG_TABLE_NAME = 'cliente_relacionamento' THEN
      NEW.criado_em := OLD.criado_em;
    END IF;
  ELSE
    IF NOT EXISTS (
      SELECT 1 FROM public.clients cl WHERE cl.id = NEW.client_id AND cl.tenant_id = NEW.tenant_id
    ) THEN
      RAISE EXCEPTION 'Cliente não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
    END IF;
    NEW.criado_em := now();
  END IF;
  IF TG_TABLE_NAME = 'cliente_relacionamento' THEN
    NEW.atualizado_em := now();
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cliente_relacionamento_ia_confirmar(p_id uuid, p_custo numeric)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t private.cliente_relacionamento_ia_tentativas%ROWTYPE;
BEGIN
  IF auth.uid() IS NOT NULL OR p_custo IS NULL OR p_custo<0 OR p_custo>1000 THEN RETURN false; END IF;
  SELECT * INTO t FROM private.cliente_relacionamento_ia_tentativas WHERE id=p_id;
  IF NOT FOUND THEN RETURN false; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('relacionamento-uso:'||t.tenant_id::text||':'||t.dia::text,0));
  SELECT * INTO t FROM private.cliente_relacionamento_ia_tentativas WHERE id=p_id FOR UPDATE;
  IF t.confirmado_em IS NOT NULL THEN RETURN t.custo_confirmado=round(p_custo,6); END IF;
  UPDATE public.cliente_relacionamento_uso SET custo_usd=greatest(0,custo_usd-t.reserva+round(p_custo,6))
    WHERE tenant_id=t.tenant_id AND dia=t.dia;
  IF NOT FOUND THEN RETURN false; END IF;
  UPDATE private.cliente_relacionamento_ia_tentativas SET custo_confirmado=round(p_custo,6),confirmado_em=clock_timestamp() WHERE id=p_id;
  RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cliente_relacionamento_ia_reservar(p_id uuid, p_tenant uuid, p_cliente uuid, p_dia date, p_limite integer, p_teto numeric, p_reserva numeric)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.cliente_relacionamento%ROWTYPE; t private.cliente_relacionamento_ia_tentativas%ROWTYPE; uso jsonb;
BEGIN
  IF auth.uid() IS NOT NULL OR p_id IS NULL OR p_tenant IS NULL OR p_cliente IS NULL
    OR p_dia IS DISTINCT FROM (clock_timestamp() AT TIME ZONE 'America/Sao_Paulo')::date
    OR p_limite IS NULL OR p_limite NOT BETWEEN 1 AND 2000 OR p_teto IS NULL OR p_teto<=0 OR p_teto>500
    OR p_reserva IS NULL OR p_reserva<0 OR p_reserva>p_teto THEN RETURN false; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('relacionamento-uso:'||p_tenant::text||':'||p_dia::text,0));
  SELECT * INTO t FROM private.cliente_relacionamento_ia_tentativas WHERE id=p_id;
  IF FOUND THEN RETURN t.tenant_id=p_tenant AND t.client_id=p_cliente AND t.dia=p_dia AND t.reserva=round(p_reserva,6); END IF;
  SELECT * INTO r FROM public.cliente_relacionamento WHERE tenant_id=p_tenant AND client_id=p_cliente FOR UPDATE;
  IF NOT FOUND AND NOT EXISTS(SELECT 1 FROM public.clients WHERE id=p_cliente AND tenant_id=p_tenant) THEN RETURN false; END IF;
  -- Transição sem perder nem dobrar a última chamada do worker antigo: copiar
  -- uma vez o custo legado ANTES que uma análise nova sobrescreva aquela linha.
  IF (r.analisado_em AT TIME ZONE 'America/Sao_Paulo')::date=p_dia
    AND (r.ia_uso_contabilizado_ate IS NULL OR r.ia_uso_contabilizado_ate<r.analisado_em) THEN
    PERFORM public.cliente_relacionamento_uso_registrar(p_tenant,p_dia,1,COALESCE(r.custo_usd,0));
    UPDATE public.cliente_relacionamento SET ia_uso_contabilizado_ate=r.analisado_em WHERE tenant_id=p_tenant AND client_id=p_cliente;
  END IF;
  uso:=public.cliente_relacionamento_uso_total(p_tenant,p_dia);
  IF (uso->>'chamadas')::integer>=p_limite OR (uso->>'custo')::numeric+p_reserva>p_teto THEN RETURN false; END IF;
  INSERT INTO private.cliente_relacionamento_ia_tentativas(id,tenant_id,client_id,dia,reserva)
    VALUES(p_id,p_tenant,p_cliente,p_dia,round(p_reserva,6));
  PERFORM public.cliente_relacionamento_uso_registrar(p_tenant,p_dia,1,round(p_reserva,6));
  RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cliente_relacionamento_previa_reservar(p_tenant uuid, p_dia date, p_intervalo_s integer DEFAULT 60, p_max_dia integer DEFAULT 20)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ok boolean;
BEGIN
  IF p_tenant IS NULL OR p_dia IS NULL THEN
    RETURN false;
  END IF;
  INSERT INTO public.cliente_relacionamento_uso AS u (tenant_id, dia, previas, ultima_previa_em)
  VALUES (p_tenant, p_dia, 1, now())
  ON CONFLICT (tenant_id, dia) DO UPDATE
     SET previas = u.previas + 1, ultima_previa_em = now()
   WHERE (u.ultima_previa_em IS NULL
          OR u.ultima_previa_em < now() - make_interval(secs => greatest(coalesce(p_intervalo_s, 60), 0)))
     AND u.previas < greatest(coalesce(p_max_dia, 20), 1)
  RETURNING true INTO v_ok;
  RETURN coalesce(v_ok, false);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cliente_relacionamento_reivindicar(p_tenant uuid, p_client_ids uuid[], p_dia date, p_limite integer DEFAULT 20)
 RETURNS SETOF cliente_relacionamento
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_tenant IS NULL OR p_dia IS NULL THEN
    RAISE EXCEPTION 'Parâmetros obrigatórios.' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF coalesce(cardinality(p_client_ids), 0) = 0 THEN
    RETURN;
  END IF;
  IF cardinality(p_client_ids) > 5000 THEN
    RAISE EXCEPTION 'Clientes demais.' USING ERRCODE = 'invalid_parameter_value';
  END IF;

  INSERT INTO public.cliente_relacionamento (tenant_id, client_id)
  SELECT p_tenant, cl.id
    FROM public.clients cl
   WHERE cl.tenant_id = p_tenant
     AND cl.id = ANY (p_client_ids)
  ON CONFLICT (tenant_id, client_id) DO NOTHING;

  RETURN QUERY
  UPDATE public.cliente_relacionamento r
     SET reivindicado_em = now()
   WHERE (r.tenant_id, r.client_id) IN (
     SELECT x.tenant_id, x.client_id
       FROM public.cliente_relacionamento x
      WHERE x.tenant_id = p_tenant
        AND x.client_id = ANY (p_client_ids)
        AND x.dia_processado IS DISTINCT FROM p_dia
        AND (x.reivindicado_em IS NULL OR x.reivindicado_em < now() - interval '10 minutes')
      ORDER BY x.analisado_em NULLS FIRST, x.client_id
      LIMIT greatest(1, least(coalesce(p_limite, 20), 200))
      FOR UPDATE SKIP LOCKED
   )
  RETURNING r.*;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cliente_relacionamento_reivindicar_ia(p_tenant uuid, p_client_ids uuid[], p_dia date, p_limite integer DEFAULT 20)
 RETURNS SETOF cliente_relacionamento
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF p_tenant IS NULL OR p_dia IS NULL OR COALESCE(cardinality(p_client_ids),0)>5000 THEN
    RAISE EXCEPTION 'Parâmetros inválidos.' USING ERRCODE='22023';
  END IF;
  IF COALESCE(cardinality(p_client_ids),0)=0 THEN RETURN; END IF;
  INSERT INTO public.cliente_relacionamento(tenant_id,client_id)
    SELECT p_tenant,id FROM public.clients WHERE tenant_id=p_tenant AND id=ANY(p_client_ids)
    ON CONFLICT(tenant_id,client_id) DO NOTHING;
  RETURN QUERY UPDATE public.cliente_relacionamento r SET reivindicado_em=clock_timestamp()
    WHERE (r.tenant_id,r.client_id) IN (
      SELECT x.tenant_id,x.client_id FROM public.cliente_relacionamento x
      WHERE x.tenant_id=p_tenant AND x.client_id=ANY(p_client_ids)
        AND (x.reivindicado_em IS NULL OR x.reivindicado_em<clock_timestamp()-interval '10 minutes')
        AND (x.processado_em IS NULL OR x.processado_em<clock_timestamp()-interval '2 minutes')
        AND (x.dia_processado IS DISTINCT FROM p_dia OR (
          NOT EXISTS(SELECT 1 FROM public.app_modules a WHERE a.tenant_id=p_tenant AND a.slug='atendimento' AND a.enabled IS FALSE)
          AND EXISTS(SELECT 1 FROM private.atendimento_wa_entradas e JOIN public.cliente_canais c
            ON c.tenant_id=e.tenant_id AND c.tipo=e.canal_tipo AND c.chave=e.canal_chave
            AND c.client_id=x.client_id AND c.status='confirmado'
            WHERE e.tenant_id=p_tenant AND e.atestada_em IS NOT NULL
              AND e.criado_em>COALESCE(x.analisado_ate,'-infinity'::timestamptz)
              AND NOT private.cliente_canal_excluido(p_tenant,e.canal_tipo,e.canal_chave))))
      ORDER BY x.analisado_em NULLS FIRST,x.client_id
      LIMIT greatest(1,least(COALESCE(p_limite,20),200)) FOR UPDATE SKIP LOCKED
    ) RETURNING r.*;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cliente_relacionamento_uso_registrar(p_tenant uuid, p_dia date, p_chamadas integer, p_custo numeric)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  INSERT INTO public.cliente_relacionamento_uso AS u (tenant_id, dia, chamadas_ia, custo_usd)
  VALUES (p_tenant, p_dia, greatest(coalesce(p_chamadas, 0), 0), least(greatest(coalesce(p_custo, 0), 0), 1000))
  ON CONFLICT (tenant_id, dia) DO UPDATE
     SET chamadas_ia = u.chamadas_ia + greatest(coalesce(p_chamadas, 0), 0),
         custo_usd = u.custo_usd + least(greatest(coalesce(p_custo, 0), 0), 1000)
$function$
;

CREATE OR REPLACE FUNCTION public.cliente_relacionamento_uso_total(p_tenant uuid, p_dia date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  SELECT jsonb_build_object('chamadas',
    COALESCE((SELECT chamadas_ia FROM public.cliente_relacionamento_uso WHERE tenant_id=p_tenant AND dia=p_dia),0)+count(*),
    'custo',COALESCE((SELECT custo_usd FROM public.cliente_relacionamento_uso WHERE tenant_id=p_tenant AND dia=p_dia),0)+COALESCE(sum(r.custo_usd),0))
  FROM public.cliente_relacionamento r WHERE r.tenant_id=p_tenant
    AND (r.analisado_em AT TIME ZONE 'America/Sao_Paulo')::date=p_dia
    AND (r.ia_uso_contabilizado_ate IS NULL OR r.ia_uso_contabilizado_ate<r.analisado_em);
$function$
;

CREATE OR REPLACE FUNCTION public.cliente_timeline(p_tenant uuid, p_client uuid, p_desde timestamp with time zone, p_ate timestamp with time zone DEFAULT now(), p_limite integer DEFAULT 400, p_instancias uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(message_id uuid, criado_em timestamp with time zone, canal_rotulo text, canal_tipo text, autor_tipo text, autor_nome text, tipo text, conteudo text, midia_texto text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
#variable_conflict use_column
DECLARE
  v_ate   TIMESTAMPTZ := COALESCE(p_ate, now());
  v_desde TIMESTAMPTZ := COALESCE(p_desde, COALESCE(p_ate, now()) - interval '90 days');
  v_lim   INTEGER := LEAST(GREATEST(COALESCE(p_limite, 400), 1), 2000);
BEGIN
  IF p_tenant IS NULL OR p_client IS NULL OR v_desde > v_ate
     OR NOT EXISTS (SELECT 1 FROM public.clients cl WHERE cl.id = p_client AND cl.tenant_id = p_tenant) THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH canais AS MATERIALIZED (
    -- formas já calculadas: a busca dos contatos usa o índice (tenant_id, numero_whatsapp).
    SELECT k.tipo, k.rotulo, private.canal_formas(k.tipo, k.chave) AS formas
      FROM private.cliente_canais_do_cliente(p_tenant, p_client) k
  ),
  contatos AS (
    SELECT ct.id AS contact_id, k.tipo, k.rotulo
      FROM canais k
      JOIN public.chat_contacts ct
        ON ct.tenant_id = p_tenant
       AND ct.numero_whatsapp = ANY (k.formas)
     WHERE NOT ct.restrito_admin
       AND private.canal_tipo(ct.numero_whatsapp, ct.group_size) = k.tipo
       AND (p_instancias IS NULL OR ct.instance_id = ANY (p_instancias))
  ),
  convs AS (
    SELECT cv.id AS conversation_id, c.tipo, c.rotulo
      FROM contatos c
      JOIN public.chat_conversations cv ON cv.contact_id = c.contact_id AND cv.tenant_id = p_tenant
  ),
  ultimas AS (
    SELECT x.*, cv.tipo AS c_tipo, cv.rotulo AS c_rotulo
      FROM convs cv
      CROSS JOIN LATERAL (
        SELECT m.id, m.criado_em, m.autor_tipo, m.autor_nome, m.enviado_por_agente, m.enviado_por_ia,
               m.tipo AS m_tipo, m.conteudo
          FROM public.chat_messages m
         WHERE m.tenant_id = p_tenant
           AND m.conversation_id = cv.conversation_id
           AND m.criado_em >= v_desde
           AND m.criado_em <= v_ate
           AND COALESCE(m.tipo, '') <> 'nota_interna'
         ORDER BY m.criado_em DESC, m.id DESC
         LIMIT v_lim
      ) x
     ORDER BY x.criado_em DESC, x.id DESC
     LIMIT v_lim
  ),
  prefixo AS (
    SELECT u.*,
           CASE WHEN u.c_tipo = 'grupo'
                THEN substring(u.conteudo FROM '^\[([^]\n]{1,80})\] ') END AS p_nome
      FROM ultimas u
  )
  SELECT p.id,
         p.criado_em,
         p.c_rotulo,
         p.c_tipo,
         COALESCE(p.autor_tipo,
                  CASE WHEN p.enviado_por_ia IS TRUE THEN 'ia'
                       WHEN p.enviado_por_agente IS TRUE THEN 'equipe' END),
         left(COALESCE(NULLIF(btrim(p.autor_nome), ''), NULLIF(btrim(p.p_nome), '')), 80),
         p.m_tipo,
         left(CASE WHEN p.p_nome IS NOT NULL
                   THEN substr(p.conteudo, length(p.p_nome) + 4)
                   ELSE p.conteudo END, 2000),
         (SELECT left(mt.texto, 4000)
            FROM public.chat_midia_texto mt
           WHERE mt.message_id = p.id AND mt.tenant_id = p_tenant AND mt.status = 'ok')
    FROM prefixo p
   ORDER BY p.criado_em ASC, p.id ASC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.comissoes_papel_do_perfil(p_perfil text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
        SELECT CASE lower(coalesce(p_perfil, ''))
          WHEN 'admin'        THEN 'admin'
          WHEN 'gerente'      THEN 'revisor'
          WHEN 'estrategista' THEN 'estrategista'
          ELSE NULL
        END;
      $function$
;

CREATE OR REPLACE FUNCTION public.comissoes_sync_papel()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_papel text := public.comissoes_papel_do_perfil(new.perfil);
begin
  if v_papel is null then
    return new;
  end if;

  insert into public.comissoes_papeis (user_id, papel, tenant_id)
  values (new.id, v_papel, new.tenant_id)
  on conflict (user_id) do nothing;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.compute_meeting_duration()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.ended_at IS NOT NULL AND NEW.started_at IS NOT NULL THEN
    NEW.duration_seconds := EXTRACT(EPOCH FROM (NEW.ended_at - NEW.started_at))::INTEGER;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.concluir_contratos_vencidos()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c record; v_total integer:=0; v_skip text; v_hoje date:=(now() AT TIME ZONE 'America/Sao_Paulo')::date;
BEGIN
  -- EXECUTE é exclusivo de owner/service. Não recebe data/tenant/identidade forjável.
  IF NOT pg_try_advisory_xact_lock(hashtextextended('contratos-vigencia-diaria',0)) THEN
    RETURN jsonb_build_object('concluidos',0,'em_execucao',true);
  END IF;
  v_skip:=coalesce(current_setting('app.skip_venda_resync',true),'');
  PERFORM set_config('app.skip_venda_resync','on',true);
  FOR c IN SELECT id,tenant_id FROM public.contratos
    WHERE status='ativo' AND upper(coalesce(status_secundario,''))<>'PAUSADO'
      AND vigencia_fim IS NOT NULL AND vigencia_fim<v_hoje
    ORDER BY tenant_id,id FOR UPDATE SKIP LOCKED
  LOOP
    UPDATE public.contratos SET status='concluido',status_secundario='CONCLUÍDO'
      WHERE id=c.id AND tenant_id=c.tenant_id AND status='ativo' AND vigencia_fim<v_hoje;
    IF FOUND THEN v_total:=v_total+1; END IF;
  END LOOP;
  PERFORM set_config('app.skip_venda_resync',v_skip,true);
  RETURN jsonb_build_object('concluidos',v_total,'dia',v_hoje);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.criar_contrato_de_venda_pendente()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status IS DISTINCT FROM 'descartada' THEN
    INSERT INTO public.contratos (
      cliente_nome, cpf_cnpj, email, whatsapp, empresa, instagram, endereco,
      produto_id, produto_nome, valor_total, data_fechamento,
      status, status_secundario, pagamentos, vendedor, venda_pendente_id,
      pagador_diferente, pagador_nome, pagador_cpf_cnpj, pagador_relacao, pagador_observacao,
      tenant_id
    )
    VALUES (
      NEW.cliente_nome,
      NULLIF(NEW.cliente_cpf_cnpj, ''),
      NULLIF(NEW.cliente_email, ''),
      NULLIF(NEW.cliente_whatsapp, ''),
      NULLIF(NEW.cliente_razao_social, ''),
      NULLIF(NEW.cliente_instagram, ''),
      NULLIF(NEW.cliente_endereco, ''),
      NEW.produto_id,
      NEW.produto_nome,
      COALESCE(NEW.valor_total_venda, 0),
      COALESCE(NEW.criado_em::date, CURRENT_DATE),
      'rascunho',
      'Não iniciado',
      COALESCE(NEW.pagamentos, '[]'::jsonb),
      NULLIF(NEW.closer_nome, ''),
      NEW.id,
      COALESCE(NEW.pagador_diferente, false),
      NULLIF(NEW.pagador_nome, ''),
      NULLIF(NEW.pagador_cpf_cnpj, ''),
      NULLIF(NEW.pagador_relacao, ''),
      NULLIF(NEW.pagador_observacao, ''),
      NEW.tenant_id
    )
    ON CONFLICT (venda_pendente_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.crm_omnx_aplicar_venda(p_tenant_id uuid, p_event_id text, p_crm_venda_id text, p_dados jsonb, p_criar boolean DEFAULT true, p_contrato jsonb DEFAULT NULL::jsonb, p_desk_venda_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_resp       jsonb;
  v_venda      public.vendas_pendentes%ROWTYPE;
  v_id         uuid;
  v_status     text;
  v_antes      jsonb;
  v_depois     jsonb;
  v_contrato   uuid;
  v_link       text;
  v_assinado   date;
  v_contrato_n int := 0;
  v_crm_id     text;
  v_pagador    boolean := p_dados ? 'pagador_diferente';
BEGIN
  IF p_tenant_id IS NULL OR p_event_id IS NULL OR p_crm_venda_id IS NULL THEN
    RAISE EXCEPTION 'tenant, event_id e crm_venda_id são obrigatórios';
  END IF;
  IF p_dados IS NULL OR jsonb_typeof(p_dados) <> 'object' THEN
    RAISE EXCEPTION 'dados inválidos';
  END IF;

  -- Serializa o mesmo evento e a mesma venda (duas entregas simultâneas).
  PERFORM pg_advisory_xact_lock(hashtextextended('crm_evento:' || p_tenant_id::text || ':' || p_event_id, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('crm_venda:' || p_tenant_id::text || ':' || p_crm_venda_id, 0));

  SELECT resposta INTO v_resp
    FROM public.crm_eventos_recebidos
   WHERE tenant_id = p_tenant_id AND event_id = p_event_id;
  IF FOUND THEN
    RETURN v_resp || jsonb_build_object('duplicado', true);
  END IF;

  -- Escrita vinda do CRM não volta ao CRM (gatilhos crm_omnx olham este disjuntor).
  PERFORM set_config('app.skip_crm_notify', 'on', true);

  -- 1º pelo id do Desk que o CRM já conhece; 2º pelo id da venda no CRM.
  IF p_desk_venda_id IS NOT NULL THEN
    SELECT * INTO v_venda
      FROM public.vendas_pendentes
     WHERE id = p_desk_venda_id AND tenant_id = p_tenant_id
     FOR UPDATE;
  END IF;
  IF v_venda.id IS NULL THEN
    SELECT * INTO v_venda
      FROM public.vendas_pendentes
     WHERE tenant_id = p_tenant_id AND crm_venda_id = p_crm_venda_id
     FOR UPDATE;
  END IF;

  IF v_venda.id IS NOT NULL THEN
    -- Grava o crm_venda_id na linha achada, a não ser que outra venda deste tenant
    -- já esteja ligada a ele (duplicata antiga: não quebra, mantém como está).
    IF v_venda.crm_venda_id IS DISTINCT FROM p_crm_venda_id AND NOT EXISTS (
      SELECT 1 FROM public.vendas_pendentes
       WHERE tenant_id = p_tenant_id AND crm_venda_id = p_crm_venda_id AND id <> v_venda.id
    ) THEN
      v_crm_id := p_crm_venda_id;
    ELSE
      v_crm_id := v_venda.crm_venda_id;
    END IF;
  END IF;

  IF v_venda.id IS NULL THEN
    IF NOT COALESCE(p_criar, true) THEN
      v_status := 'unchanged';
    ELSE
      INSERT INTO public.vendas_pendentes (
        tenant_id, origem, crm_venda_id, crm_sincronizado_em, status,
        closer_nome, closer_email,
        cliente_nome, cliente_razao_social, cliente_cpf_cnpj, cliente_email, cliente_whatsapp,
        cliente_instagram, cliente_cep, cliente_logradouro, cliente_numero, cliente_complemento,
        cliente_bairro, cliente_municipio, cliente_uf,
        produto_nome, valor_total_venda, pagamentos, observacoes,
        pagador_diferente, pagador_nome, pagador_cpf_cnpj, pagador_relacao
      ) VALUES (
        p_tenant_id, 'crm', p_crm_venda_id, now(), 'pendente',
        COALESCE(NULLIF(p_dados->>'closer_nome', ''), 'CRM'),
        COALESCE(NULLIF(lower(p_dados->>'closer_email'), ''), 'crm@omnx.pro'),
        p_dados->>'cliente_nome',
        p_dados->>'cliente_razao_social',
        p_dados->>'cliente_cpf_cnpj',
        p_dados->>'cliente_email',
        COALESCE(p_dados->>'cliente_whatsapp', ''),
        p_dados->>'cliente_instagram',
        p_dados->>'cliente_cep',
        p_dados->>'cliente_logradouro',
        p_dados->>'cliente_numero',
        p_dados->>'cliente_complemento',
        p_dados->>'cliente_bairro',
        p_dados->>'cliente_municipio',
        p_dados->>'cliente_uf',
        p_dados->>'produto_nome',
        (p_dados->>'valor_total_venda')::numeric,
        COALESCE(NULLIF(p_dados->'pagamentos', 'null'::jsonb), '[]'::jsonb),
        p_dados->>'observacoes',
        COALESCE((p_dados->>'pagador_diferente')::boolean, false),
        p_dados->>'pagador_nome',
        p_dados->>'pagador_cpf_cnpj',
        p_dados->>'pagador_relacao'
      )
      RETURNING id INTO v_id;
      v_status := 'created';
    END IF;
  ELSE
    v_id := v_venda.id;
    v_antes := to_jsonb(v_venda) - ARRAY['atualizado_em', 'crm_sincronizado_em', 'crm_sincronizacao_erro'];

    UPDATE public.vendas_pendentes vp SET
      closer_nome          = COALESCE(NULLIF(p_dados->>'closer_nome', ''), vp.closer_nome),
      closer_email         = COALESCE(NULLIF(lower(p_dados->>'closer_email'), ''), vp.closer_email),
      cliente_nome         = COALESCE(NULLIF(p_dados->>'cliente_nome', ''), vp.cliente_nome),
      cliente_razao_social = COALESCE(p_dados->>'cliente_razao_social', vp.cliente_razao_social),
      cliente_cpf_cnpj     = COALESCE(p_dados->>'cliente_cpf_cnpj', vp.cliente_cpf_cnpj),
      cliente_email        = COALESCE(p_dados->>'cliente_email', vp.cliente_email),
      cliente_whatsapp     = COALESCE(NULLIF(p_dados->>'cliente_whatsapp', ''), vp.cliente_whatsapp),
      cliente_instagram    = COALESCE(p_dados->>'cliente_instagram', vp.cliente_instagram),
      cliente_cep          = COALESCE(p_dados->>'cliente_cep', vp.cliente_cep),
      cliente_logradouro   = COALESCE(p_dados->>'cliente_logradouro', vp.cliente_logradouro),
      cliente_numero       = COALESCE(p_dados->>'cliente_numero', vp.cliente_numero),
      cliente_complemento  = COALESCE(p_dados->>'cliente_complemento', vp.cliente_complemento),
      cliente_bairro       = COALESCE(p_dados->>'cliente_bairro', vp.cliente_bairro),
      cliente_municipio    = COALESCE(p_dados->>'cliente_municipio', vp.cliente_municipio),
      cliente_uf           = COALESCE(p_dados->>'cliente_uf', vp.cliente_uf),
      produto_nome         = COALESCE(p_dados->>'produto_nome', vp.produto_nome),
      valor_total_venda    = COALESCE((p_dados->>'valor_total_venda')::numeric, vp.valor_total_venda),
      pagamentos           = COALESCE(NULLIF(p_dados->'pagamentos', 'null'::jsonb), vp.pagamentos),
      observacoes          = COALESCE(p_dados->>'observacoes', vp.observacoes),
      -- Pagador: só quando o CRM mandou; aí os campos mudam juntos.
      pagador_diferente    = CASE WHEN v_pagador THEN COALESCE((p_dados->>'pagador_diferente')::boolean, false) ELSE vp.pagador_diferente END,
      pagador_nome         = CASE WHEN v_pagador THEN p_dados->>'pagador_nome' ELSE vp.pagador_nome END,
      pagador_cpf_cnpj     = CASE WHEN v_pagador THEN p_dados->>'pagador_cpf_cnpj' ELSE vp.pagador_cpf_cnpj END,
      pagador_relacao      = CASE WHEN v_pagador THEN p_dados->>'pagador_relacao' ELSE vp.pagador_relacao END,
      pagador_observacao   = CASE WHEN v_pagador AND NOT COALESCE((p_dados->>'pagador_diferente')::boolean, false)
                                  THEN NULL ELSE vp.pagador_observacao END,
      crm_venda_id         = v_crm_id,
      crm_sincronizado_em  = now(),
      crm_sincronizacao_erro = NULL
    WHERE vp.id = v_id
    RETURNING to_jsonb(vp) - ARRAY['atualizado_em', 'crm_sincronizado_em', 'crm_sincronizacao_erro']
      INTO v_depois;

    v_status := CASE WHEN v_antes IS NOT DISTINCT FROM v_depois THEN 'unchanged' ELSE 'updated' END;
  END IF;

  IF v_id IS NOT NULL THEN
    SELECT id INTO v_contrato FROM public.contratos WHERE venda_pendente_id = v_id LIMIT 1;

    -- Contrato assinado no CRM: completa link e data só onde estão vazios.
    v_link := NULLIF(btrim(COALESCE(p_contrato->>'link', '')), '');
    IF v_contrato IS NOT NULL AND p_contrato->>'status' = 'signed' AND v_link IS NOT NULL THEN
      -- Data impossível (ex.: 2026-02-30) não derruba a gravação: fica sem data.
      BEGIN
        v_assinado := CASE WHEN (p_contrato->>'assinado_em') ~ '^\d{4}-\d{2}-\d{2}'
                           THEN left(p_contrato->>'assinado_em', 10)::date END;
      EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
        v_assinado := NULL;
      END;
      UPDATE public.contratos c SET
        link_clicksign  = COALESCE(NULLIF(btrim(COALESCE(c.link_clicksign, '')), ''), v_link),
        data_assinatura = COALESCE(c.data_assinatura, v_assinado)
      WHERE c.id = v_contrato
        AND (NULLIF(btrim(COALESCE(c.link_clicksign, '')), '') IS NULL
             OR (c.data_assinatura IS NULL AND v_assinado IS NOT NULL));
      GET DIAGNOSTICS v_contrato_n = ROW_COUNT;
      IF v_contrato_n > 0 AND v_status = 'unchanged' THEN
        v_status := 'updated';
      END IF;
    END IF;
  END IF;

  v_resp := jsonb_build_object(
    'ok', true,
    'status', v_status,
    'desk_venda_id', v_id,
    'desk_contrato_id', v_contrato
  );

  INSERT INTO public.crm_eventos_recebidos (tenant_id, event_id, crm_venda_id, desk_venda_id, resposta)
  VALUES (p_tenant_id, p_event_id, p_crm_venda_id, v_id, v_resp)
  ON CONFLICT (tenant_id, event_id) DO NOTHING;

  RETURN v_resp || jsonb_build_object('duplicado', false);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.crm_omnx_ativo(p_tenant_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT p_tenant_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.tenant_integracoes
     WHERE tenant_id = p_tenant_id
       AND provider = 'crm_omnx'
       AND is_active
       AND secret_key_id IS NOT NULL
       AND base_url IS NOT NULL
  );
$function$
;

CREATE OR REPLACE FUNCTION public.crm_omnx_chamar_notificar(p_body jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault', 'net', 'pg_temp'
AS $function$
DECLARE
  v_secret text;
  v_url    text;
  v_anon   text;
BEGIN
  SELECT decrypted_secret INTO v_secret
    FROM vault.decrypted_secrets
   WHERE name = 'notify_webhook_secret';
  IF v_secret IS NULL THEN
    RETURN;  -- sem segredo não há como chamar: nunca quebra a escrita
  END IF;

  IF to_regprocedure('public.app_url_funcoes(text)') IS NOT NULL THEN
    v_url := public.app_url_funcoes('crm-omnx-notificar');
  ELSE
    v_url := 'https://wuzmckatbmlpkdxtfhqr.supabase.co/functions/v1/crm-omnx-notificar';
  END IF;
  IF to_regprocedure('public.app_chave_anon()') IS NOT NULL THEN
    v_anon := public.app_chave_anon();
  ELSE
    v_anon := 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Ind1em1ja2F0Ym1scGtkeHRmaHFyIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzMxNjUxNzEsImV4cCI6MjA4ODc0MTE3MX0.dL8LHbCJv69zJtt-aA3iAEO6PMcJBHlDC1HAEu9O9Ho';
  END IF;

  PERFORM net.http_post(
    url := v_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_anon,
      'x-notify-secret', v_secret
    ),
    body := p_body,
    timeout_milliseconds := 60000
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.definir_clientes_contrato(p_contrato_id uuid, p_actor_esperado uuid, p_cliente_ids uuid[], p_cliente_ids_esperados uuid[], p_cliente_principal_esperado uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c public.contratos%ROWTYPE; v_tenant uuid:=public.get_user_tenant_id();
  v_atuais uuid[]; v_novos uuid[]; v_esperados uuid[]; v_client uuid;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_actor_esperado OR v_tenant IS NULL
    OR NOT coalesce(public.pode_gerir_contratos(),false) THEN
    RAISE EXCEPTION 'Acesso negado.' USING ERRCODE='42501';
  END IF;
  SELECT * INTO c FROM public.contratos WHERE id=p_contrato_id AND tenant_id=v_tenant FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Contrato indisponível.' USING ERRCODE='P0002'; END IF;
  IF p_cliente_ids IS NULL OR p_cliente_ids_esperados IS NULL
    OR array_position(p_cliente_ids,NULL) IS NOT NULL OR array_position(p_cliente_ids_esperados,NULL) IS NOT NULL
    OR char_length(btrim(coalesce(p_motivo,''))) NOT BETWEEN 8 AND 2000 THEN
    RAISE EXCEPTION 'Informe os clientes e um motivo entre 8 e 2000 caracteres.' USING ERRCODE='22023';
  END IF;
  SELECT coalesce(array_agg(DISTINCT id ORDER BY id),'{}'::uuid[]) INTO v_novos FROM unnest(p_cliente_ids) x(id);
  SELECT coalesce(array_agg(DISTINCT id ORDER BY id),'{}'::uuid[]) INTO v_esperados FROM unnest(p_cliente_ids_esperados) x(id);
  SELECT coalesce(array_agg(id ORDER BY id),'{}'::uuid[]) INTO v_atuais FROM (
    SELECT c.cliente_id AS id WHERE c.cliente_id IS NOT NULL
    UNION SELECT cc.cliente_id FROM public.contrato_clientes cc WHERE cc.contrato_id=c.id AND cc.tenant_id=v_tenant
  ) x;
  IF c.cliente_id IS DISTINCT FROM p_cliente_principal_esperado OR v_atuais IS DISTINCT FROM v_esperados THEN
    RAISE EXCEPTION 'O contrato mudou. Atualize a ficha antes de confirmar.' USING ERRCODE='40001';
  END IF;
  IF cardinality(v_novos)<>cardinality(p_cliente_ids) OR cardinality(v_esperados)<>cardinality(p_cliente_ids_esperados)
    OR (c.cliente_id IS NOT NULL AND NOT c.cliente_id=ANY(v_novos)) THEN
    RAISE EXCEPTION 'Preserve o cliente principal e não repita clientes.' USING ERRCODE='22023';
  END IF;
  -- Valida também removidos; vínculo não cria permissão para editar um cliente inacessível.
  FOR v_client IN SELECT id FROM unnest(v_atuais||v_novos) x(id) GROUP BY id ORDER BY id LOOP
    PERFORM 1 FROM public.clients cl WHERE cl.id=v_client AND cl.tenant_id=v_tenant
      AND coalesce(public.user_can_access_client(cl.id),false) FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Cliente indisponível para esta operação.' USING ERRCODE='42501'; END IF;
  END LOOP;
  IF v_atuais=v_novos THEN
    RETURN jsonb_build_object('id',c.id,'cliente_id',c.cliente_id,'cliente_ids',v_atuais);
  END IF;
  DELETE FROM public.contrato_clientes cc WHERE cc.contrato_id=c.id AND cc.tenant_id=v_tenant
    AND (NOT cc.cliente_id=ANY(v_novos) OR cc.cliente_id IS NOT DISTINCT FROM c.cliente_id);
  INSERT INTO public.contrato_clientes(contrato_id,cliente_id,tenant_id)
    SELECT c.id,id,v_tenant FROM unnest(v_novos) x(id) WHERE id IS DISTINCT FROM c.cliente_id
    ON CONFLICT (contrato_id,cliente_id) DO NOTHING;
  INSERT INTO public.contratos_audit_log(contrato_id,operacao,campo,valor_antigo,valor_novo,alterado_por,tenant_id)
    VALUES(c.id,'UPDATE','clientes_atendidos',jsonb_build_object('cliente_ids',v_atuais)::text,
      jsonb_build_object('cliente_ids',v_novos,'motivo',btrim(p_motivo))::text,auth.uid(),v_tenant);
  RETURN jsonb_build_object('id',c.id,'cliente_id',c.cliente_id,'cliente_ids',v_novos);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.desk_conferir_conta_nova()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app      jsonb;
  v_user     jsonb;
  v_email      text;
  v_perfil     text;
  v_tenant     uuid;
  v_tenant_txt text;
  v_nome       text;
  v_linha    uuid;
  v_marca    jsonb;
  v_renomeou jsonb;
BEGIN
  -- Estado no fim da transação (o NEW é o da hora do INSERT, sem o app_metadata).
  SELECT u.raw_app_meta_data, u.raw_user_meta_data, u.email
    INTO v_app, v_user, v_email
    FROM auth.users u
   WHERE u.id = NEW.id;
  IF NOT FOUND THEN
    RETURN NULL;  -- conta apagada na mesma transação
  END IF;

  v_perfil := NULLIF(btrim(COALESCE(v_app->>'perfil', '')), '');
  v_tenant_txt := NULLIF(btrim(COALESCE(v_app->>'tenant_id', '')), '');
  v_nome   := COALESCE(NULLIF(btrim(COALESCE(v_user->>'nome', '')), ''), v_email);

  -- Só um dos dois no app_metadata: nenhum chamador do servidor manda pela metade, então é
  -- provisionamento quebrado. Recusa alto: sair calado deixaria a conta na empresa principal.
  IF (v_perfil IS NULL) <> (v_tenant_txt IS NULL) THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'Metadados de provisionamento incompletos: perfil e tenant_id vêm juntos.',
      HINT = 'Quem provisiona a conta manda os dois em app_metadata; o cadastro público não manda nenhum.';
  END IF;

  -- tenant_id fora do formato de uuid: mensagem clara em vez do erro cru do Postgres.
  IF v_tenant_txt IS NOT NULL
     AND v_tenant_txt !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'Metadados de provisionamento inválidos: tenant_id do app_metadata não é um uuid válido.',
      HINT = 'Mande em app_metadata.tenant_id o id (uuid) da empresa de destino.';
  END IF;

  v_tenant := v_tenant_txt::uuid;

  SELECT tenant_id INTO v_linha FROM public.users WHERE id = NEW.id;

  -- Marca do primeiro acesso desta mesma transação (handle_new_user), por conta.
  v_marca := NULLIF(current_setting('desk.primeiro_acesso', true), '')::jsonb -> NEW.id::text;

  -- Conta com vínculo e sem papel/empresa do servidor: primeiro acesso (ou vínculo já
  -- feito) continua como está, nada a conferir.
  IF v_linha IS NOT NULL AND (v_perfil IS NULL OR v_tenant IS NULL) THEN
    RETURN NULL;
  END IF;

  -- Papel e empresa vêm do servidor; com eles, até a conta já vinculada é conferida.
  IF v_linha IS NOT NULL THEN
    IF v_linha = v_tenant THEN
      -- Já está na empresa certa: completa o que faltar. O vínculo que existe vale (não
      -- despromove quem já é admin): só cria perfil, papel e cargo ausentes.
      PERFORM public.desk_provisionar_conta(NEW.id, v_email, v_nome, v_perfil, v_tenant);
      RETURN NULL;
    END IF;

    -- Outra empresa: só é corrigível quando foi o primeiro acesso desta transação que pôs
    -- a conta lá (a dona provisionada numa instalação que ainda não tinha administradora).
    IF v_marca IS NULL THEN
      RAISE EXCEPTION USING
        ERRCODE = '42501',
        MESSAGE = 'Cadastro recusado: conta já vinculada a outra empresa.',
        HINT = 'O vínculo existente vale; para mudar de empresa, use a tela de colaboradores.';
    END IF;

    -- Desfaz o primeiro acesso: apaga o vínculo que ele criou, devolve o nome da empresa
    -- principal e apaga a empresa que ele criou (se foi o caso). Em seguida o vínculo é
    -- refeito abaixo, na empresa que o servidor mandou.
    DELETE FROM public.employee_positions
     WHERE employee_id IN (SELECT e.id FROM public.employees e WHERE e.user_id = NEW.id);
    DELETE FROM public.employees  WHERE user_id = NEW.id;
    DELETE FROM public.user_roles WHERE user_id = NEW.id;
    DELETE FROM public.profiles   WHERE user_id = NEW.id;
    DELETE FROM public.users      WHERE id = NEW.id;

    v_renomeou := v_marca->'renomeou';
    IF v_renomeou IS NOT NULL AND v_renomeou ? 'name_gravado' THEN
      -- Só devolve nome e slug de antes se a principal ainda estiver exatamente como o
      -- primeiro acesso a deixou: valor que alguém já mudou não é reescrito por aqui.
      UPDATE public.tenants
         SET name = v_renomeou->>'name',
             slug = v_renomeou->>'slug'
       WHERE id = (v_renomeou->>'id')::uuid
         AND name = v_renomeou->>'name_gravado'
         AND slug = v_renomeou->>'slug_gravado';
    END IF;

    IF COALESCE((v_marca->>'criada')::boolean, false) THEN
      BEGIN
        DELETE FROM public.tenants WHERE id = (v_marca->>'tenant')::uuid;
      EXCEPTION WHEN foreign_key_violation THEN
        NULL;  -- sobrou algo na empresa criada: fica para a limpeza, nada de cascata
      END;
    END IF;
  END IF;

  IF v_perfil IS NULL OR v_tenant IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'Cadastro recusado: conta nova sem papel e empresa definidos pelo servidor.',
      HINT = 'Contas novas entram pelo cadastro de colaborador (admin-create-user) ou pelo provisionamento de empresa (provision-tenant).';
  END IF;

  PERFORM public.desk_provisionar_conta(NEW.id, v_email, v_nome, v_perfil, v_tenant);
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.desk_mfa_situacao()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
      WITH base AS (
        SELECT EXISTS (SELECT 1 FROM public.profiles p
          JOIN public.tenants t ON t.id = p.tenant_id AND t.is_master
          JOIN public.users u ON u.id = p.user_id AND u.tenant_id = p.tenant_id
          WHERE p.user_id = auth.uid() AND p.tenant_id = public.get_user_tenant_id()
            AND u.perfil = 'admin') AS superadmin,
          public.htai_licenca_escopo_instalacao() AS exigida,
          coalesce(auth.jwt() ->> 'aal', 'aal1') AS aal
      )
      SELECT jsonb_build_object(
        'superadmin', superadmin,
        'exigida', exigida AND superadmin,
        'aal', aal,
        'pendente', exigida AND superadmin AND aal <> 'aal2'
      ) FROM base
    $function$
;

CREATE OR REPLACE FUNCTION public.desk_password_change_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_sid_text text := auth.jwt()->>'session_id';
  v_sid uuid;
  v_created timestamptz;
  v_tenant uuid;
  v_required timestamptz;
  v_active boolean := false;
BEGIN
  IF v_user IS NULL OR v_sid_text IS NULL OR v_sid_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN jsonb_build_object('state','invalid_session','requirement_active',false,'session_id',null);
  END IF;
  v_sid := v_sid_text::uuid;
  SELECT u.tenant_id INTO v_tenant FROM public.users u
  JOIN public.profiles p ON p.user_id=u.id AND p.tenant_id=u.tenant_id
  WHERE u.id=v_user AND u.ativo IS DISTINCT FROM false;
  SELECT s.created_at INTO v_created FROM auth.sessions s
  WHERE s.id=v_sid AND s.user_id=v_user AND (s.not_after IS NULL OR s.not_after > now());
  IF v_tenant IS NULL OR v_created IS NULL THEN
    RETURN jsonb_build_object('state','invalid_session','requirement_active',false,'session_id',v_sid);
  END IF;
  SELECT r.required_at INTO v_required FROM public.desk_password_requirements r
  WHERE r.user_id=v_user AND r.completed_at IS NULL;
  v_active := FOUND;
  -- Uma mudança de empresa não apaga a exigência da identidade; somente Auth confirmado conclui.
  RETURN jsonb_build_object('state', CASE WHEN v_active AND v_created >= v_required THEN 'password_change_required' ELSE 'ok' END,
    'requirement_active',v_active,'session_id',v_sid);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.desk_password_session_allowed()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ SELECT (public.desk_password_change_status()->>'state')='ok' $function$
;

CREATE OR REPLACE FUNCTION public.desk_primeiro_acesso_aberto()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT NOT EXISTS (SELECT 1 FROM public.user_roles WHERE role = 'admin')
     AND NOT EXISTS (SELECT 1 FROM public.users WHERE perfil = 'admin');
$function$
;

CREATE OR REPLACE FUNCTION public.desk_provisionar_conta(p_user_id uuid, p_email text, p_nome text, p_perfil text, p_tenant_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role        public.app_role;
  v_position_id UUID;
  v_employee_id UUID;
  v_master      UUID := '00000000-0000-0000-0000-000000000001';
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.tenants WHERE id = p_tenant_id) THEN
    RAISE EXCEPTION 'Empresa % não existe.', p_tenant_id;
  END IF;

  INSERT INTO public.users (id, nome, email, perfil, tenant_id)
  VALUES (p_user_id, p_nome, p_email, p_perfil, p_tenant_id)
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO public.profiles (user_id, tenant_id, full_name)
  VALUES (p_user_id, p_tenant_id, p_nome)
  ON CONFLICT (user_id) DO NOTHING;

  v_position_id := NULL;
  CASE p_perfil
    WHEN 'admin'           THEN v_role := 'admin';   v_position_id := '00000000-0000-0000-0003-000000000001';
    WHEN 'gerente'         THEN v_role := 'manager'; v_position_id := '00000000-0000-0000-0003-000000000002';
    WHEN 'admin_cobranca'  THEN v_role := 'manager'; v_position_id := '00000000-0000-0000-0003-000000000007';
    WHEN 'estrategista'    THEN v_role := 'member';  v_position_id := '00000000-0000-0000-0003-000000000003';
    WHEN 'atendimento'     THEN v_role := 'member';  v_position_id := '00000000-0000-0000-0003-000000000004';
    WHEN 'agente_chat'     THEN v_role := 'member';  v_position_id := '00000000-0000-0000-0003-000000000005';
    WHEN 'agente_cobranca' THEN v_role := 'member';  v_position_id := '00000000-0000-0000-0003-000000000006';
    WHEN 'cliente'         THEN v_role := 'member';  v_position_id := NULL;
    ELSE                        v_role := 'member';  v_position_id := NULL;
  END CASE;

  INSERT INTO public.user_roles (user_id, role, tenant_id)
  VALUES (p_user_id, v_role, p_tenant_id)
  ON CONFLICT (user_id) DO NOTHING;

  -- Os cargos-semente (00000000-0000-0000-0003-...) só existem no tenant mestre.
  IF v_position_id IS NOT NULL AND p_tenant_id = v_master THEN
    INSERT INTO public.employees (tenant_id, user_id, position_id, status, work_email)
    VALUES (p_tenant_id, p_user_id, v_position_id, 'active', p_email)
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_employee_id;

    IF v_employee_id IS NULL THEN
      SELECT id INTO v_employee_id
      FROM public.employees
      WHERE user_id = p_user_id AND tenant_id = p_tenant_id
      LIMIT 1;
    END IF;

    IF v_employee_id IS NOT NULL THEN
      INSERT INTO public.employee_positions (employee_id, position_id, is_primary, tenant_id)
      VALUES (v_employee_id, v_position_id, true, p_tenant_id)
      ON CONFLICT (employee_id, position_id) DO NOTHING;
    END IF;
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.equipe_identidades_confere()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_sessao BOOLEAN := auth.uid() IS NOT NULL;
  v_tel8   TEXT;
BEGIN
  IF v_sessao THEN
    -- Usuário logado só grava na própria empresa e só o que é dele (cadastro).
    IF NEW.tenant_id IS DISTINCT FROM public.get_user_tenant_id() THEN
      RAISE EXCEPTION 'Registro não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
    END IF;
    IF TG_OP = 'INSERT' THEN
      NEW.origem := 'cadastro';
      NEW.instance_uuid := NULL;
      NEW.lid := NULL;
      NEW.lid_aprendido_em := NULL;
      NEW.created_by := auth.uid();
    ELSE
      NEW.origem := OLD.origem;
      NEW.instance_uuid := OLD.instance_uuid;
      NEW.user_id := OLD.user_id;
      NEW.lid := OLD.lid;
      NEW.lid_aprendido_em := OLD.lid_aprendido_em;
    END IF;
  END IF;

  NEW.telefone_norm := private.autoria_chave_tel(NEW.telefone_norm);
  NEW.nome_exibicao := nullif(left(btrim(coalesce(NEW.nome_exibicao, '')), 80), '');
  NEW.updated_at := now();

  -- Trocou o telefone: o LID aprendido era do número antigo.
  IF TG_OP = 'UPDATE' AND NEW.telefone_norm IS DISTINCT FROM OLD.telefone_norm
     AND NEW.lid IS NOT DISTINCT FROM OLD.lid THEN
    NEW.lid := NULL;
    NEW.lid_aprendido_em := NULL;
  END IF;

  -- Pausar nunca é bloqueado.
  IF TG_OP = 'UPDATE' AND NEW.ativo = false
     AND NEW.user_id IS NOT DISTINCT FROM OLD.user_id
     AND NEW.telefone_norm IS NOT DISTINCT FROM OLD.telefone_norm THEN
    RETURN NEW;
  END IF;

  IF NEW.user_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.users u
     WHERE u.id = NEW.user_id
       AND u.tenant_id = NEW.tenant_id
       AND u.perfil IS DISTINCT FROM 'cliente'
       AND (u.ativo IS TRUE OR NOT v_sessao)
  ) THEN
    RAISE EXCEPTION 'Pessoa não encontrada na equipe desta empresa (ou inativa, ou é cliente).' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.instance_uuid IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.whatsapp_instances wi WHERE wi.id = NEW.instance_uuid AND wi.tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'Número de WhatsApp não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.origem <> 'instancia' AND NEW.telefone_norm IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.whatsapp_instances wi
     WHERE wi.tenant_id = NEW.tenant_id
       AND private.autoria_chave_tel(wi.numero_whatsapp) = NEW.telefone_norm
  ) THEN
    RAISE EXCEPTION 'Esse é o número de um WhatsApp da empresa (já reconhecido automaticamente).' USING ERRCODE = 'check_violation';
  END IF;

  -- Cadastro pela tela: telefone de CLIENTE nunca vira "equipe" (senão as
  -- mensagens do cliente passariam a apagar o "aguardando resposta").
  -- Compara DDD + 8 últimos dígitos (com ou sem o 9º dígito).
  IF NEW.origem = 'cadastro' AND NEW.telefone_norm IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.telefone_norm IS DISTINCT FROM OLD.telefone_norm OR (NEW.ativo AND NOT OLD.ativo)) THEN
    v_tel8 := private.autoria_chave_tel8(NEW.telefone_norm);
    IF v_tel8 IS NOT NULL AND (
      EXISTS (SELECT 1 FROM public.clients cl
               WHERE cl.tenant_id = NEW.tenant_id
                 AND (private.autoria_chave_tel8(cl.telefone) = v_tel8 OR private.autoria_chave_tel8(cl.whatsapp) = v_tel8))
      OR EXISTS (SELECT 1 FROM public.contratos co
                  WHERE co.tenant_id = NEW.tenant_id AND private.autoria_chave_tel8(co.whatsapp) = v_tel8)
      OR EXISTS (SELECT 1 FROM public.chat_contacts ct
                  WHERE ct.tenant_id = NEW.tenant_id
                    AND private.autoria_chave_tel8(ct.numero_whatsapp) = v_tel8
                    AND (ct.client_id IS NOT NULL
                         OR EXISTS (SELECT 1 FROM public.chat_contact_clients cc WHERE cc.contact_id = ct.id)))
    ) THEN
      RAISE EXCEPTION 'Esse WhatsApp está no cadastro de um cliente. Confira o número: o de cliente não pode ser marcado como da equipe.'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF NEW.telefone_norm IS NOT NULL AND NEW.ativo AND EXISTS (
    SELECT 1 FROM public.equipe_identidades e
     WHERE e.tenant_id = NEW.tenant_id
       AND e.telefone_norm = NEW.telefone_norm
       AND e.ativo
       AND e.id <> NEW.id
       AND e.user_id IS DISTINCT FROM NEW.user_id
  ) THEN
    RAISE EXCEPTION 'Esse WhatsApp já está cadastrado para outra pessoa da equipe.' USING ERRCODE = 'check_violation';
  END IF;

  IF TG_OP = 'INSERT' THEN
    PERFORM pg_advisory_xact_lock(hashtext('equipe_identidades:' || NEW.tenant_id::text));
    IF (SELECT count(*) FROM public.equipe_identidades WHERE tenant_id = NEW.tenant_id) >= 500 THEN
      RAISE EXCEPTION 'Limite de 500 números da equipe por empresa atingido.' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.origem = 'cadastro' AND (
      SELECT count(*) FROM public.equipe_identidades
       WHERE tenant_id = NEW.tenant_id AND user_id = NEW.user_id AND origem = 'cadastro'
    ) >= 3 THEN
      RAISE EXCEPTION 'Cada pessoa pode ter até 3 WhatsApp cadastrados.' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.equipe_identidades_espelho_instancia()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_tel TEXT := private.autoria_chave_tel(NEW.numero_whatsapp);
BEGIN
  BEGIN
    DELETE FROM public.equipe_identidades e
     WHERE e.instance_uuid = NEW.id AND e.origem = 'instancia'
       AND (e.telefone_norm IS DISTINCT FROM v_tel OR e.tenant_id IS DISTINCT FROM NEW.tenant_id);
    IF v_tel IS NOT NULL AND length(v_tel) BETWEEN 10 AND 15 AND NEW.tenant_id IS NOT NULL THEN
      INSERT INTO public.equipe_identidades (tenant_id, instance_uuid, telefone_norm, nome_exibicao, origem)
      VALUES (NEW.tenant_id, NEW.id, v_tel, left(NEW.nome, 80), 'instancia')
      ON CONFLICT (tenant_id, origem, telefone_norm) WHERE telefone_norm IS NOT NULL
      DO UPDATE SET nome_exibicao = EXCLUDED.nome_exibicao;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'equipe_identidades_espelho_instancia: não espelhado (%)', SQLSTATE;
  END;
  RETURN NULL; -- AFTER
END;
$function$
;

CREATE OR REPLACE FUNCTION public.equipe_identidades_espelho_membro()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  BEGIN
    IF TG_OP IN ('DELETE', 'UPDATE') THEN
      DELETE FROM public.equipe_identidades e
       WHERE e.tenant_id = OLD.tenant_id AND e.origem = 'membro_agente' AND e.user_id = OLD.user_id;
    END IF;
    IF TG_OP IN ('INSERT', 'UPDATE') THEN
      INSERT INTO public.equipe_identidades (tenant_id, user_id, telefone_norm, origem, ativo)
      VALUES (NEW.tenant_id, NEW.user_id, NEW.telefone_chave, 'membro_agente', NEW.ativo)
      ON CONFLICT (tenant_id, origem, telefone_norm) WHERE telefone_norm IS NOT NULL
      DO UPDATE SET user_id = EXCLUDED.user_id, ativo = EXCLUDED.ativo;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- Nunca bloqueia a lista do assistente por causa do espelho.
    RAISE WARNING 'equipe_identidades_espelho_membro: não espelhado (%)', SQLSTATE;
  END;
  RETURN NULL; -- AFTER
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_agent_tma(p_agent_id uuid, p_days integer DEFAULT 7)
 RETURNS TABLE(tma_minutos numeric, total_conversas bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role()='authenticated' AND NOT public.desk_password_session_allowed() THEN RETURN; END IF;
  RETURN QUERY SELECT ROUND(AVG(EXTRACT(EPOCH FROM (c.primeira_resposta_em-c.criado_em))/60)::NUMERIC,1),COUNT(*)
  FROM public.chat_conversations c WHERE c.agente_id=p_agent_id AND c.primeira_resposta_em IS NOT NULL
    AND c.criado_em>=now()-make_interval(days=>p_days);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_client_last_contact(p_client_ids uuid[])
 RETURNS TABLE(client_id uuid, ultimo_contato timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role()='authenticated' AND NOT public.desk_password_session_allowed() THEN RETURN; END IF;
  RETURN QUERY SELECT cc.client_id,MAX(cv.atualizado_em) FROM public.chat_contacts cc
  JOIN public.chat_conversations cv ON cv.contact_id=cc.id
  WHERE cc.client_id=ANY(p_client_ids) AND cv.status!='encerrada' GROUP BY cc.client_id
  UNION ALL SELECT unnest(p_client_ids),NULL::timestamptz WHERE NOT EXISTS (
    SELECT 1 FROM public.chat_contacts cc2 JOIN public.chat_conversations cv2 ON cv2.contact_id=cc2.id
    WHERE cc2.client_id=ANY(p_client_ids));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_contact_client_id(p_contact_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT client_id FROM public.chat_contacts WHERE id=p_contact_id
    AND (auth.role() IS DISTINCT FROM 'authenticated' OR public.desk_password_session_allowed())
$function$
;

CREATE OR REPLACE FUNCTION public.get_internal_last_messages(p_conv_ids uuid[])
 RETURNS TABLE(conversation_id uuid, id uuid, user_id uuid, conteudo text, tipo text, media_url text, criado_em timestamp with time zone, user_nome text, user_perfil text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT DISTINCT ON (m.conversation_id)
    m.conversation_id,
    m.id,
    m.user_id,
    m.conteudo,
    m.tipo::text,
    m.media_url,
    m.criado_em,
    u.nome AS user_nome,
    u.perfil::text AS user_perfil
  FROM internal_messages m
  LEFT JOIN users u ON u.id = m.user_id
  WHERE m.conversation_id = ANY(p_conv_ids)
  ORDER BY m.conversation_id, m.criado_em DESC
$function$
;

CREATE OR REPLACE FUNCTION public.get_internal_unread_counts(p_user_id uuid)
 RETURNS TABLE(conversation_id uuid, unread_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    m.conversation_id,
    COUNT(*) AS unread_count
  FROM internal_messages m
  JOIN internal_conversation_members mem
    ON mem.conversation_id = m.conversation_id AND mem.user_id = p_user_id
  LEFT JOIN internal_message_reads r
    ON r.conversation_id = m.conversation_id AND r.user_id = p_user_id
  WHERE m.user_id <> p_user_id
    AND m.criado_em > COALESCE(r.last_read_at, '1970-01-01T00:00:00Z'::timestamptz)
  GROUP BY m.conversation_id
$function$
;

CREATE OR REPLACE FUNCTION public.get_my_gerente_dept_ids()
 RETURNS uuid[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT ARRAY(
    SELECT department_id
    FROM chat_department_agents
    WHERE user_id = auth.uid()
    AND is_gerente = true
  );
$function$
;

CREATE OR REPLACE FUNCTION public.get_omnx_bridge_credential(p_provider text DEFAULT 'empire'::text)
 RETURNS TABLE(secret text, base_url text, tenant_id uuid, rotation_version integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count int;
BEGIN
  -- "1 empresa por clone": deve haver no máximo 1 integração ativa deste provider.
  SELECT count(*) INTO v_count
  FROM public.tenant_integracoes
  WHERE provider = p_provider AND is_active = true AND secret_key_id IS NOT NULL;

  IF v_count <> 1 THEN
    RETURN; -- 0 (não configurado ainda) ou >1 (ambíguo) → fail-closed, edge cai no fallback/erro
  END IF;

  RETURN QUERY
    SELECT ds.decrypted_secret, ti.base_url, ti.tenant_id, ti.rotation_version
    FROM public.tenant_integracoes ti
    JOIN vault.decrypted_secrets ds ON ds.id = ti.secret_key_id
    WHERE ti.provider = p_provider AND ti.is_active = true
    LIMIT 1;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_omnx_bridge_credential_tenant(p_tenant_id uuid, p_provider text DEFAULT 'empire'::text)
 RETURNS TABLE(secret text, base_url text, tenant_id uuid, rotation_version integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_tenant_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
    SELECT ds.decrypted_secret, ti.base_url, ti.tenant_id, ti.rotation_version
      FROM public.tenant_integracoes ti
      JOIN vault.decrypted_secrets ds ON ds.id = ti.secret_key_id
     WHERE ti.provider  = p_provider
       AND ti.tenant_id = p_tenant_id
       AND ti.is_active = true
       AND ti.secret_key_id IS NOT NULL
     LIMIT 1;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_omnx_integracao_status(p_provider text DEFAULT 'empire'::text)
 RETURNS TABLE(provider text, base_url text, rotation_version integer, is_active boolean, connected boolean, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant   uuid;
  v_is_admin boolean;
BEGIN
  SELECT (perfil = 'admin') INTO v_is_admin FROM public.users WHERE id = auth.uid();
  IF NOT COALESCE(v_is_admin, false) THEN
    RAISE EXCEPTION 'apenas admin';
  END IF;
  v_tenant := public.resolve_tenant_do_clone();
  IF v_tenant IS NULL THEN
    RETURN;
  END IF;
  RETURN QUERY
    SELECT ti.provider, ti.base_url, ti.rotation_version, ti.is_active,
           (ti.secret_key_id IS NOT NULL) AS connected, ti.updated_at
    FROM public.tenant_integracoes ti
    WHERE ti.tenant_id = v_tenant AND ti.provider = p_provider;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_tenant_by_domain(p_domain text)
 RETURNS TABLE(id uuid, name text, slug text, logo_url text, logo_dark_url text, favicon_url text, primary_color text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT id, name, slug, logo_url, logo_dark_url, favicon_url, primary_color
  FROM public.tenants
  WHERE custom_domain IS NOT NULL
    AND LOWER(custom_domain) = LOWER(p_domain)
  LIMIT 1;
$function$
;

CREATE OR REPLACE FUNCTION public.get_tenant_do_usuario(p_user_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT tenant_id FROM public.profiles WHERE user_id = p_user_id LIMIT 1;
$function$
;

CREATE OR REPLACE FUNCTION public.get_unread_counts_for_user(p_user_id uuid, p_instance_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(conversation_id uuid, unread_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH conversas_visiveis AS MATERIALIZED (
    SELECT c.id, c.tenant_id
    FROM public.chat_conversations c
    WHERE ((SELECT auth.uid()) IS NULL OR p_user_id = (SELECT auth.uid()))
      AND (p_instance_ids IS NULL OR c.instance_id = ANY(p_instance_ids))
      AND ((SELECT auth.uid()) IS NULL OR c.tenant_id = (SELECT public.get_user_tenant_id()))
      AND ((SELECT public.pode_ver_restrito())
           OR COALESCE(c.contact_id <> ALL ((SELECT private.chat_contatos_restritos_ids())::uuid[]), true))
  ), leituras_do_usuario AS MATERIALIZED (
    SELECT r.conversation_id, r.last_read_at
    FROM public.chat_message_reads r
    WHERE r.user_id = p_user_id
      AND ((SELECT auth.uid()) IS NULL OR p_user_id = (SELECT auth.uid()))
  )
  SELECT c.id AS conversation_id, nao_lidas.unread_count
  FROM conversas_visiveis c
  LEFT JOIN leituras_do_usuario r ON r.conversation_id = c.id
  CROSS JOIN LATERAL (
    SELECT count(*) AS unread_count
    FROM (
      -- Sem leitura, datas nulas também eram contadas e continuam elegíveis.
      SELECT 1
      FROM public.chat_messages m
      WHERE r.last_read_at IS NULL
        AND m.tenant_id = c.tenant_id
        AND m.conversation_id = c.id
        AND m.enviado_por_agente = false
        AND m.tipo != 'nota_interna'
      UNION ALL
      -- Com leitura, o limite temporal participa da condição do índice.
      SELECT 1
      FROM public.chat_messages m
      WHERE r.last_read_at IS NOT NULL
        AND m.tenant_id = c.tenant_id
        AND m.conversation_id = c.id
        AND m.enviado_por_agente = false
        AND m.tipo != 'nota_interna'
        AND m.criado_em > r.last_read_at
    ) mensagens_candidatas
  ) nao_lidas
  WHERE nao_lidas.unread_count > 0;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_id_by_email(p_email text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select u.id
  from auth.users u
  where lower(u.email) = lower(trim(p_email))
  limit 1;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_tenant_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT p.tenant_id FROM public.profiles p
  JOIN public.users u ON u.id=p.user_id AND u.tenant_id=p.tenant_id
  WHERE p.user_id=auth.uid() AND u.ativo IS DISTINCT FROM false
    AND public.desk_password_session_allowed()
$function$
;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_nome        TEXT;
  v_has_admin   BOOLEAN;
  v_new_tenant  UUID;
  v_email_local TEXT;
  v_empresa     TEXT;
  v_renomeou    JSONB;
  v_gravado     JSONB;
BEGIN
  -- Nome de exibição pode vir da pessoa; papel e empresa, nunca (ver o cabeçalho).
  v_nome := COALESCE(NEW.raw_user_meta_data->>'nome', NEW.email);

  -- Mesma regra da tela de entrada (desk_primeiro_acesso_aberto). Com a porta
  -- aberta, a trava consultiva enfileira cadastros simultâneos e a regra é
  -- conferida de novo depois dela: só um deles vira a primeira administradora.
  -- Com administradora (o caso da produção da empresa) a trava nem é pedida.
  v_has_admin := NOT public.desk_primeiro_acesso_aberto();
  IF NOT v_has_admin THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('omnx-desk:primeiro-acesso', 0));
    v_has_admin := NOT public.desk_primeiro_acesso_aberto();
  END IF;

  -- Com administradora, o vínculo sai do app_metadata no fim da transação
  -- (public.desk_conferir_conta_nova), ou o cadastro é recusado.
  IF v_has_admin THEN
    RETURN NEW;
  END IF;

  -- Instância recém-criada: o 1º usuário vira admin.
  v_email_local := split_part(COALESCE(NEW.email, 'tenant'), '@', 1);
  v_empresa := NULLIF(btrim(COALESCE(NEW.raw_user_meta_data->>'empresa', '')), '');

  -- Instalação do zero: a semente já criou a empresa principal (mestre), vazia.
  -- A primeira conta assume essa empresa em vez de criar uma segunda.
  SELECT t.id INTO v_new_tenant
    FROM public.tenants t
   WHERE t.is_master
     AND NOT EXISTS (SELECT 1 FROM public.users u WHERE u.tenant_id = t.id)
   LIMIT 1;

  IF v_new_tenant IS NOT NULL THEN
    -- Nome da principal antes de renomear: o gatilho adiado devolve este nome se a conta
    -- vier provisionada para outra empresa (instalação que ainda não tinha administradora).
    SELECT jsonb_build_object('id', t.id, 'name', t.name, 'slug', t.slug)
      INTO v_renomeou
      FROM public.tenants t
     WHERE t.id = v_new_tenant;

    UPDATE public.tenants
       SET name = COALESCE(v_empresa, v_nome, v_email_local, 'Minha Empresa'),
           slug = lower(regexp_replace(v_email_local, '[^a-zA-Z0-9]+', '-', 'g')) || '-' || substring(NEW.id::text, 1, 8)
     WHERE id = v_new_tenant
    -- Guarda também o que ficou gravado: o gatilho adiado só devolve nome e slug de antes
    -- se os dois ainda forem exatamente estes.
    RETURNING jsonb_build_object('name_gravado', name, 'slug_gravado', slug)
         INTO v_gravado;

    -- UPDATE que não casa linha nenhuma não devolve linha e zeraria v_gravado (o COALESCE
    -- dentro do RETURNING não salva: variável sem linha volta NULL). A marca `renomeou` tem
    -- que sobreviver, porque com ela nula o gatilho adiado trata a conta como "empresa
    -- criada" e apaga a principal. Aqui a marca só é somada, nunca zerada.
    v_renomeou := COALESCE(v_renomeou, '{}'::jsonb) || COALESCE(v_gravado, '{}'::jsonb);
    PERFORM public.desk_provisionar_conta(NEW.id, NEW.email, v_nome, 'admin', v_new_tenant);
  ELSE
    INSERT INTO public.tenants (name, slug, primary_color)
    VALUES (
      COALESCE(v_empresa, v_nome, v_email_local, 'Minha Empresa'),
      v_email_local || '-' || substring(NEW.id::text, 1, 8),
      '#0B57D0'
    )
    RETURNING id INTO v_new_tenant;

    INSERT INTO public.users (id, nome, email, perfil, tenant_id)
    VALUES (NEW.id, v_nome, NEW.email, 'admin', v_new_tenant)
    ON CONFLICT (id) DO NOTHING;

    INSERT INTO public.profiles (user_id, tenant_id, full_name)
    VALUES (NEW.id, v_new_tenant, v_nome)
    ON CONFLICT (user_id) DO NOTHING;

    INSERT INTO public.user_roles (user_id, role, tenant_id)
    VALUES (NEW.id, 'admin', v_new_tenant)
    ON CONFLICT (user_id) DO NOTHING;
  END IF;

  -- Marca local desta transação: a conta que o primeiro acesso criou, a empresa onde ele a
  -- pôs e, se renomeou a principal, o nome de antes. Só o que esta marca aponta pode ser
  -- desfeito pelo gatilho adiado; conta que já existia nunca é mexida.
  PERFORM set_config(
    'desk.primeiro_acesso',
    (COALESCE(NULLIF(current_setting('desk.primeiro_acesso', true), ''), '{}')::jsonb
      || jsonb_build_object(
           NEW.id::text,
           jsonb_build_object(
             'tenant', v_new_tenant,
             'renomeou', v_renomeou,
             'criada', v_renomeou IS NULL)))::text,
    true);

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.has_permissao(p_recurso text, p_acao text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.get_user_tenant_id() IS NOT NULL AND (
    public.is_admin() OR EXISTS (
      SELECT 1 FROM public.permissoes_app pa
      JOIN public.users u ON u.id = auth.uid() AND u.perfil = pa.perfil
      WHERE pa.tenant_id = public.get_user_tenant_id()
        AND pa.recurso IN (p_recurso, '*')
        AND pa.acao = ANY (CASE p_acao
          WHEN 'ver' THEN ARRAY['ver','editar','admin']
          WHEN 'editar' THEN ARRAY['editar','admin']
          WHEN 'admin' THEN ARRAY['admin'] ELSE ARRAY[]::text[] END)
    )
  )
$function$
;

CREATE OR REPLACE FUNCTION public.has_permissao_de(p_user_id uuid, p_recurso text, p_acao text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH u AS (
    SELECT us.perfil, us.tenant_id
      FROM public.users us
     WHERE us.id = p_user_id
       AND us.ativo IS TRUE
  )
  SELECT
    COALESCE((SELECT u.perfil = 'admin' FROM u), false)
    OR EXISTS (
      SELECT 1
        FROM public.permissoes_app pa
        JOIN u ON pa.tenant_id = u.tenant_id AND pa.perfil = u.perfil
       WHERE pa.recurso IN (p_recurso, '*')
         AND pa.acao IN (
           SELECT unnest(
             CASE p_acao
               WHEN 'ver'    THEN ARRAY['ver','editar','admin']
               WHEN 'editar' THEN ARRAY['editar','admin']
               WHEN 'admin'  THEN ARRAY['admin']
               ELSE ARRAY[p_acao]
             END
           )
         )
    );
$function$
;

CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role app_role)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (SELECT 1 FROM public.user_roles r
    JOIN public.users u ON u.id = r.user_id AND u.tenant_id = r.tenant_id
    JOIN public.profiles p ON p.user_id = u.id AND p.tenant_id = u.tenant_id
    WHERE r.user_id = _user_id AND r.role = _role AND u.ativo IS DISTINCT FROM false)
$function$
;

CREATE OR REPLACE FUNCTION public.htai_banco_novo()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT NOT EXISTS (SELECT 1 FROM auth.users);
$function$
;

CREATE OR REPLACE FUNCTION public.htai_exportar_tabelas()
 RETURNS TABLE(tabela text, ordem text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT c.table_name::text,
         (SELECT o.column_name::text
            FROM information_schema.columns o
           WHERE o.table_schema = 'public' AND o.table_name = c.table_name
             AND o.column_name IN ('id', 'criado_em', 'created_at')
           ORDER BY array_position(ARRAY['id','criado_em','created_at'], o.column_name::text)
           LIMIT 1)
    FROM information_schema.columns c
    JOIN information_schema.tables tb
      ON tb.table_schema = c.table_schema AND tb.table_name = c.table_name
   WHERE c.table_schema = 'public'
     AND c.column_name = 'tenant_id'
     AND tb.table_type = 'BASE TABLE'
     AND c.table_name NOT LIKE '\_%'
     AND c.table_name NOT LIKE '%\_tokens'
     AND c.table_name <> ALL (ARRAY['api_keys','push_subscriptions','wa_webhook_tokens',
                                    'htai_licenca_estado','htai_licenca_assinaturas'])
   ORDER BY 1;
$function$
;

CREATE OR REPLACE FUNCTION public.htai_installation_set_installed_version(p_installed_version text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  INSERT INTO public.htai_app_update (id, installed_version, latest_version, notes, checked_at)
  VALUES (true, p_installed_version, NULL, '[]'::jsonb, now())
  ON CONFLICT (id) DO UPDATE SET installed_version = excluded.installed_version;
END $function$
;

CREATE OR REPLACE FUNCTION public.htai_installation_set_update(p_installed_version text, p_latest_version text, p_notes jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  INSERT INTO public.htai_app_update (id, installed_version, latest_version, notes, checked_at)
  VALUES (true, p_installed_version, p_latest_version,
          CASE WHEN jsonb_typeof(p_notes) = 'array' THEN p_notes ELSE '[]'::jsonb END, now())
  ON CONFLICT (id) DO UPDATE
     SET installed_version = excluded.installed_version, latest_version = excluded.latest_version,
         notes = excluded.notes, checked_at = now();
END $function$
;

CREATE OR REPLACE FUNCTION public.htai_licenca_aplicar_travas()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  t record;
  n integer := 0;
  v_atual text;
BEGIN
  IF public.htai_licenca_modo() = 'off' THEN
    RETURN 0;
  END IF;

  -- Escrita
  FOR t IN
    SELECT c.table_name
      FROM information_schema.columns c
      JOIN information_schema.tables tb
        ON tb.table_schema = c.table_schema AND tb.table_name = c.table_name
     WHERE c.table_schema = 'public'
       AND c.column_name = 'tenant_id'
       AND tb.table_type = 'BASE TABLE'
       AND c.table_name <> ALL (public.htai_licenca_tabelas_livres())
       AND c.table_name NOT LIKE '\_backup%'
       AND NOT EXISTS (
         SELECT 1 FROM pg_trigger g
          WHERE g.tgrelid = format('public.%I', c.table_name)::regclass
            AND g.tgname = 'htai_licenca_trava'
       )
  LOOP
    EXECUTE format(
      'CREATE TRIGGER htai_licenca_trava BEFORE INSERT OR UPDATE OR DELETE ON public.%I '
      'FOR EACH STATEMENT EXECUTE FUNCTION public.htai_licenca_trava_escrita()',
      t.table_name);
    n := n + 1;
  END LOOP;

  -- Leitura (navegador e Realtime)
  FOR t IN
    SELECT c.table_name
      FROM information_schema.columns c
      JOIN information_schema.tables tb
        ON tb.table_schema = c.table_schema AND tb.table_name = c.table_name
     WHERE c.table_schema = 'public'
       AND c.column_name = 'tenant_id'
       AND tb.table_type = 'BASE TABLE'
       AND c.table_name <> ALL (public.htai_licenca_tabelas_leitura_livre())
       AND c.table_name NOT LIKE '\_backup%'
       AND NOT EXISTS (
         SELECT 1 FROM pg_policies pp
          WHERE pp.schemaname = 'public' AND pp.tablename = c.table_name
            AND pp.policyname = 'htai_licenca_leitura'
       )
  LOOP
    EXECUTE format(
      'CREATE POLICY htai_licenca_leitura ON public.%I AS RESTRICTIVE FOR SELECT '
      'TO anon, authenticated USING ((SELECT public.htai_licenca_libera()))',
      t.table_name);
    n := n + 1;
  END LOOP;

  -- Storage (arquivos fora dos buckets livres: leitura e escrita)
  IF NOT EXISTS (SELECT 1 FROM pg_policies
                  WHERE schemaname = 'storage' AND tablename = 'objects'
                    AND policyname = 'htai_licenca_arquivos') THEN
    BEGIN
      EXECUTE 'CREATE POLICY htai_licenca_arquivos ON storage.objects AS RESTRICTIVE FOR ALL '
              'TO anon, authenticated '
              'USING (bucket_id = ANY (public.htai_licenca_buckets_livres()) OR (SELECT public.htai_licenca_libera())) '
              'WITH CHECK (bucket_id = ANY (public.htai_licenca_buckets_livres()) OR (SELECT public.htai_licenca_libera()))';
      n := n + 1;
    EXCEPTION WHEN insufficient_privilege THEN
      RAISE WARNING 'htai_licenca: sem permissão para criar a política do Storage (%).', SQLERRM;
    END;
  END IF;

  -- API do banco: função de pré-requisição (não troca uma já ligada por outra peça).
  SELECT (SELECT split_part(c, '=', 2) FROM unnest(r.rolconfig) c WHERE c LIKE 'pgrst.db\_pre\_request=%' LIMIT 1)
    INTO v_atual
    FROM pg_roles r WHERE r.rolname = 'authenticator';
  IF v_atual IS NULL THEN
    BEGIN
      ALTER ROLE authenticator SET pgrst.db_pre_request = 'public.htai_licenca_pre_request';
      NOTIFY pgrst, 'reload config';
      n := n + 1;
    EXCEPTION WHEN insufficient_privilege THEN
      RAISE WARNING 'htai_licenca: sem permissão para ligar a pré-requisição da API (%).', SQLERRM;
    END;
  ELSIF v_atual <> 'public.htai_licenca_pre_request' THEN
    RAISE WARNING 'htai_licenca: a API já usa outra pré-requisição (%); a lista de RPCs livres não está ativa.', v_atual;
  END IF;

  RETURN n;
END
$function$
;

CREATE OR REPLACE FUNCTION public.htai_licenca_buckets_livres()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT ARRAY['branding','avatars','reportes-anexos']::text[];
$function$
;

CREATE OR REPLACE FUNCTION public.htai_licenca_escopo_instalacao()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT coalesce(public.htai_licenca_segredo('htai_instalacao_id'), '') <> ''
      OR lower(coalesce(public.htai_licenca_segredo('htai_escopo'), '')) = 'instalacao';
$function$
;

CREATE OR REPLACE FUNCTION public.htai_licenca_libera()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT NOT coalesce((public.htai_licenca_situacao() ->> 'nega')::boolean, false);
$function$
;

CREATE OR REPLACE FUNCTION public.htai_licenca_modo()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v text := lower(coalesce(public.htai_licenca_segredo('htai_entitlements_mode'), ''));
BEGIN
  IF public.htai_licenca_escopo_instalacao() THEN
    -- App instalado: só 'shadow' afrouxa; ausente, vazio, 'off' ou inválido = 'enforce'.
    RETURN CASE WHEN v = 'shadow' THEN 'shadow' ELSE 'enforce' END;
  END IF;
  -- Produção da empresa: sem modo configurado = desligado.
  RETURN CASE WHEN v IN ('shadow', 'enforce') THEN v ELSE 'off' END;
END
$function$
;

CREATE OR REPLACE FUNCTION public.htai_licenca_pre_request()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_papel text;
  v_path  text := btrim(coalesce(current_setting('request.path', true), ''), '/');
  v_alvo  text;
  s       jsonb;
BEGIN
  BEGIN
    v_papel := coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '');
  EXCEPTION WHEN OTHERS THEN
    v_papel := '';
  END;
  IF v_papel = 'service_role' THEN
    RETURN;
  END IF;

  IF v_path LIKE 'rpc/%' THEN
    v_alvo := split_part(substr(v_path, 5), '/', 1);
    IF v_alvo = ANY (public.htai_licenca_rpcs_livres()) THEN
      RETURN;
    END IF;
  ELSE
    v_alvo := split_part(v_path, '/', 1);
    IF v_alvo = ANY (public.htai_licenca_tabelas_leitura_livre())
       OR v_alvo = ANY (public.htai_licenca_tabelas_livres()) THEN
      RETURN;
    END IF;
  END IF;

  s := public.htai_licenca_situacao();
  IF coalesce((s ->> 'nega')::boolean, false) THEN
    -- Formato de erro do PostgREST: status HTTP 402 e corpo JSON com a mensagem.
    RAISE SQLSTATE 'PGRST' USING
      MESSAGE = jsonb_build_object(
        'code', 'htai_licenca',
        'message', s ->> 'mensagem',
        'details', s ->> 'motivo',
        'hint', 'Login, Configurações, Ajuda e exportar continuam abertos.'
      )::text,
      DETAIL = '{"status": 402, "headers": {}}';
  ELSIF coalesce((s ->> 'negaria')::boolean, false) THEN
    RAISE LOG 'htai_licenca shadow: negaria a API em /% (%)', v_path, s ->> 'motivo';
  END IF;
END
$function$
;

CREATE OR REPLACE FUNCTION public.htai_licenca_remover_travas()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  t record;
  n integer := 0;
BEGIN
  FOR t IN
    SELECT c.relname
      FROM pg_trigger g
      JOIN pg_class c ON c.oid = g.tgrelid
      JOIN pg_namespace ns ON ns.oid = c.relnamespace
     WHERE ns.nspname = 'public' AND g.tgname = 'htai_licenca_trava'
  LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS htai_licenca_trava ON public.%I', t.relname);
    n := n + 1;
  END LOOP;
  FOR t IN
    SELECT tablename FROM pg_policies
     WHERE schemaname = 'public' AND policyname = 'htai_licenca_leitura'
  LOOP
    EXECUTE format('DROP POLICY IF EXISTS htai_licenca_leitura ON public.%I', t.tablename);
    n := n + 1;
  END LOOP;
  IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage' AND tablename = 'objects'
                AND policyname = 'htai_licenca_arquivos') THEN
    DROP POLICY IF EXISTS htai_licenca_arquivos ON storage.objects;
    n := n + 1;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles r, unnest(r.rolconfig) c
              WHERE r.rolname = 'authenticator'
                AND c = 'pgrst.db_pre_request=public.htai_licenca_pre_request') THEN
    ALTER ROLE authenticator RESET pgrst.db_pre_request;
    NOTIFY pgrst, 'reload config';
    n := n + 1;
  END IF;
  RETURN n;
END
$function$
;

CREATE OR REPLACE FUNCTION public.htai_licenca_rpcs_livres()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT ARRAY[
    'desk_password_change_status','desk_password_session_allowed','desk_mfa_situacao',
    'get_user_tenant_id','get_tenant_by_domain','resolve_tenant_default',
    'has_role','has_permissao','is_admin','is_admin_or_manager','is_manager','is_master_admin',
    'is_comissoes_admin','is_comissoes_gestor','pode_gerir_contratos','pode_ver_restrito',
    'htai_licenca_situacao','htai_licenca_libera','htai_licenca_escopo_instalacao',
    'desk_primeiro_acesso_aberto'
  ]::text[];
$function$
;

CREATE OR REPLACE FUNCTION public.htai_licenca_segredo(p_nome text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v text;
BEGIN
  BEGIN
    SELECT btrim(decrypted_secret) INTO v
      FROM vault.decrypted_secrets
     WHERE name = p_nome
     LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    v := NULL;  -- cofre indisponível = segredo ausente
  END;
  RETURN v;
END
$function$
;

CREATE OR REPLACE FUNCTION public.htai_licenca_situacao()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    DECLARE
      v_modo   text := public.htai_licenca_modo();
      e        public.htai_licenca_estado%ROWTYPE;
      v_motivo text;
      v_folga  timestamptz;
    BEGIN
      IF v_modo = 'off' THEN
        RETURN jsonb_build_object('modo', 'off', 'nega', false, 'negaria', false, 'motivo', NULL,
                                  'mensagem', NULL, 'valido_ate', NULL, 'folga_ate', NULL);
      END IF;

      SELECT * INTO e FROM public.htai_licenca_estado WHERE id;
      IF NOT FOUND OR e.status IS NULL OR e.valid_until IS NULL THEN
        v_motivo := 'nao_ativado';
      ELSIF e.status NOT IN ('active', 'grace') THEN
        v_motivo := e.status;
      ELSE
        v_folga := e.valid_until + make_interval(secs => greatest(e.offline_grace_seconds, 0));
        IF now() >= v_folga THEN v_motivo := 'vencida'; END IF;
      END IF;

      RETURN jsonb_build_object(
        'modo', v_modo,
        'nega', v_motivo IS NOT NULL AND v_modo = 'enforce',
        'negaria', v_motivo IS NOT NULL AND v_modo = 'shadow',
        'motivo', v_motivo,
        'mensagem', CASE
          WHEN v_motivo IS NULL THEN NULL
          WHEN v_motivo = 'nao_ativado' THEN 'Ative a licença deste app. Seus dados estão guardados e você pode exportá-los.'
          WHEN v_motivo = 'suspended' THEN 'A licença deste app está suspensa: o uso foi pausado pela HTAI. Fale com o suporte da HTAI para voltar a usar. Seus dados estão guardados e você pode exportá-los.'
          WHEN v_motivo = 'revoked' THEN 'A licença deste app foi desativada pela HTAI. Fale com o suporte da HTAI para saber o motivo. Seus dados estão guardados e você pode exportá-los.'
          WHEN v_motivo = 'vencida' THEN 'Não foi possível confirmar a licença deste app: ele ficou mais tempo que o permitido sem falar com a HTAI. Ele volta a funcionar sozinho quando a conexão voltar; se continuar assim, fale com o suporte da HTAI. Seus dados estão guardados e você pode exportá-los.'
          -- expired (e qualquer outro motivo, como antes)
          ELSE 'A licença deste app venceu. Renove na sua conta HTAI para voltar a usar. Seus dados estão guardados e você pode exportá-los.'
        END,
        'valido_ate', e.valid_until,
        'folga_ate', v_folga
      );
    END
    $function$
;

