 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT ARRAY[
    'tenants','users','user_roles','profiles','desk_password_requirements','push_subscriptions',
    'app_modules','permissoes_app',
    'reportes_erro'
  ]::text[];
$function$
