CREATE OR REPLACE FUNCTION public.prorrogar_vigencia_contrato(p_contrato_id uuid, p_actor_esperado uuid, p_nova_data date, p_motivo text, p_fim_esperado date, p_status_esperado text, p_reativar boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c public.contratos%ROWTYPE; v_tenant uuid:=public.get_user_tenant_id(); v_skip text;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_actor_esperado OR v_tenant IS NULL OR NOT public.pode_gerir_contratos() THEN
    RAISE EXCEPTION 'Acesso negado.' USING ERRCODE='42501';
  END IF;
  SELECT * INTO c FROM public.contratos WHERE id=p_contrato_id AND tenant_id=v_tenant FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Contrato indisponível.' USING ERRCODE='P0002'; END IF;
  IF c.vigencia_fim IS DISTINCT FROM p_fim_esperado OR c.status IS DISTINCT FROM p_status_esperado THEN
    RAISE EXCEPTION 'O contrato mudou. Atualize a ficha antes de confirmar.' USING ERRCODE='40001';
  END IF;
  IF c.status NOT IN ('ativo','pausado','concluido') OR (p_reativar AND c.status<>'concluido') THEN
    RAISE EXCEPTION 'Este status não permite a operação solicitada.' USING ERRCODE='22023';
  END IF;
  IF p_nova_data IS NULL OR p_nova_data<(now() AT TIME ZONE 'America/Sao_Paulo')::date
    OR (c.vigencia_fim IS NOT NULL AND p_nova_data<=c.vigencia_fim)
    OR char_length(btrim(coalesce(p_motivo,''))) NOT BETWEEN 8 AND 2000 THEN
    RAISE EXCEPTION 'Informe um novo prazo futuro e um motivo entre 8 e 2000 caracteres.' USING ERRCODE='22023';
  END IF;
  v_skip:=coalesce(current_setting('app.skip_venda_resync',true),'');
  PERFORM set_config('app.skip_venda_resync','on',true);
  IF p_reativar THEN
    UPDATE public.contratos SET vigencia_fim=p_nova_data,vigencia_motivo=btrim(p_motivo),status='ativo',status_secundario='ATIVO'
      WHERE id=c.id AND tenant_id=v_tenant RETURNING * INTO c;
  ELSE
    UPDATE public.contratos SET vigencia_fim=p_nova_data,vigencia_motivo=btrim(p_motivo)
      WHERE id=c.id AND tenant_id=v_tenant RETURNING * INTO c;
  END IF;
  PERFORM set_config('app.skip_venda_resync',v_skip,true);
  RETURN jsonb_build_object('id',c.id,'vigencia_fim',c.vigencia_fim,'vigencia_motivo',c.vigencia_motivo,'status',c.status,'status_secundario',c.status_secundario);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.recalcular_cliente_ativo_contratos(p_cliente_id uuid, p_tenant_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_ativo boolean;
BEGIN
  PERFORM 1 FROM public.clients WHERE id=p_cliente_id AND tenant_id=p_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.contratos c WHERE c.tenant_id=p_tenant_id
      AND (c.cliente_id=p_cliente_id OR EXISTS (
        SELECT 1 FROM public.contrato_clientes cc WHERE cc.contrato_id=c.id
          AND cc.tenant_id=c.tenant_id AND cc.cliente_id=p_cliente_id))
      AND (c.status='pausado' OR (c.status='ativo' AND (upper(coalesce(c.status_secundario,''))='PAUSADO'
        OR c.vigencia_fim IS NULL OR c.vigencia_fim>=(now() AT TIME ZONE 'America/Sao_Paulo')::date)))
  ) INTO v_ativo;
  UPDATE public.clients SET ativo=v_ativo WHERE id=p_cliente_id AND tenant_id=p_tenant_id AND ativo IS DISTINCT FROM v_ativo;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.renumerar_parcelas_pagamentos(p_pagamentos jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN p_pagamentos IS NULL
      OR jsonb_typeof(p_pagamentos) <> 'array'
      OR jsonb_array_length(p_pagamentos) = 0
    THEN p_pagamentos
    ELSE (
      WITH itens AS (
        SELECT
          e.value AS item,
          e.ord,
          (e.value->>'sinal') ~* '^\s*parcela(\s+[0-9]+)?\s*$' AS eh_parcela,
          CASE
            WHEN (e.value->>'data') ~ '^\d{4}-\d{2}-\d{2}'
            THEN (e.value->>'data')::date
          END AS dt
        FROM jsonb_array_elements(p_pagamentos) WITH ORDINALITY AS e(value, ord)
      ),
      numeradas AS (
        SELECT
          item, ord, eh_parcela,
          ROW_NUMBER() OVER (PARTITION BY eh_parcela ORDER BY dt NULLS LAST, ord) AS n
        FROM itens
      )
      SELECT jsonb_agg(
               CASE
                 WHEN eh_parcela
                 THEN jsonb_set(item, '{sinal}', to_jsonb('Parcela ' || n::text))
                 ELSE item
               END
               ORDER BY ord
             )
      FROM numeradas
    )
  END;
$function$
;

CREATE OR REPLACE FUNCTION public.resolve_tenant_default()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    public.get_user_tenant_id(),
    (SELECT t.id FROM public.tenants t
      WHERE (SELECT count(*) FROM public.tenants) = 1
      LIMIT 1)
  );
$function$
;

CREATE OR REPLACE FUNCTION public.resolve_tenant_do_clone()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid;
  v_count  int;
BEGIN
  BEGIN
    v_tenant := public.get_user_tenant_id();
  EXCEPTION WHEN OTHERS THEN
    v_tenant := NULL;
  END;
  IF v_tenant IS NOT NULL THEN
    RETURN v_tenant;
  END IF;
  SELECT count(*) INTO v_count FROM public.tenants;
  IF v_count = 1 THEN
    SELECT id INTO v_tenant FROM public.tenants LIMIT 1;
    RETURN v_tenant;
  END IF;
  RETURN NULL; -- ambíguo: 0 ou >1 tenant e sem contexto de usuário
END;
$function$
;

CREATE OR REPLACE FUNCTION public.resumo_saude_apps(p_horas integer DEFAULT 24)
 RETURNS TABLE(app text, erros bigint, avisos bigint, ultimo timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT l.app,
         count(*) FILTER (WHERE l.nivel = 'erro')  AS erros,
         count(*) FILTER (WHERE l.nivel = 'aviso') AS avisos,
         max(l.created_at)                         AS ultimo
    FROM public.app_logs l
   WHERE l.created_at >= now() - make_interval(hours => p_horas)
   GROUP BY l.app
   ORDER BY erros DESC, l.app;
$function$
;

CREATE OR REPLACE FUNCTION public.revoke_omnx_integracao(p_provider text DEFAULT 'empire'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant    uuid;
  v_is_admin  boolean;
  v_secret_id uuid;
BEGIN
  SELECT (perfil = 'admin') INTO v_is_admin FROM public.users WHERE id = auth.uid();
  IF NOT COALESCE(v_is_admin, false) THEN
    RAISE EXCEPTION 'apenas admin';
  END IF;
  v_tenant := public.resolve_tenant_do_clone();
  IF v_tenant IS NULL THEN
    RETURN;
  END IF;

  SELECT secret_key_id INTO v_secret_id
  FROM public.tenant_integracoes
  WHERE tenant_id = v_tenant AND provider = p_provider;

  DELETE FROM public.tenant_integracoes WHERE tenant_id = v_tenant AND provider = p_provider;
  IF v_secret_id IS NOT NULL THEN
    DELETE FROM vault.secrets WHERE id = v_secret_id;
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.salvar_uazapi_token_cobranca(p_instance uuid, p_token text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_tenant    uuid;
  v_inst      public.cobranca_instances%ROWTYPE;
  v_atual     public.cobranca_instance_tokens%ROWTYPE;
  v_token     text := NULLIF(btrim(COALESCE(p_token, '')), '');
  v_secret_id uuid;
BEGIN
  v_tenant := public.get_user_tenant_id();
  IF v_tenant IS NULL OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'apenas administrador pode salvar o token do número'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_inst FROM public.cobranca_instances
   WHERE id = p_instance AND tenant_id = v_tenant;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'número não encontrado nesta empresa';
  END IF;

  IF v_token IS NOT NULL AND (length(v_token) > 512 OR v_token ~ '\s') THEN
    RAISE EXCEPTION 'token inválido';
  END IF;

  SELECT * INTO v_atual FROM public.cobranca_instance_tokens WHERE instance_uuid = p_instance;

  IF v_token IS NULL THEN
    IF FOUND THEN
      DELETE FROM public.cobranca_instance_tokens WHERE instance_uuid = p_instance;
      DELETE FROM vault.secrets WHERE id = v_atual.secret_key_id;
    END IF;
    RETURN false;
  END IF;

  IF FOUND THEN
    PERFORM vault.update_secret(v_atual.secret_key_id, v_token);
    UPDATE public.cobranca_instance_tokens
       SET atualizado_por = auth.uid(), atualizado_em = now()
     WHERE instance_uuid = p_instance;
  ELSE
    v_secret_id := vault.create_secret(
      v_token,
      'uazapi_cobranca:' || p_instance::text || ':' || gen_random_uuid()::text,
      'Token UAZAPI do número de cobrança ' || v_inst.instance_id
    );
    INSERT INTO public.cobranca_instance_tokens (instance_uuid, tenant_id, secret_key_id, atualizado_por)
    VALUES (p_instance, v_tenant, v_secret_id, auth.uid());
  END IF;

  RETURN true;  -- nunca devolve o token
END;
$function$
;

CREATE OR REPLACE FUNCTION public.salvar_uazapi_token_numero(p_instance uuid, p_token text)
 RETURNS boolean
