$function$
;

CREATE OR REPLACE FUNCTION public.tg_atendimento_demanda_historico()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.etapa_id IS DISTINCT FROM OLD.etapa_id THEN
    INSERT INTO public.atendimento_historico (tenant_id, demanda_id, campo, valor_de, valor_para)
    VALUES (NEW.tenant_id, NEW.id, 'etapa',
            (SELECT nome FROM public.atendimento_etapas WHERE id = OLD.etapa_id),
            (SELECT nome FROM public.atendimento_etapas WHERE id = NEW.etapa_id));
  END IF;

  IF NEW.responsavel_id IS DISTINCT FROM OLD.responsavel_id THEN
    INSERT INTO public.atendimento_historico (tenant_id, demanda_id, campo, valor_de, valor_para)
    VALUES (NEW.tenant_id, NEW.id, 'responsavel',
            (SELECT nome FROM public.users WHERE id = OLD.responsavel_id),
            (SELECT nome FROM public.users WHERE id = NEW.responsavel_id));
  END IF;

  IF NEW.prazo IS DISTINCT FROM OLD.prazo THEN
    INSERT INTO public.atendimento_historico (tenant_id, demanda_id, campo, valor_de, valor_para)
    VALUES (NEW.tenant_id, NEW.id, 'prazo', OLD.prazo::text, NEW.prazo::text);
  END IF;

  IF NEW.prioridade IS DISTINCT FROM OLD.prioridade THEN
    INSERT INTO public.atendimento_historico (tenant_id, demanda_id, campo, valor_de, valor_para)
    VALUES (NEW.tenant_id, NEW.id, 'prioridade', OLD.prioridade, NEW.prioridade);
  END IF;

  IF NEW.aprovacao IS DISTINCT FROM OLD.aprovacao THEN
    INSERT INTO public.atendimento_historico (tenant_id, demanda_id, campo, valor_de, valor_para)
    VALUES (NEW.tenant_id, NEW.id, 'aprovacao', OLD.aprovacao, NEW.aprovacao);
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_atendimento_demanda_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_final boolean;
BEGIN
  NEW.updated_at := now();

  IF NEW.etapa_id IS DISTINCT FROM OLD.etapa_id THEN
    SELECT is_final INTO v_final FROM public.atendimento_etapas WHERE id = NEW.etapa_id;
    IF COALESCE(v_final, false) THEN
      NEW.concluida_em := COALESCE(NEW.concluida_em, now());
    ELSE
      -- Voltou para uma etapa de trabalho: deixa de estar concluída.
      NEW.concluida_em := NULL;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_atendimento_whatsapp_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_final boolean;
BEGIN
  IF current_user <> 'service_role' THEN
    IF TG_OP = 'INSERT' THEN
      IF NEW.wa_origem_mensagem_id IS NOT NULL OR NEW.wa_ultima_analise IS NOT NULL
         OR NEW.wa_resolucao_mensagem_id IS NOT NULL OR NEW.wa_resolvida_manualmente
         OR NEW.wa_reaberta_em IS NOT NULL THEN
        RAISE EXCEPTION 'Origem WhatsApp é registrada somente pelo processamento autorizado.' USING ERRCODE = '42501';
      END IF;
    ELSE
      IF ROW(NEW.wa_origem_mensagem_id, NEW.wa_ultima_analise, NEW.wa_resolucao_mensagem_id,
             NEW.wa_resolvida_manualmente, NEW.wa_reaberta_em)
         IS DISTINCT FROM ROW(OLD.wa_origem_mensagem_id, OLD.wa_ultima_analise, OLD.wa_resolucao_mensagem_id,
             OLD.wa_resolvida_manualmente, OLD.wa_reaberta_em) THEN
        RAISE EXCEPTION 'Metadados de sincronização não são editáveis.' USING ERRCODE = '42501';
      END IF;
    END IF;
  END IF;
  IF NEW.wa_origem_mensagem_id IS NULL THEN RETURN NEW; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.clients c WHERE c.id = NEW.cliente_id AND c.tenant_id = NEW.tenant_id) THEN
    RAISE EXCEPTION 'Cliente não pertence à empresa do ticket.' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND ROW(NEW.cliente_id, NEW.tenant_id, NEW.wa_origem_mensagem_id)
      IS DISTINCT FROM ROW(OLD.cliente_id, OLD.tenant_id, OLD.wa_origem_mensagem_id) THEN
    RAISE EXCEPTION 'O vínculo de origem do ticket é imutável.' USING ERRCODE = '23514';
  END IF;
  IF NEW.etapa_id IS NOT NULL THEN
    SELECT e.is_final INTO v_final FROM public.atendimento_etapas e WHERE e.id = NEW.etapa_id AND e.tenant_id = NEW.tenant_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Etapa não pertence à empresa do ticket.' USING ERRCODE = '23514'; END IF;
  END IF;
  IF TG_OP = 'UPDATE' AND current_user <> 'service_role' THEN
    -- Conclusão é derivada da etapa; um PATCH em concluida_em não forja baixa.
    IF NEW.etapa_id IS NOT DISTINCT FROM OLD.etapa_id THEN
      NEW.concluida_em := OLD.concluida_em;
    ELSIF COALESCE(v_final, false) THEN
      NEW.wa_resolvida_manualmente := true;
      NEW.wa_resolucao_mensagem_id := NULL;
    ELSIF OLD.concluida_em IS NOT NULL THEN
      NEW.wa_resolvida_manualmente := false;
      NEW.wa_resolucao_mensagem_id := NULL;
      NEW.wa_reaberta_em := clock_timestamp();
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_atendimento_whatsapp_ia_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF current_user <> 'service_role' THEN
    IF TG_OP = 'INSERT' THEN
      IF NEW.wa_resolucao_metodo IS NOT NULL OR NEW.wa_resolucao_motivo IS NOT NULL
        OR NEW.wa_resolucao_confianca IS NOT NULL OR cardinality(NEW.wa_resolucao_evidencias) <> 0
        OR NEW.wa_resolucao_modelo IS NOT NULL OR NEW.wa_resolucao_versao IS NOT NULL THEN
        RAISE EXCEPTION 'Evidência automática não pode ser fabricada.' USING ERRCODE = '42501';
      END IF;
    ELSE
      IF ROW(NEW.wa_resolucao_metodo, NEW.wa_resolucao_motivo, NEW.wa_resolucao_confianca, NEW.wa_resolucao_evidencias,NEW.wa_resolucao_modelo,NEW.wa_resolucao_versao)
        IS DISTINCT FROM ROW(OLD.wa_resolucao_metodo, OLD.wa_resolucao_motivo, OLD.wa_resolucao_confianca, OLD.wa_resolucao_evidencias,OLD.wa_resolucao_modelo,OLD.wa_resolucao_versao) THEN
        RAISE EXCEPTION 'Evidência automática não é editável.' USING ERRCODE = '42501';
      END IF;
      IF NEW.etapa_id IS DISTINCT FROM OLD.etapa_id THEN
        NEW.wa_resolucao_metodo := NULL; NEW.wa_resolucao_motivo := NULL;
        NEW.wa_resolucao_confianca := NULL; NEW.wa_resolucao_evidencias := '{}'::uuid[];
        NEW.wa_resolucao_modelo := NULL; NEW.wa_resolucao_versao := NULL;
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_atendimento_whatsapp_sugestao_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF current_user <> 'service_role' AND (NEW.wa_sugestao_em IS NOT NULL OR cardinality(NEW.wa_sugestao_evidencias) <> 0) THEN
      RAISE EXCEPTION 'Sugestão automática não pode ser fabricada.' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.etapa_id IS DISTINCT FROM OLD.etapa_id AND OLD.wa_sugestao_em IS NOT NULL
     AND NEW.wa_sugestao_em IS NOT DISTINCT FROM OLD.wa_sugestao_em THEN
    NEW.wa_sugestao_em := NULL; NEW.wa_sugestao_razao := NULL; NEW.wa_sugestao_motivo := NULL;
    NEW.wa_sugestao_confianca := NULL; NEW.wa_sugestao_evidencias := '{}'::uuid[];
    NEW.wa_sugestao_modelo := NULL; NEW.wa_sugestao_versao := NULL;
  END IF;
  IF current_user <> 'service_role' AND NEW.wa_sugestao_em IS NOT NULL
     AND ROW(NEW.wa_sugestao_em, NEW.wa_sugestao_razao, NEW.wa_sugestao_motivo, NEW.wa_sugestao_confianca,
             NEW.wa_sugestao_evidencias, NEW.wa_sugestao_modelo, NEW.wa_sugestao_versao)
     IS DISTINCT FROM ROW(OLD.wa_sugestao_em, OLD.wa_sugestao_razao, OLD.wa_sugestao_motivo, OLD.wa_sugestao_confianca,
             OLD.wa_sugestao_evidencias, OLD.wa_sugestao_modelo, OLD.wa_sugestao_versao) THEN
    RAISE EXCEPTION 'Sugestão automática não é editável; só pode ser recusada.' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_atendimento_whatsapp_sugestao_historico()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_final boolean; v_valor text;
BEGIN
  IF NEW.wa_sugestao_em IS NOT DISTINCT FROM OLD.wa_sugestao_em THEN RETURN NEW; END IF;
  IF OLD.wa_sugestao_em IS NULL THEN
    v_valor := 'sugerida';
  ELSIF NEW.wa_sugestao_em IS NOT NULL THEN
    v_valor := 'substituida';
  ELSE
    SELECT e.is_final INTO v_final FROM public.atendimento_etapas e WHERE e.id = NEW.etapa_id AND e.tenant_id = NEW.tenant_id;
    IF NEW.etapa_id IS NOT DISTINCT FROM OLD.etapa_id THEN v_valor := 'recusada';
    ELSIF COALESCE(v_final, false) AND auth.uid() IS NOT NULL THEN v_valor := 'aprovada';
    ELSIF COALESCE(v_final, false) THEN v_valor := 'resolvida pela Íris';
    ELSE v_valor := 'descartada';
    END IF;
  END IF;
  INSERT INTO public.atendimento_historico (tenant_id, demanda_id, autor_id, campo, valor_de, valor_para)
  VALUES (NEW.tenant_id, NEW.id, auth.uid(), 'sugestao_ia',
    COALESCE(OLD.wa_sugestao_razao, NEW.wa_sugestao_razao), v_valor);
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_contrato_ressincronizar_venda_crm()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault', 'net'
AS $function$
declare
  v_secret text;
  v_venda  record;
begin
  -- Disjuntor para imports/backfills em massa:
  --   SET LOCAL app.skip_venda_resync = 'on';  antes do lote.
  if coalesce(current_setting('app.skip_venda_resync', true), '') = 'on' then
    return new;
  end if;

  -- Sem venda vinculada não há o que atualizar no CRM.
  if new.venda_pendente_id is null then
    return new;
  end if;

  -- Só interessa quando algo que o CRM exibe muda. Sem este recorte, qualquer edição
  -- do contrato (valor, produto, tag) viraria uma chamada HTTP inútil.
  if tg_op = 'UPDATE'
     and old.status           is not distinct from new.status
     and old.link_clicksign   is not distinct from new.link_clicksign
     and old.data_assinatura  is not distinct from new.data_assinatura
  then
    return new;
  end if;

  -- A venda precisa já estar vinculada a uma oportunidade no CRM. Venda sem vínculo
  -- não tem para onde ir: continua na fila de pendência de vínculo, como hoje.
  select id, ghl_oportunidade_id, sincronizado_em
    into v_venda
  from public.vendas_pendentes
  where id = new.venda_pendente_id;

  if v_venda.id is null or v_venda.ghl_oportunidade_id is null or v_venda.sincronizado_em is null then
    return new;
  end if;

  select decrypted_secret into v_secret
  from vault.decrypted_secrets
  where name = 'notify_webhook_secret';

  if v_secret is null then
    return new;  -- sem secret configurado, não há como chamar: não quebra a edição
  end if;

  -- Assíncrono (pg_net enfileira e envia após o commit). O Authorization com a anon key
  -- só passa pelo gateway; a autorização real é o header x-notify-secret.
  perform net.http_post(
    url := 'https://wuzmckatbmlpkdxtfhqr.supabase.co/functions/v1/vendas-ressincronizar-crm',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Ind1em1ja2F0Ym1scGtkeHRmaHFyIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzMxNjUxNzEsImV4cCI6MjA4ODc0MTE3MX0.dL8LHbCJv69zJtt-aA3iAEO6PMcJBHlDC1HAEu9O9Ho',
      'x-notify-secret', v_secret
    ),
    body := jsonb_build_object('venda_id', v_venda.id),
    timeout_milliseconds := 60000
  );

  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.tg_crm_omnx_contrato()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF coalesce(current_setting('app.skip_crm_notify', true), '') = 'on' THEN
    RETURN NEW;
  END IF;

  -- O CRM conhece a venda, não o contrato solto.
  IF NEW.venda_pendente_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    -- O rascunho criado junto com a venda já vai no evento desk.venda.registrada.
    IF NULLIF(btrim(COALESCE(NEW.link_clicksign, '')), '') IS NULL
       AND NEW.data_assinatura IS NULL
       AND COALESCE(NEW.status, 'rascunho') = 'rascunho' THEN
      RETURN NEW;
    END IF;
  ELSIF OLD.status            IS NOT DISTINCT FROM NEW.status
    AND OLD.status_secundario IS NOT DISTINCT FROM NEW.status_secundario
    AND OLD.link_clicksign    IS NOT DISTINCT FROM NEW.link_clicksign
    AND OLD.data_assinatura   IS NOT DISTINCT FROM NEW.data_assinatura
  THEN
    RETURN NEW;
  END IF;

  IF NOT public.crm_omnx_ativo(NEW.tenant_id) THEN
    RETURN NEW;
  END IF;

  PERFORM public.crm_omnx_chamar_notificar(jsonb_build_object('contrato_id', NEW.id));
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_crm_omnx_venda()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_antes  jsonb;
  v_depois jsonb;
BEGIN
  IF coalesce(current_setting('app.skip_crm_notify', true), '') = 'on' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.origem = 'crm' THEN
      RETURN NEW;  -- veio do CRM: não volta para lá
    END IF;
    IF NOT public.crm_omnx_ativo(NEW.tenant_id) THEN
      RETURN NEW;
    END IF;
    PERFORM public.crm_omnx_chamar_notificar(
      jsonb_build_object('venda_id', NEW.id, 'evento', 'desk.venda.registrada'));
    RETURN NEW;
  END IF;

  -- UPDATE: só os campos que vão ao CRM (os mesmos da ponte Empire em
  -- 20260804214000, mais os que a forma comum da venda leva) e o status. Colunas de
  -- controle (crm_*, ghl_*, sincronizado_em, comprovantes) ficam de fora — gravar o
  -- resultado do envio não redispara o gatilho.
  v_antes := jsonb_build_object(
    'status',               OLD.status,
    'cliente_nome',         OLD.cliente_nome,
    'cliente_razao_social', OLD.cliente_razao_social,
    'cliente_cpf_cnpj',     OLD.cliente_cpf_cnpj,
    'cliente_email',        OLD.cliente_email,
    'cliente_whatsapp',     OLD.cliente_whatsapp,
    'cliente_instagram',    OLD.cliente_instagram,
    'cliente_logradouro',   OLD.cliente_logradouro,
    'cliente_endereco',     OLD.cliente_endereco,
    'cliente_numero',       OLD.cliente_numero,
    'cliente_complemento',  OLD.cliente_complemento,
    'cliente_bairro',       OLD.cliente_bairro,
    'cliente_municipio',    OLD.cliente_municipio,
    'cliente_uf',           OLD.cliente_uf,
    'cliente_cep',          OLD.cliente_cep,
    'produto_nome',         OLD.produto_nome,
    'valor_total_venda',    OLD.valor_total_venda,
    'observacoes',          OLD.observacoes,
    'closer_nome',          OLD.closer_nome,
    'closer_email',         OLD.closer_email,
    'pagamentos',           OLD.pagamentos,
    'pagador_diferente',    OLD.pagador_diferente,
    'pagador_nome',         OLD.pagador_nome,
    'pagador_cpf_cnpj',     OLD.pagador_cpf_cnpj,
    'pagador_relacao',      OLD.pagador_relacao
  );
  v_depois := jsonb_build_object(
    'status',               NEW.status,
    'cliente_nome',         NEW.cliente_nome,
    'cliente_razao_social', NEW.cliente_razao_social,
    'cliente_cpf_cnpj',     NEW.cliente_cpf_cnpj,
    'cliente_email',        NEW.cliente_email,
    'cliente_whatsapp',     NEW.cliente_whatsapp,
    'cliente_instagram',    NEW.cliente_instagram,
    'cliente_logradouro',   NEW.cliente_logradouro,
    'cliente_endereco',     NEW.cliente_endereco,
    'cliente_numero',       NEW.cliente_numero,
    'cliente_complemento',  NEW.cliente_complemento,
    'cliente_bairro',       NEW.cliente_bairro,
    'cliente_municipio',    NEW.cliente_municipio,
    'cliente_uf',           NEW.cliente_uf,
    'cliente_cep',          NEW.cliente_cep,
    'produto_nome',         NEW.produto_nome,
    'valor_total_venda',    NEW.valor_total_venda,
    'observacoes',          NEW.observacoes,
    'closer_nome',          NEW.closer_nome,
    'closer_email',         NEW.closer_email,
    'pagamentos',           NEW.pagamentos,
    'pagador_diferente',    NEW.pagador_diferente,
    'pagador_nome',         NEW.pagador_nome,
    'pagador_cpf_cnpj',     NEW.pagador_cpf_cnpj,
    'pagador_relacao',      NEW.pagador_relacao
  );
  IF v_antes IS NOT DISTINCT FROM v_depois THEN
    RETURN NEW;
  END IF;
  IF NOT public.crm_omnx_ativo(NEW.tenant_id) THEN
    RETURN NEW;
  END IF;

  PERFORM public.crm_omnx_chamar_notificar(
    jsonb_build_object('venda_id', NEW.id, 'evento', 'desk.venda.atualizada'));
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_email_queue_tenant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ref uuid;
begin
  if new.tenant_id is not null then
    return new;
  end if;

  -- 1) pela referência, quando ela aponta para um registro de verdade
  if new.referencia_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    v_ref := new.referencia_id::uuid;

    if new.referencia_tipo = 'contrato' then
      select tenant_id into new.tenant_id from public.contratos where id = v_ref;
    elsif new.referencia_tipo in ('venda', 'vendas_sync', 'venda_pendente') then
      select tenant_id into new.tenant_id from public.vendas_pendentes where id = v_ref;
    elsif new.referencia_tipo = 'cliente' then
      select tenant_id into new.tenant_id from public.clients where id = v_ref;
    end if;
  end if;

  -- 2) pelo destinatário, quando é gente de casa
  if new.tenant_id is null then
    select tenant_id into new.tenant_id
    from public.users
    where lower(email) = lower(new.destinatario_email)
    limit 1;
  end if;

  -- 3) último recurso — e-mail transacional não pode travar
  if new.tenant_id is null then
    new.tenant_id := public.tenant_fallback_mais_antigo();
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_ghl_marcar_assinada()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault', 'net'
AS $function$
declare
  v_link_novo  text := nullif(btrim(coalesce(new.link_clicksign, '')), '');
  v_link_velho text;
  v_secret     text;
begin
  -- Disjuntor para imports/backfills em massa (mesmo flag do e-mail de assinatura):
  --   SET LOCAL app.skip_contrato_notify = 'on';  antes do lote.
  if coalesce(current_setting('app.skip_contrato_notify', true), '') = 'on' then
    return new;
  end if;

  -- Só interessa quando o contrato PASSA a ter link do Clicksign.
  if v_link_novo is null then
    return new;
  end if;

  if tg_op = 'UPDATE' then
    v_link_velho := nullif(btrim(coalesce(old.link_clicksign, '')), '');
    if v_link_velho is not null then
      return new;  -- já tinha link antes; não é uma nova assinatura
    end if;
  end if;

  -- Idempotência: não redispara se já foi sincronizado com sucesso.
  if new.ghl_assinada_sincronizada_em is not null then
    return new;
  end if;

  select decrypted_secret into v_secret
  from vault.decrypted_secrets
  where name = 'notify_webhook_secret';

  -- Chamada assíncrona (pg_net enfileira e envia após o commit).
  -- Authorization usa a anon key (pública) só para passar o gateway;
  -- a autorização real é o header x-notify-secret.
  perform net.http_post(
    url := 'https://wuzmckatbmlpkdxtfhqr.supabase.co/functions/v1/empire-contrato-assinado-ghl',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Ind1em1ja2F0Ym1scGtkeHRmaHFyIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzMxNjUxNzEsImV4cCI6MjA4ODc0MTE3MX0.dL8LHbCJv69zJtt-aA3iAEO6PMcJBHlDC1HAEu9O9Ho',
      'x-notify-secret', v_secret
    ),
    body := jsonb_build_object('contrato_id', new.id),
    timeout_milliseconds := 60000
  );

  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.tg_herda_tenant_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pai_tabela text := tg_argv[0];
  v_pai_coluna text := tg_argv[1];
  v_pai_id     uuid;
  v_tenant     uuid;
begin
  if new.tenant_id is not null then
    return new;
  end if;

  v_pai_id := (to_jsonb(new) ->> v_pai_coluna)::uuid;
  if v_pai_id is null then
    return new;
  end if;

  execute format('select tenant_id from public.%I where id = $1', v_pai_tabela)
    into v_tenant using v_pai_id;

  if v_tenant is not null then
    new.tenant_id := v_tenant;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_notificar_reporte_novo()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault', 'net'
AS $function$
declare
  v_secret     text;
  v_admin      record;
  v_html       text;
  v_assunto    text;
  v_impacto    text;
  v_url_painel text := 'https://desk.omnx.pro/reportes';
begin
  -- Disjuntor para import/backfill em massa:
  --   SET LOCAL app.skip_reporte_email = 'on';
  if coalesce(current_setting('app.skip_reporte_email', true), '') = 'on' then
    return new;
  end if;

  -- Dúvida e sugestão não acordam ninguém: o aviso existe para o que quebrou.
  -- Sem este recorte, o canal vira ruído e a equipe passa a ignorar o alerta —
  -- que é exatamente o problema que ele veio resolver.
  if new.categoria <> 'bug' then
    return new;
  end if;

  select decrypted_secret into v_secret
  from vault.decrypted_secrets
  where name = 'notify_webhook_secret';

  if v_secret is null then
    return new;  -- sem secret configurado não há como chamar; o reporte segue gravado
  end if;

  v_impacto := case new.impacto
    when 'critico' then 'CRÍTICO'
    when 'alto'    then 'Alto'
    when 'medio'   then 'Médio'
    else 'Baixo'
  end;

  v_assunto := '[' || new.protocolo || '] ' ||
               case when new.impacto in ('critico','alto') then 'Erro ' || v_impacto || ': ' else 'Novo reporte: ' end ||
               new.titulo;

  -- HTML simples de propósito: é aviso operacional, não peça de marketing.
  -- Cliente de e-mail corporativo corta CSS elaborado e o que sobra fica pior.
  v_html :=
    '<h2>' || coalesce(new.titulo, 'Reporte sem título') || '</h2>' ||
    '<p><strong>Protocolo:</strong> ' || new.protocolo ||
    '<br><strong>Impacto:</strong> ' || v_impacto ||
    '<br><strong>Quem reportou:</strong> ' || coalesce(new.reportado_nome, 'não informado') ||
      ' (' || coalesce(new.reportado_email, 'sem e-mail') || ')' ||
    '<br><strong>Módulo:</strong> ' || coalesce(new.modulo, '—') ||
    '<br><strong>Tela:</strong> ' || coalesce(new.rota, '—') || '</p>' ||
    case when coalesce(new.descricao, '') <> ''
      then '<p><strong>O que aconteceu</strong><br>' || replace(new.descricao, chr(10), '<br>') || '</p>'
      else '' end ||
    case when coalesce(new.passos, '') <> ''
      then '<p><strong>Passos para reproduzir</strong><br>' || replace(new.passos, chr(10), '<br>') || '</p>'
      else '' end ||
    '<p><a href="' || v_url_painel || '">Abrir a triagem no painel</a></p>' ||
    '<p style="color:#666;font-size:12px">Print da tela, console e rede ficam no painel — ' ||
    'não são enviados por e-mail.</p>';

  -- Um e-mail por admin ATIVO do MESMO tenant do reporte. Sem isso, o admin de
  -- uma empresa receberia o erro de outra — vazamento entre tenants por e-mail,
  -- que a RLS do painel impediria mas o aviso não.
  for v_admin in
    select u.email, u.nome
    from public.users u
    where u.tenant_id = new.tenant_id
      and u.perfil = 'admin'
      and coalesce(u.ativo, true) = true
      and coalesce(u.email, '') <> ''
  loop
    perform net.http_post(
      url := 'https://wuzmckatbmlpkdxtfhqr.supabase.co/functions/v1/send-email',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Ind1em1ja2F0Ym1scGtkeHRmaHFyIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzMxNjUxNzEsImV4cCI6MjA4ODc0MTE3MX0.dL8LHbCJv69zJtt-aA3iAEO6PMcJBHlDC1HAEu9O9Ho',
        'x-notify-secret', v_secret
      ),
      body := jsonb_build_object(
        'to', v_admin.email,
        'to_name', v_admin.nome,
        'subject', v_assunto,
        'html', v_html,
        'type', 'transacional',
        'ref_type', 'reporte_erro',
        'ref_id', new.id
      ),
      timeout_milliseconds := 30000
    );
  end loop;

  return new;
end $function$
;

