CREATE OR REPLACE FUNCTION public.uazapi_token_do_numero(p_instance_id text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT x.token FROM (
    SELECT ds.decrypted_secret AS token, 1 AS ordem
      FROM public.whatsapp_instances wi
      JOIN public.whatsapp_instance_tokens t ON t.instance_uuid = wi.id AND t.tenant_id = wi.tenant_id
      JOIN vault.decrypted_secrets ds ON ds.id = t.secret_key_id
     WHERE wi.instance_id = p_instance_id
       AND (p_tenant_id IS NULL OR wi.tenant_id = p_tenant_id)
    UNION ALL
    SELECT ds.decrypted_secret, 2
      FROM public.cobranca_instances ci
      JOIN public.cobranca_instance_tokens t ON t.instance_uuid = ci.id AND t.tenant_id = ci.tenant_id
      JOIN vault.decrypted_secrets ds ON ds.id = t.secret_key_id
     WHERE ci.instance_id = p_instance_id
       AND (p_tenant_id IS NULL OR ci.tenant_id = p_tenant_id)
  ) x
  ORDER BY x.ordem
  LIMIT 1;
$function$
;

CREATE OR REPLACE FUNCTION public.update_aguardando_resposta()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tipo TEXT := NEW.autor_tipo;
BEGIN
  IF v_tipo IS NULL THEN
    -- Regra antiga (mensagem gravada sem autor): só as flags.
    v_tipo := CASE WHEN (NEW.enviado_por_agente = false AND NEW.enviado_por_ia = false) IS TRUE
                   THEN 'cliente' ELSE 'equipe' END;
  END IF;

  IF v_tipo IN ('cliente', 'desconhecido') THEN
    -- Cliente (ou remetente que não deu para identificar) → aguardando resposta.
    UPDATE chat_conversations
       SET aguardando_resposta = true,
           ultima_msg_cliente_em = NEW.criado_em
     WHERE id = NEW.conversation_id;
  ELSIF v_tipo IN ('equipe', 'ia') AND coalesce(NEW.autor_origem, '') NOT LIKE 'heuristica%' THEN
    -- Equipe (telefone/LID conhecido, fromMe, plataforma) ou IA → respondido.
    -- Reconhecida só pelo NOME (heuristica_*): não acende nem apaga.
    UPDATE chat_conversations
       SET aguardando_resposta = false
     WHERE id = NEW.conversation_id;
  END IF;
  -- 'sistema' e equipe por heurística de nome: não mexe.
  RETURN NEW;
END;
$function$
;

