CREATE OR REPLACE FUNCTION public.user_can_access_client(p_client_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN p_client_id IS NULL THEN true
    WHEN (SELECT perfil FROM public.users WHERE id = auth.uid())
      IN ('admin','gerente','agente_chat','atendimento','admin_cobranca','agente_cobranca') THEN true
    WHEN (SELECT perfil FROM public.users WHERE id = auth.uid()) = 'estrategista' THEN EXISTS (
      SELECT 1 FROM public.client_assignments ca
       WHERE ca.user_id = auth.uid() AND ca.client_id = p_client_id
         AND ca.tenant_id = public.get_user_tenant_id() AND ca.ativo IS TRUE
    )
    ELSE false
  END
$function$
;

CREATE OR REPLACE FUNCTION public.user_can_access_instance(p_instance_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN (SELECT perfil FROM public.users WHERE id = auth.uid())
         IN ('admin', 'gerente')
    THEN true
    ELSE EXISTS (
      SELECT 1 FROM public.user_instance_assignments uia
      WHERE uia.user_id = auth.uid()
        AND uia.instance_id = p_instance_id
    )
  END
$function$
;

CREATE OR REPLACE FUNCTION public.validar_vigencia_contrato()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP='INSERT' OR NEW.vigencia_fim IS DISTINCT FROM OLD.vigencia_fim THEN
    IF NEW.vigencia_fim IS NOT NULL THEN
      IF char_length(btrim(coalesce(NEW.vigencia_motivo,''))) NOT BETWEEN 8 AND 2000 THEN
        RAISE EXCEPTION 'Informe um motivo entre 8 e 2000 caracteres para a vigência.' USING ERRCODE='22023';
      END IF;
    END IF;
    -- Operações administrativas de reparo sem sessão são separadas e auditadas.
    -- Escritas humanas, inclusive update direto/reversão do histórico, não encurtam nem retrodatam.
    IF auth.uid() IS NOT NULL AND (TG_OP='UPDATE' OR NEW.vigencia_fim IS NOT NULL) THEN
      IF NEW.vigencia_fim IS NULL OR NEW.vigencia_fim < (now() AT TIME ZONE 'America/Sao_Paulo')::date
        OR (TG_OP='UPDATE' AND OLD.vigencia_fim IS NOT NULL AND NEW.vigencia_fim<=OLD.vigencia_fim) THEN
        RAISE EXCEPTION 'A nova vigência deve ser futura e posterior ao prazo confirmado.' USING ERRCODE='22023';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.vinculos_buscar_clientes(p_texto text, p_limite integer DEFAULT 20)
 RETURNS TABLE(id uuid, nome text, empresa text, ativo boolean, vigente boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
#variable_conflict use_column
DECLARE
  v_tenant UUID := public.get_user_tenant_id();
  v_txt    TEXT := btrim(COALESCE(p_texto, ''));
  v_padrao TEXT;
BEGIN
  IF v_tenant IS NULL OR NOT public.vinculos_pode_gerir() THEN
    RAISE EXCEPTION 'Sem permissão para buscar clientes.' USING ERRCODE = '42501';
  END IF;
  IF length(v_txt) < 2 OR length(v_txt) > 80 THEN
    RETURN;
  END IF;
  v_padrao := '%' || replace(replace(replace(
                lower(extensions.unaccent('extensions.unaccent'::regdictionary, v_txt)),
                '\', '\\'), '%', '\%'), '_', '\_') || '%';
  RETURN QUERY
    SELECT cl.id, left(cl.nome, 120), left(cl.empresa, 120), (cl.ativo IS DISTINCT FROM false),
           EXISTS (
             SELECT 1 FROM public.contratos co
              WHERE co.tenant_id = v_tenant AND co.cliente_id = cl.id
                AND lower(extensions.unaccent('extensions.unaccent'::regdictionary, btrim(COALESCE(co.status, ''))))
                    NOT IN ('cancelado', 'concluido', 'encerrado', 'distrato', 'finalizado', 'rescindido')
           )
      FROM public.clients cl
     WHERE cl.tenant_id = v_tenant
       AND (
         lower(extensions.unaccent('extensions.unaccent'::regdictionary, COALESCE(cl.nome, ''))) LIKE v_padrao
         OR lower(extensions.unaccent('extensions.unaccent'::regdictionary, COALESCE(cl.empresa, ''))) LIKE v_padrao
         OR lower(extensions.unaccent('extensions.unaccent'::regdictionary, COALESCE(cl.razao_social, ''))) LIKE v_padrao
       )
     ORDER BY (cl.ativo IS DISTINCT FROM false) DESC, cl.nome
     LIMIT LEAST(GREATEST(COALESCE(p_limite, 20), 1), 50);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.vinculos_decidir(p_contato_id uuid, p_acao text, p_client_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_tenant UUID := public.get_user_tenant_id();
  v_ct     RECORD;
  v_tipo   TEXT;
  v_chave  TEXT;
  v_restr  BOOLEAN;
BEGIN
  IF v_tenant IS NULL OR NOT public.vinculos_pode_gerir() THEN
    RAISE EXCEPTION 'Sem permissão para decidir vínculos de conversas.' USING ERRCODE = '42501';
  END IF;
  IF p_acao IS NULL OR p_acao NOT IN ('aceitar', 'trocar', 'adicionar', 'rejeitar', 'interno', 'nao_cliente', 'reabrir') THEN
    RAISE EXCEPTION 'Ação inválida.' USING ERRCODE = '22023';
  END IF;

  SELECT ct.numero_whatsapp, ct.group_size INTO v_ct
    FROM public.chat_contacts ct
   WHERE ct.id = p_contato_id AND ct.tenant_id = v_tenant;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Conversa não encontrada nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;
  v_tipo := private.canal_tipo(v_ct.numero_whatsapp, v_ct.group_size);
  v_chave := private.canal_chave(v_ct.numero_whatsapp, v_ct.group_size);
  IF v_chave IS NULL THEN
    RAISE EXCEPTION 'Esta conversa não tem um número ou grupo reconhecido.' USING ERRCODE = 'check_violation';
  END IF;

  v_restr := EXISTS (
    SELECT 1 FROM public.chat_contacts ct
     WHERE ct.tenant_id = v_tenant AND ct.restrito_admin
       AND ct.numero_whatsapp = ANY (private.canal_formas(v_tipo, v_chave))
  );
  IF v_restr AND p_acao IN ('aceitar', 'trocar', 'adicionar', 'reabrir') THEN
    RAISE EXCEPTION 'Este é um grupo interno (relatório diário ou assistente) e não pode ser ligado a cliente.'
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_acao IN ('aceitar', 'trocar', 'adicionar', 'rejeitar') THEN
    IF p_client_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.clients cl WHERE cl.id = p_client_id AND cl.tenant_id = v_tenant
    ) THEN
      RAISE EXCEPTION 'Cliente não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  -- Uma decisão por canal de cada vez.
  PERFORM pg_advisory_xact_lock(hashtext('cliente_canais:' || v_tenant::text || ':' || v_tipo || ':' || v_chave));

  IF p_acao IN ('aceitar', 'trocar', 'adicionar') THEN
    DELETE FROM public.cliente_canais c
     WHERE c.tenant_id = v_tenant AND c.tipo = v_tipo AND c.chave = v_chave AND c.client_id IS NULL;
    IF p_acao IN ('aceitar', 'trocar') THEN
      UPDATE public.cliente_canais c
         SET status = 'rejeitado', revisado_por = auth.uid(), revisado_em = now()
       WHERE c.tenant_id = v_tenant AND c.tipo = v_tipo AND c.chave = v_chave
         AND c.client_id IS NOT NULL AND c.client_id <> p_client_id
         AND (c.status = 'sugerido' OR (p_acao = 'trocar' AND c.status = 'confirmado'));
    END IF;
    INSERT INTO public.cliente_canais
      (tenant_id, client_id, tipo, chave, status, origem, revisado_por, revisado_em)
    VALUES (v_tenant, p_client_id, v_tipo, v_chave, 'confirmado', 'manual', auth.uid(), now())
    ON CONFLICT (tenant_id, tipo, chave, (COALESCE(client_id, '00000000-0000-0000-0000-000000000000'::uuid)))
    DO UPDATE SET status = 'confirmado', revisado_por = EXCLUDED.revisado_por, revisado_em = EXCLUDED.revisado_em;

  ELSIF p_acao = 'rejeitar' THEN
    INSERT INTO public.cliente_canais
      (tenant_id, client_id, tipo, chave, status, origem, revisado_por, revisado_em)
    VALUES (v_tenant, p_client_id, v_tipo, v_chave, 'rejeitado', 'manual', auth.uid(), now())
    ON CONFLICT (tenant_id, tipo, chave, (COALESCE(client_id, '00000000-0000-0000-0000-000000000000'::uuid)))
    DO UPDATE SET status = 'rejeitado', revisado_por = EXCLUDED.revisado_por, revisado_em = EXCLUDED.revisado_em;

  ELSIF p_acao IN ('interno', 'nao_cliente') THEN
    UPDATE public.cliente_canais c
       SET status = 'rejeitado', revisado_por = auth.uid(), revisado_em = now()
     WHERE c.tenant_id = v_tenant AND c.tipo = v_tipo AND c.chave = v_chave
       AND c.client_id IS NOT NULL AND c.status IN ('confirmado', 'sugerido');
    INSERT INTO public.cliente_canais
      (tenant_id, client_id, tipo, chave, status, origem, revisado_por, revisado_em)
    VALUES (v_tenant, NULL, v_tipo, v_chave, p_acao, 'manual', auth.uid(), now())
    ON CONFLICT (tenant_id, tipo, chave, (COALESCE(client_id, '00000000-0000-0000-0000-000000000000'::uuid)))
    DO UPDATE SET status = EXCLUDED.status, origem = 'manual',
                  revisado_por = EXCLUDED.revisado_por, revisado_em = EXCLUDED.revisado_em;

  ELSE -- reabrir
    DELETE FROM public.cliente_canais c
     WHERE c.tenant_id = v_tenant AND c.tipo = v_tipo AND c.chave = v_chave AND c.client_id IS NULL;
  END IF;

  RETURN jsonb_build_object('ok', true, 'tipo', v_tipo);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.vinculos_gravar_sugestoes(p_tenant uuid, p_itens jsonb, p_chaves text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  r          RECORD;
  v_status   TEXT;
  v_ids      UUID[];
  v_gravados INTEGER := 0;
  v_conf     INTEGER := 0;
  v_ignor    INTEGER := 0;
  v_remov    INTEGER := 0;
  v_n        INTEGER;
BEGIN
  IF p_tenant IS NULL OR NOT EXISTS (SELECT 1 FROM public.tenants t WHERE t.id = p_tenant) THEN
    RAISE EXCEPTION 'Empresa não encontrada.' USING ERRCODE = 'check_violation';
  END IF;
  IF p_itens IS NULL OR jsonb_typeof(p_itens) <> 'array' OR jsonb_array_length(p_itens) > 5000 THEN
    RAISE EXCEPTION 'Lista de sugestões inválida.' USING ERRCODE = '22023';
  END IF;
  IF p_chaves IS NOT NULL AND cardinality(p_chaves) > 20000 THEN
    RAISE EXCEPTION 'Lista de canais grande demais.' USING ERRCODE = '22023';
  END IF;

  FOR r IN
    SELECT x.tipo, x.chave, x.client_id, x.status, x.origem, x.score, x.evidencias
      FROM jsonb_to_recordset(p_itens) AS x(tipo text, chave text, client_id uuid, status text,
                                            origem text, score numeric, evidencias jsonb)
  LOOP
    IF r.tipo NOT IN ('grupo', 'privado') OR r.chave IS NULL OR r.client_id IS NULL
       OR r.status NOT IN ('sugerido', 'confirmado')
       OR r.origem NOT IN ('legado', 'mesmo_jid', 'telefone', 'nome_grupo', 'nome_membro')
       OR private.canal_tipo(r.chave, CASE WHEN r.tipo = 'grupo' THEN 1 END) IS DISTINCT FROM r.tipo
       OR private.canal_chave(r.chave, CASE WHEN r.tipo = 'grupo' THEN 1 END) IS DISTINCT FROM r.chave
       OR NOT EXISTS (SELECT 1 FROM public.clients cl WHERE cl.id = r.client_id AND cl.tenant_id = p_tenant)
       OR EXISTS (
         SELECT 1 FROM public.cliente_canais c
          WHERE c.tenant_id = p_tenant AND c.tipo = r.tipo AND c.chave = r.chave
            AND c.client_id IS NULL AND c.status IN ('interno', 'nao_cliente'))
       OR EXISTS (
         SELECT 1 FROM public.chat_contacts ct
          WHERE ct.tenant_id = p_tenant AND ct.restrito_admin
            AND ct.numero_whatsapp = ANY (private.canal_formas(r.tipo, r.chave)))
    THEN
      v_ignor := v_ignor + 1;
      CONTINUE;
    END IF;

    v_status := r.status;
    IF v_status = 'confirmado' THEN
      IF r.origem = 'telefone' THEN
        v_ids := ARRAY(
          SELECT u FROM unnest(private.clientes_por_telefone(p_tenant, private.tel_cmp_contato(r.chave))) AS u
          EXCEPT
          SELECT c.client_id FROM public.cliente_canais c
           WHERE c.tenant_id = p_tenant AND c.tipo = r.tipo AND c.chave = r.chave AND c.status = 'rejeitado'
        );
        IF r.tipo <> 'privado' OR v_ids IS DISTINCT FROM ARRAY[r.client_id] THEN
          v_status := 'sugerido';
        END IF;
      ELSIF r.origem IN ('legado', 'mesmo_jid') THEN
        IF NOT EXISTS (
          SELECT 1 FROM public.chat_contacts ct
           WHERE ct.tenant_id = p_tenant
             AND ct.numero_whatsapp = ANY (private.canal_formas(r.tipo, r.chave))
             AND (ct.client_id = r.client_id OR EXISTS (
                   SELECT 1 FROM public.chat_contact_clients cc
                    WHERE cc.tenant_id = p_tenant AND cc.contact_id = ct.id AND cc.client_id = r.client_id))
        ) THEN
          v_ignor := v_ignor + 1;
          CONTINUE;
        END IF;
      ELSE
        v_status := 'sugerido'; -- nome nunca confirma sozinho
      END IF;
    END IF;

    INSERT INTO public.cliente_canais
      (tenant_id, client_id, tipo, chave, status, origem, score, evidencias)
    VALUES (
      p_tenant, r.client_id, r.tipo, r.chave, v_status, r.origem,
      CASE WHEN r.score IS NULL THEN NULL ELSE round(LEAST(GREATEST(r.score, 0), 1), 2) END,
      private.vinculo_evidencias_limpas(r.evidencias)
    )
    ON CONFLICT (tenant_id, tipo, chave, (COALESCE(client_id, '00000000-0000-0000-0000-000000000000'::uuid)))
    DO UPDATE SET status = EXCLUDED.status, origem = EXCLUDED.origem,
                  score = EXCLUDED.score, evidencias = EXCLUDED.evidencias
            WHERE public.cliente_canais.status = 'sugerido'
              AND public.cliente_canais.origem <> 'manual' -- pedido feito no Chat fica como está
              AND (public.cliente_canais.status, public.cliente_canais.origem, public.cliente_canais.score, public.cliente_canais.evidencias)
                  IS DISTINCT FROM (EXCLUDED.status, EXCLUDED.origem, EXCLUDED.score, EXCLUDED.evidencias);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n > 0 THEN
      v_gravados := v_gravados + 1;
      IF v_status = 'confirmado' THEN
        v_conf := v_conf + 1;
      END IF;
    END IF;
  END LOOP;

  IF p_chaves IS NOT NULL THEN
    DELETE FROM public.cliente_canais c
     WHERE c.tenant_id = p_tenant
       AND c.status = 'sugerido'
       AND c.origem <> 'manual'
       AND (c.tipo || ':' || c.chave) = ANY (p_chaves)
       AND NOT EXISTS (
         SELECT 1 FROM jsonb_to_recordset(p_itens) AS x(tipo text, chave text, client_id uuid)
          WHERE x.tipo = c.tipo AND x.chave = c.chave AND x.client_id = c.client_id);
    GET DIAGNOSTICS v_remov = ROW_COUNT;
  END IF;

  RETURN jsonb_build_object('gravados', v_gravados, 'confirmados', v_conf, 'ignorados', v_ignor, 'removidos', v_remov);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.vinculos_listar(p_dias integer DEFAULT 30, p_filtro text DEFAULT 'ativos'::text, p_tipo text DEFAULT NULL::text, p_limite integer DEFAULT 300)
 RETURNS TABLE(contato_id uuid, tipo text, nome text, final_telefone text, msgs_30d integer, ultima_msg_em timestamp with time zone, instancias integer, instancias_nomes text[], ocultar_grupos boolean, instancias_ocultas text[], restrito boolean, decisao text, clientes jsonb, sugestoes jsonb, rejeitados integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_tenant UUID := public.get_user_tenant_id();
  v_filtro TEXT := COALESCE(p_filtro, 'ativos');
  v_dias   INTEGER;
  v_lim    INTEGER := LEAST(GREATEST(COALESCE(p_limite, 300), 1), 500);
  v_janela TIMESTAMPTZ;
BEGIN
  IF v_tenant IS NULL OR NOT public.vinculos_pode_gerir() THEN
    RAISE EXCEPTION 'Sem permissão para ver os vínculos de conversas.' USING ERRCODE = '42501';
  END IF;
  IF v_filtro NOT IN ('ativos', 'pendentes', 'todos') THEN
    RAISE EXCEPTION 'Filtro inválido.' USING ERRCODE = '22023';
  END IF;
  IF p_tipo IS NOT NULL AND p_tipo NOT IN ('grupo', 'privado') THEN
    RAISE EXCEPTION 'Tipo inválido.' USING ERRCODE = '22023';
  END IF;
  v_dias := CASE v_filtro
              WHEN 'todos' THEN NULL
              ELSE LEAST(GREATEST(COALESCE(p_dias, 30), 1), 365)
            END;
  -- Mensagens lidas: a janela do filtro (mínimo 30 dias, para a contagem).
  v_janela := now() - make_interval(days => GREATEST(COALESCE(v_dias, 30), 30));

  RETURN QUERY
  WITH ct AS (
    SELECT c.id, c.instance_id, c.nome AS c_nome, c.restrito_admin, c.atualizado_em,
           private.canal_tipo(c.numero_whatsapp, c.group_size) AS tp,
           private.canal_chave(c.numero_whatsapp, c.group_size) AS ch
      FROM public.chat_contacts c
     WHERE c.tenant_id = v_tenant
  ),
  ctk AS (
    SELECT * FROM ct WHERE ct.tp IS NOT NULL AND ct.ch IS NOT NULL AND (p_tipo IS NULL OR ct.tp = p_tipo)
  ),
  conv AS (
    -- Última mensagem do cliente (atualizado_em muda por outros motivos).
    SELECT cv.contact_id, max(cv.ultima_msg_cliente_em) AS ult_conv
      FROM public.chat_conversations cv
     WHERE cv.tenant_id = v_tenant
     GROUP BY cv.contact_id
  ),
  msg AS (
    SELECT cv.contact_id,
           (count(*) FILTER (WHERE m.criado_em >= now() - interval '30 days'))::int AS n30,
           max(m.criado_em) AS ult
      FROM public.chat_messages m
      JOIN public.chat_conversations cv ON cv.id = m.conversation_id AND cv.tenant_id = v_tenant
     WHERE m.tenant_id = v_tenant
       AND m.criado_em >= v_janela
       AND COALESCE(m.tipo, '') <> 'nota_interna'
     GROUP BY cv.contact_id
  ),
  pk AS (
    SELECT k.tp, k.ch,
           (array_agg(k.id ORDER BY COALESCE(msg.ult, conv.ult_conv, k.atualizado_em) DESC NULLS LAST))[1] AS rep,
           (array_agg(NULLIF(btrim(k.c_nome), '')
              ORDER BY (NULLIF(btrim(k.c_nome), '') IS NULL), COALESCE(msg.ult, conv.ult_conv, k.atualizado_em) DESC NULLS LAST))[1] AS p_nome,
           COALESCE(sum(msg.n30), 0)::int AS n30,
           max(COALESCE(msg.ult, conv.ult_conv)) AS ult,
           count(DISTINCT k.instance_id)::int AS ninst,
           array_agg(DISTINCT wi.nome) FILTER (WHERE wi.nome IS NOT NULL) AS nomes_inst,
           bool_or(COALESCE(wi.ocultar_grupos, false)) AS ocultar,
           array_agg(DISTINCT wi.nome) FILTER (WHERE wi.ocultar_grupos AND wi.nome IS NOT NULL) AS nomes_ocultos,
           bool_or(k.restrito_admin) AS restr
      FROM ctk k
      LEFT JOIN msg ON msg.contact_id = k.id
      LEFT JOIN conv ON conv.contact_id = k.id
      LEFT JOIN public.whatsapp_instances wi ON wi.id = k.instance_id AND wi.tenant_id = v_tenant
     GROUP BY k.tp, k.ch
  ),
  cc AS (
    SELECT c.* FROM public.cliente_canais c WHERE c.tenant_id = v_tenant
  ),
  dec AS (
    SELECT pk.tp, pk.ch,
           (SELECT x.status FROM cc x WHERE x.tipo = pk.tp AND x.chave = pk.ch AND x.client_id IS NULL LIMIT 1) AS neg,
           EXISTS (SELECT 1 FROM cc x WHERE x.tipo = pk.tp AND x.chave = pk.ch AND x.status = 'confirmado') AS conf
      FROM pk
  )
  SELECT pk.rep,
         pk.tp,
         left(COALESCE(pk.p_nome, CASE WHEN pk.tp = 'grupo' THEN 'Grupo sem nome' ELSE 'Contato sem nome' END), 120),
         CASE WHEN pk.tp = 'privado' THEN right(pk.ch, 4) END,
         pk.n30,
         pk.ult,
         pk.ninst,
         COALESCE(pk.nomes_inst, '{}'::text[]),
         (pk.tp = 'grupo' AND pk.ocultar),
         CASE WHEN pk.tp = 'grupo' THEN COALESCE(pk.nomes_ocultos, '{}'::text[]) ELSE '{}'::text[] END,
         pk.restr,
         COALESCE(dec.neg, CASE WHEN dec.conf THEN 'confirmado' END),
         COALESCE((
           SELECT jsonb_agg(jsonb_build_object(
                    'id', cl.id, 'nome', left(cl.nome, 120), 'origem', x.origem,
                    'revisado', x.revisado_por IS NOT NULL)
                  ORDER BY COALESCE(x.revisado_em, x.criado_em))
             FROM cc x JOIN public.clients cl ON cl.id = x.client_id AND cl.tenant_id = v_tenant
            WHERE x.tipo = pk.tp AND x.chave = pk.ch AND x.status = 'confirmado'
         ), '[]'::jsonb),
         COALESCE((
           SELECT jsonb_agg(jsonb_build_object(
                    'id', cl.id, 'nome', left(cl.nome, 120), 'origem', x.origem,
                    'score', x.score, 'evidencias', x.evidencias)
                  ORDER BY x.score DESC NULLS LAST, cl.nome)
             FROM cc x JOIN public.clients cl ON cl.id = x.client_id AND cl.tenant_id = v_tenant
            WHERE x.tipo = pk.tp AND x.chave = pk.ch AND x.status = 'sugerido'
         ), '[]'::jsonb),
         (SELECT count(*)::int FROM cc x WHERE x.tipo = pk.tp AND x.chave = pk.ch AND x.status = 'rejeitado')
    FROM pk
    JOIN dec ON dec.tp = pk.tp AND dec.ch = pk.ch
   WHERE (v_dias IS NULL OR pk.ult >= now() - make_interval(days => v_dias))
     AND (v_filtro <> 'pendentes' OR (NOT pk.restr AND dec.neg IS NULL AND NOT dec.conf))
   ORDER BY (pk.tp = 'grupo') DESC, pk.n30 DESC, pk.ult DESC NULLS LAST
   LIMIT v_lim;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.vinculos_pode_gerir()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(public.pode_ver_restrito(), false)
     AND COALESCE(public.has_permissao('automacoes-wa', 'admin'), false)
$function$
;

CREATE OR REPLACE FUNCTION public.vinculos_reservar_execucao(p_tenant uuid, p_user uuid, p_intervalo_s integer DEFAULT 60)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_id UUID;
BEGIN
  IF p_tenant IS NULL THEN
    RETURN NULL;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('vinculos_execucoes:' || p_tenant::text));
  IF EXISTS (
    SELECT 1 FROM public.vinculos_execucoes e
     WHERE e.tenant_id = p_tenant AND e.origem = 'manual'
       AND e.criado_em > now() - make_interval(secs => LEAST(GREATEST(COALESCE(p_intervalo_s, 60), 10), 3600))
  ) THEN
    RETURN NULL;
  END IF;
  INSERT INTO public.vinculos_execucoes (tenant_id, origem, user_id, resultado)
  VALUES (p_tenant, 'manual', p_user, '{"em_andamento":1}'::jsonb)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_agente_acoes_capacidades()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ SELECT jsonb_build_object('versao',2,'cliente_estrategista',true) $function$
;

CREATE OR REPLACE FUNCTION public.wa_agente_acoes_confirmar(p_pedido uuid, p_codigo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET lock_timeout TO '3s'
 SET statement_timeout TO '8s'
AS $function$
DECLARE
  p public.wa_agente_pedidos%ROWTYPE;
  v public.wa_agente_acoes_propostas%ROWTYPE;
  v_estado jsonb;
  v_texto text;
  v_match text[];
  v_mensagem_em timestamptz;
  v_recibo jsonb;
  v_linhas integer;
  v_total boolean;
  v_ids uuid[];
  v_cliente uuid;
  v_itens jsonb; v_item jsonb; v_operacoes jsonb := '[]'; v_operacao jsonb;
BEGIN
  p := private.wa_agente_acoes_pedido(p_pedido, false);
  -- Confirmação mantém mensagem nova, sozinha e sem citação. O helper acima
  -- aceita resposta citada apenas para ler intenção própria/preparar proposta.
  IF p.gatilho NOT IN ('nome', 'mencao') OR EXISTS (
    SELECT 1 FROM public.chat_messages WHERE id = p.chat_message_id
      AND tenant_id = p.tenant_id AND reply_to_id IS NOT NULL
  ) THEN
    RETURN jsonb_build_object('ok', false, 'codigo', 'confirmacao_invalida',
      'erro', 'Envie a confirmação sozinha em uma nova mensagem sem citação.');
  END IF;
  IF p_codigo IS NULL OR p_codigo !~ '^[0-9A-F]{8}$' THEN
    RETURN jsonb_build_object('ok', false, 'codigo', 'confirmacao_invalida', 'erro', 'Use o código exato da proposta.');
  END IF;
  SELECT conteudo, criado_em INTO v_texto, v_mensagem_em FROM public.chat_messages
    WHERE id = p.chat_message_id AND tenant_id = p.tenant_id;
  IF p.eh_grupo THEN v_texto := regexp_replace(v_texto, '^\[[^\]\r\n]{1,100}\] ', ''); END IF;
  v_match := regexp_match(v_texto, '^(?:[ÍI]ris, )?CONFIRMAR ([0-9A-F]{8})$', 'i');
  -- PostgreSQL regex padrão inclui todo o texto; CR/LF são sempre recusados.
  IF v_match IS NULL OR v_texto ~ '[\r\n]' OR upper(v_match[1]) IS DISTINCT FROM p_codigo THEN
    RETURN jsonb_build_object('ok', false, 'codigo', 'confirmacao_invalida', 'erro', 'Envie somente Íris, confirmar e o código, em nova mensagem direta.');
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('wa-acoes:' || p.tenant_id || ':' || p.user_id || ':' || p.chat_jid, 0));
  SELECT * INTO v FROM public.wa_agente_acoes_propostas
    WHERE tenant_id = p.tenant_id AND user_id = p.user_id AND membro_id = p.membro_id
      AND instance_uuid = p.instance_uuid AND chat_jid = p.chat_jid AND eh_grupo = p.eh_grupo
      AND remetente_chave = p.remetente_chave AND codigo = p_codigo FOR UPDATE;
  IF NOT FOUND OR v.pedido_origem_id = p.id OR v.mensagem_origem_id = p.chat_message_id
      OR p.created_at <= v.origem_criada_em OR p.created_at <= v.criada_em OR v_mensagem_em <= v.criada_em THEN
    RETURN jsonb_build_object('ok', false, 'codigo', 'proposta_indisponivel', 'erro', 'Proposta não encontrada para esta nova mensagem e este chat.');
  END IF;
  -- Revalida a permissão da ação inclusive ao devolver um recibo idempotente.
  IF NOT coalesce(public.has_permissao_de(p.user_id, CASE v.acao WHEN 'cliente_ativo' THEN 'clientes' WHEN 'cliente_estrategista' THEN 'clientes.atribuir' ELSE 'contratos' END, 'editar'), false) THEN
    RAISE EXCEPTION 'Sem permissão atual para esta operação.' USING ERRCODE = '42501';
  END IF;
  SELECT total, client_ids INTO v_total, v_ids FROM public.wa_agente_escopo(p.tenant_id, p.user_id);
  IF v.acao='cliente_estrategista' THEN
    v_itens:=private.wa_agente_atribuicoes_itens(v.alvo,v.novo);
    IF v_total IS NOT TRUE AND EXISTS (SELECT 1 FROM jsonb_array_elements(v_itens)
      WHERE NOT ((value->>'cliente_id')::uuid=ANY(coalesce(v_ids,'{}'::uuid[])))) THEN
      RAISE EXCEPTION 'Registro fora da carteira autorizada.' USING ERRCODE='42501';
    END IF;
  ELSE
    v_cliente := CASE v.acao WHEN 'cliente_ativo' THEN v.alvo ELSE (v.novo ->> 'cliente_id')::uuid END;
    IF v_total IS NOT TRUE AND (NOT (v_cliente = ANY(coalesce(v_ids, '{}'::uuid[])))
      OR (v.acao = 'vincular_contrato_cliente' AND NOT EXISTS (
        SELECT 1 FROM public.contratos WHERE id = v.alvo AND tenant_id = p.tenant_id AND estrategista_id = p.user_id
      ))) THEN RAISE EXCEPTION 'Registro fora da carteira autorizada.' USING ERRCODE = '42501'; END IF;
  END IF;
  IF v.estado = 'executada' THEN
    IF v.pedido_confirmacao_id = p.id THEN RETURN jsonb_build_object('ok', true, 'repetida', true, 'recibo', v.recibo); END IF;
    RETURN jsonb_build_object('ok', false, 'codigo', 'proposta_concluida', 'erro', 'Esta proposta já foi concluída por outra mensagem.');
  END IF;
  p := private.wa_agente_acoes_pedido(p_pedido, true);
  IF v.expira_em <= clock_timestamp() THEN
    UPDATE public.wa_agente_acoes_propostas SET estado = 'expirada' WHERE id = v.id;
    RETURN jsonb_build_object('ok', false, 'codigo', 'proposta_expirada', 'erro', 'Código expirado. Solicite nova proposta.');
  END IF;
  IF v.estado <> 'pendente' THEN
    RETURN jsonb_build_object('ok', false, 'codigo', 'proposta_indisponivel', 'erro', 'Solicite nova proposta.');
  END IF;
  v_estado := private.wa_agente_acoes_estado(p, v.acao, v.alvo, v.novo);
  IF v_estado -> 'esperado' IS DISTINCT FROM v.esperado THEN
    UPDATE public.wa_agente_acoes_propostas SET estado = 'obsoleta' WHERE id = v.id;
    RETURN jsonb_build_object('ok', false, 'codigo', 'estado_alterado', 'erro', 'O registro mudou. Solicite nova proposta.');
  END IF;
  -- Reconfere prazo/lease após adquirir os locks de negócio.
  IF v.expira_em <= clock_timestamp() OR p.lock_ate <= clock_timestamp() THEN
    RETURN jsonb_build_object('ok', false, 'codigo', 'prazo_encerrado', 'erro', 'Prazo encerrado. Solicite nova proposta.');
  END IF;
  IF v.acao='cliente_estrategista' THEN
    IF EXISTS (SELECT 1 FROM private.client_assignment_iris_context
      WHERE backend_pid=pg_backend_pid() AND transacao=txid_current()) THEN
      RAISE EXCEPTION 'Contexto de confirmação já em uso.' USING ERRCODE='42501';
    END IF;
    BEGIN
      FOR v_item IN SELECT value FROM jsonb_array_elements(v_itens) ORDER BY (value->>'cliente_id')::uuid LOOP
        INSERT INTO private.client_assignment_iris_context(backend_pid,transacao,proposta_id,pedido_id,client_id)
          VALUES(pg_backend_pid(),txid_current(),v.id,p.id,(v_item->>'cliente_id')::uuid);
        v_operacao:=public.client_assignment_decidir((v_item->>'cliente_id')::uuid,
          CASE WHEN v_item->>'assignment_id' IS NULL THEN 'adicionar' ELSE 'trocar' END,
          'estrategista',(v_item->>'assignment_id')::uuid,(v_item->>'user_id')::uuid,
          (v_item->>'expected_revision')::bigint,v.id,'Confirmação explícita de responsáveis pela Íris no WhatsApp.');
        v_operacoes:=v_operacoes||jsonb_build_array(jsonb_build_object('cliente_id',v_item->'cliente_id','resultado',v_operacao));
        DELETE FROM private.client_assignment_iris_context WHERE backend_pid=pg_backend_pid() AND transacao=txid_current();
      END LOOP;
    EXCEPTION WHEN OTHERS THEN
      -- O bloco desfaz o lote inteiro; nenhum contexto vaza ao próximo comando.
      DELETE FROM private.client_assignment_iris_context WHERE backend_pid=pg_backend_pid() AND transacao=txid_current();
      RAISE;
    END;
    v_linhas:=1;
  ELSIF v.acao = 'cliente_ativo' THEN
    UPDATE public.clients SET ativo = (v.novo ->> 'ativo')::boolean
      WHERE id = v.alvo AND tenant_id = p.tenant_id
        AND atualizado_em = (v.esperado ->> 'atualizado_em')::timestamptz
        AND ativo IS NOT DISTINCT FROM (v.esperado ->> 'ativo')::boolean;
    GET DIAGNOSTICS v_linhas = ROW_COUNT;
  ELSE
    -- Exclusivamente a FK. Não reescreve snapshot, status, financeiro ou formulário.
    UPDATE public.contratos SET cliente_id = (v.novo ->> 'cliente_id')::uuid
      WHERE id = v.alvo AND tenant_id = p.tenant_id AND cliente_id IS NULL
        AND atualizado_em = (v.esperado ->> 'atualizado_em')::timestamptz;
    GET DIAGNOSTICS v_linhas = ROW_COUNT;
  END IF;
  IF v_linhas <> 1 THEN RAISE EXCEPTION 'O registro mudou; nenhuma ação confirmada.' USING ERRCODE = '40001'; END IF;
  IF v.expira_em <= clock_timestamp() OR p.lock_ate <= clock_timestamp() THEN
    RAISE EXCEPTION 'Processamento expirado; nenhuma ação confirmada.' USING ERRCODE = '42501';
  END IF;
  v_recibo := jsonb_build_object('proposta_id', v.id, 'pedido_confirmacao_id', p.id,
    'executada_em', clock_timestamp(), 'estado', 'executada', 'previa', v.previa);
  IF v.acao='cliente_estrategista' THEN v_recibo:=v_recibo||jsonb_build_object('operacoes',v_operacoes); END IF;
  UPDATE public.wa_agente_acoes_propostas SET estado = 'executada', pedido_confirmacao_id = p.id, recibo = v_recibo WHERE id = v.id;
  RETURN jsonb_build_object('ok', true, 'repetida', false, 'recibo', v_recibo);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_agente_acoes_propor(p_pedido uuid, p_acao text, p_alvo uuid, p_novo jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET lock_timeout TO '3s'
 SET statement_timeout TO '8s'
AS $function$
DECLARE
  p public.wa_agente_pedidos%ROWTYPE;
  v public.wa_agente_acoes_propostas%ROWTYPE;
  v_estado jsonb;
  v_agora timestamptz;
BEGIN
  p := private.wa_agente_acoes_pedido(p_pedido, true);
  -- Uma proposta por mensagem; repetir com outro payload nunca muda a proposta.
  PERFORM pg_advisory_xact_lock(hashtextextended('wa-acoes:' || p.tenant_id || ':' || p.user_id || ':' || p.chat_jid, 0));
  SELECT * INTO v FROM public.wa_agente_acoes_propostas WHERE pedido_origem_id = p.id FOR UPDATE;
  IF FOUND THEN
    IF v.acao IS DISTINCT FROM p_acao OR v.alvo IS DISTINCT FROM p_alvo OR v.novo IS DISTINCT FROM p_novo THEN
      RETURN jsonb_build_object('ok', false, 'codigo', 'pedido_reutilizado', 'erro', 'Este pedido já possui outra proposta.');
    END IF;
    IF v.estado <> 'pendente' OR v.expira_em <= clock_timestamp() THEN
      RETURN jsonb_build_object('ok', false, 'codigo', 'proposta_indisponivel', 'erro', 'Solicite uma nova proposta em outra mensagem.');
    END IF;
    -- Revalida autorização e estado atual também no retry da criação.
    v_estado := private.wa_agente_acoes_estado(p, v.acao, v.alvo, v.novo);
    IF v_estado -> 'esperado' IS DISTINCT FROM v.esperado THEN
      RETURN jsonb_build_object('ok', false, 'codigo', 'estado_alterado', 'erro', 'O registro mudou. Solicite nova proposta.');
    END IF;
  ELSE
    v_estado := private.wa_agente_acoes_estado(p, p_acao, p_alvo, p_novo);
    v_agora := clock_timestamp();
    IF p.lock_ate <= v_agora THEN RAISE EXCEPTION 'Processamento expirado.' USING ERRCODE = '42501'; END IF;
    INSERT INTO public.wa_agente_acoes_propostas (tenant_id, user_id, membro_id, instance_uuid, chat_jid, eh_grupo,
      remetente_chave, pedido_origem_id, mensagem_origem_id, origem_criada_em, acao, alvo, novo, esperado, previa, codigo, criada_em, expira_em)
      VALUES (p.tenant_id, p.user_id, p.membro_id, p.instance_uuid, p.chat_jid, p.eh_grupo, p.remetente_chave,
        p.id, p.chat_message_id, p.created_at, p_acao, p_alvo, p_novo, v_estado -> 'esperado', v_estado -> 'previa',
        upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8)), v_agora, v_agora + interval '5 minutes') RETURNING * INTO v;
  END IF;
  IF p.lock_ate <= clock_timestamp() THEN RAISE EXCEPTION 'Processamento expirado.' USING ERRCODE = '42501'; END IF;
  RETURN jsonb_build_object('ok', true, 'proposta_id', v.id, 'codigo', v.codigo, 'expira_em', v.expira_em, 'previa', v.previa);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_agente_aprendizados_confere()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  -- Usuário logado só grava na própria empresa (recusa genérica, antes do RLS).
  IF v_uid IS NOT NULL AND NEW.tenant_id IS DISTINCT FROM public.get_user_tenant_id() THEN
    RAISE EXCEPTION 'Registro não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.instrucao := btrim(NEW.instrucao);
    -- Pela tela: autor = quem está logado; origem 'tela'; sem pedido.
    IF v_uid IS NOT NULL THEN
      NEW.origem := 'tela';
      NEW.criado_por_user := v_uid;
      NEW.criado_por_nome := (SELECT left(u.nome, 80) FROM public.users u WHERE u.id = v_uid AND u.tenant_id = NEW.tenant_id);
      NEW.pedido_id := NULL;
      NEW.created_at := now();
    END IF;
    NEW.desativado_em := CASE WHEN NEW.ativo THEN NULL ELSE now() END;
  ELSE
    -- Imutáveis depois de criado.
    NEW.tenant_id := OLD.tenant_id;
    NEW.instrucao := OLD.instrucao;
    NEW.categoria := OLD.categoria;
    NEW.origem := OLD.origem;
    NEW.criado_por_user := OLD.criado_por_user;
    NEW.criado_por_nome := OLD.criado_por_nome;
    NEW.pedido_id := OLD.pedido_id;
    NEW.created_at := OLD.created_at;
    IF NEW.ativo IS DISTINCT FROM OLD.ativo THEN
      NEW.desativado_em := CASE WHEN NEW.ativo THEN NULL ELSE now() END;
    END IF;
  END IF;

  -- Limite de 50 ativos por empresa (ao criar ativo ou religar).
  IF NEW.ativo AND (TG_OP = 'INSERT' OR OLD.ativo IS DISTINCT FROM true) THEN
    PERFORM pg_advisory_xact_lock(hashtext('wa_agente_aprendizados:' || NEW.tenant_id::text));
    IF (SELECT count(*) FROM public.wa_agente_aprendizados a
         WHERE a.tenant_id = NEW.tenant_id AND a.ativo AND a.id IS DISTINCT FROM NEW.id) >= 50 THEN
      RAISE EXCEPTION 'Limite de 50 aprendizados ativos por empresa atingido. Desligue ou apague algum antes.'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_agente_confere_grupo()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_inst_txt TEXT;
  v_inst     UUID;
  v_base     TEXT;
  v_nome     TEXT;
  v_chave    TEXT;
BEGIN
  IF auth.uid() IS NOT NULL AND NEW.tenant_id IS DISTINCT FROM public.get_user_tenant_id() THEN
    RAISE EXCEPTION 'Registro não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;

  -- Pausar nunca é bloqueado.
  IF TG_OP = 'UPDATE' AND NEW.ativo = false
     AND NEW.grupo_jid IS NOT DISTINCT FROM OLD.grupo_jid
     AND NEW.tenant_id IS NOT DISTINCT FROM OLD.tenant_id THEN
    RETURN NEW;
  END IF;

  NEW.grupo_jid := lower(btrim(coalesce(NEW.grupo_jid, '')));
  IF NEW.grupo_jid <> '' AND right(NEW.grupo_jid, 5) <> '@g.us' THEN
    NEW.grupo_jid := NEW.grupo_jid || '@g.us';
  END IF;
  IF length(NEW.grupo_jid) > 60
     OR NEW.grupo_jid !~ '^(120363[0-9]{9,15}|[1-9][0-9]{9,14}-[0-9]{9,11})@g\.us$' THEN
    RAISE EXCEPTION 'Grupo inválido.' USING ERRCODE = 'check_violation';
  END IF;
  v_base := left(NEW.grupo_jid, length(NEW.grupo_jid) - length('@g.us'));

  SELECT c.uazapi_instance_id INTO v_inst_txt
    FROM public.wa_auto_config c
   WHERE c.tenant_id = NEW.tenant_id;
  IF v_inst_txt IS NULL THEN
    RAISE EXCEPTION 'Escolha primeiro o número do assistente (aba Conexão): o grupo precisa ser desse número.'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT wi.id INTO v_inst
    FROM public.whatsapp_instances wi
   WHERE wi.tenant_id = NEW.tenant_id AND wi.instance_id = v_inst_txt;
  IF v_inst IS NULL THEN
    RAISE EXCEPTION 'O número do assistente não foi encontrado nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM public.chat_contacts ct
      JOIN public.chat_conversations cv
        ON cv.contact_id = ct.id AND cv.tenant_id = ct.tenant_id
     WHERE ct.tenant_id = NEW.tenant_id
       AND ct.instance_id = v_inst
       AND cv.instance_id = v_inst
       AND cv.is_group = true
       AND lower(btrim(ct.numero_whatsapp)) IN (v_base, NEW.grupo_jid)
  ) THEN
    RAISE EXCEPTION 'Grupo não encontrado nas conversas do número do assistente. O número precisa estar no grupo.'
      USING ERRCODE = 'check_violation';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.chat_contacts ct
     WHERE ct.tenant_id = NEW.tenant_id
       AND lower(btrim(ct.numero_whatsapp)) IN (v_base, NEW.grupo_jid)
       AND (
         ct.client_id IS NOT NULL
         OR EXISTS (
           SELECT 1 FROM public.chat_contact_clients cc
            WHERE cc.tenant_id = NEW.tenant_id AND cc.contact_id = ct.id
         )
       )
  ) THEN
    RAISE EXCEPTION 'Este grupo está vinculado a um cliente. O assistente só responde em grupos internos da equipe.'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT nullif(btrim(ct.nome), '') INTO v_nome
    FROM public.chat_contacts ct
   WHERE ct.tenant_id = NEW.tenant_id
     AND ct.instance_id = v_inst
     AND lower(btrim(ct.numero_whatsapp)) IN (v_base, NEW.grupo_jid)
     AND nullif(btrim(ct.nome), '') IS NOT NULL
   ORDER BY ct.atualizado_em DESC NULLS LAST
   LIMIT 1;
  NEW.nome := left(coalesce(v_nome, 'Grupo sem nome'), 120);

  v_chave := btrim(regexp_replace(
    lower(extensions.unaccent('extensions.unaccent'::regdictionary, NEW.nome)), '\s+', ' ', 'g'));
  IF v_chave <> '' AND EXISTS (
    SELECT 1
      FROM public.clients cl
     WHERE cl.tenant_id = NEW.tenant_id
       AND cl.ativo IS DISTINCT FROM false
       AND btrim(regexp_replace(
             lower(extensions.unaccent('extensions.unaccent'::regdictionary, coalesce(cl.nome, ''))), '\s+', ' ', 'g'))
           = v_chave
  ) THEN
    RAISE EXCEPTION 'Este grupo tem o mesmo nome de um cliente. O assistente só responde em grupos internos da equipe.'
      USING ERRCODE = 'check_violation';
  END IF;

  IF TG_OP = 'INSERT' THEN
    PERFORM pg_advisory_xact_lock(hashtext('wa_agente_grupos:' || NEW.tenant_id::text));
    IF (SELECT count(*) FROM public.wa_agente_grupos WHERE tenant_id = NEW.tenant_id) >= 10 THEN
      RAISE EXCEPTION 'Limite de 10 grupos por empresa atingido.' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_agente_confere_grupo_numero()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_grupo_tenant UUID;
  v_jid  TEXT;
  v_base TEXT;
BEGIN
  IF auth.uid() IS NOT NULL AND NEW.tenant_id IS DISTINCT FROM public.get_user_tenant_id() THEN
    RAISE EXCEPTION 'Registro não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;

  SELECT g.tenant_id, g.grupo_jid INTO v_grupo_tenant, v_jid
    FROM public.wa_agente_grupos g WHERE g.id = NEW.grupo_id;
  IF v_grupo_tenant IS NULL OR v_grupo_tenant IS DISTINCT FROM NEW.tenant_id THEN
    RAISE EXCEPTION 'Grupo não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.whatsapp_instances wi
     WHERE wi.id = NEW.instance_uuid AND wi.tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'Número de WhatsApp não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;

  v_base := left(v_jid, length(v_jid) - length('@g.us'));
  IF NOT EXISTS (
    SELECT 1
      FROM public.chat_contacts ct
      JOIN public.chat_conversations cv
        ON cv.contact_id = ct.id AND cv.tenant_id = ct.tenant_id
     WHERE ct.tenant_id = NEW.tenant_id
       AND ct.instance_id = NEW.instance_uuid
       AND cv.instance_id = NEW.instance_uuid
       AND cv.is_group = true
       AND lower(btrim(ct.numero_whatsapp)) IN (v_base, v_jid)
  ) THEN
    RAISE EXCEPTION 'Esse número não está no grupo (o grupo não aparece nas conversas dele).'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_agente_confere_membro()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- Usuário logado só grava na própria empresa (recusa genérica, antes do RLS).
  IF auth.uid() IS NOT NULL AND NEW.tenant_id IS DISTINCT FROM public.get_user_tenant_id() THEN
    RAISE EXCEPTION 'Registro não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;

  -- Pausar nunca é bloqueado.
  IF TG_OP = 'UPDATE' AND NEW.ativo = false
     AND NEW.user_id IS NOT DISTINCT FROM OLD.user_id
     AND NEW.tenant_id IS NOT DISTINCT FROM OLD.tenant_id THEN
    RETURN NEW;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.users u
     WHERE u.id = NEW.user_id
       AND u.tenant_id = NEW.tenant_id
       AND u.ativo IS TRUE
       AND u.perfil IS DISTINCT FROM 'cliente'
  ) THEN
    RAISE EXCEPTION 'Usuário não encontrado nesta empresa (ou inativo, ou é cliente).' USING ERRCODE = 'check_violation';
  END IF;

  IF TG_OP = 'INSERT' THEN
    PERFORM pg_advisory_xact_lock(hashtext('wa_agente_membros:' || NEW.tenant_id::text));
    IF (SELECT count(*) FROM public.wa_agente_membros WHERE tenant_id = NEW.tenant_id) >= 100 THEN
      RAISE EXCEPTION 'Limite de 100 pessoas por empresa atingido.' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_agente_escopo(p_tenant uuid, p_user uuid)
 RETURNS TABLE(total boolean, client_ids uuid[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF p_tenant IS NULL OR p_user IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.users u
     WHERE u.id = p_user
       AND u.tenant_id = p_tenant
       AND u.ativo IS TRUE
       AND u.perfil IS DISTINCT FROM 'cliente'
  ) THEN
    RETURN QUERY SELECT false, '{}'::uuid[];
    RETURN;
  END IF;

  IF COALESCE(public.has_permissao_de(p_user, 'clientes.carteira', 'ver'), false) THEN
    RETURN QUERY SELECT true, '{}'::uuid[];
    RETURN;
  END IF;

  RETURN QUERY
    SELECT false, COALESCE(array_agg(DISTINCT ca.client_id), '{}'::uuid[])
      FROM public.client_assignments ca
      JOIN public.clients cl ON cl.id = ca.client_id AND cl.tenant_id = p_tenant
     WHERE ca.tenant_id = p_tenant
       AND ca.user_id = p_user
       AND ca.ativo IS TRUE;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_agente_grupo_restrito_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.grupo_jid IS NOT NULL AND NEW.tenant_id IS NOT NULL THEN
    PERFORM private.marcar_grupo_restrito(NEW.tenant_id, NEW.grupo_jid, 'agente_ia');
  END IF;
  RETURN NULL; -- AFTER
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_agente_pedido_acorda()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_segredo TEXT;
BEGIN
  SELECT s.decrypted_secret INTO v_segredo
    FROM vault.decrypted_secrets s
   WHERE s.name = 'wa_auto_cron_secret'
   LIMIT 1;
  IF v_segredo IS NULL THEN
    RETURN NULL;
  END IF;
  BEGIN
    PERFORM net.http_post(
      url := 'https://wuzmckatbmlpkdxtfhqr.supabase.co/functions/v1/wa-agente-responder',
      headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', v_segredo),
      body := jsonb_build_object('pedido_id', NEW.id),
      timeout_milliseconds := 150000
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'wa_agente_pedido_acorda: pg_net indisponível (%)', SQLSTATE;
  END;
  RETURN NULL; -- AFTER
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_agente_reivindicar(p_limite integer)
 RETURNS SETOF wa_agente_pedidos
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  UPDATE public.wa_agente_pedidos p
     SET status = 'falhou', motivo = 'tentativas_esgotadas', lock_ate = NULL
   WHERE p.status = 'processando' AND p.lock_ate < now() AND p.tentativas >= 3;

  UPDATE public.wa_agente_pedidos p
     SET status = 'ignorado', motivo = 'expirado'
   WHERE p.status = 'aguardando' AND p.processar_apos < now() - interval '30 minutes';

  RETURN QUERY
    WITH alvo AS (
      SELECT p.id
        FROM public.wa_agente_pedidos p
       WHERE (p.status = 'aguardando' AND p.processar_apos <= now())
          OR (p.status = 'processando' AND p.lock_ate < now() AND p.tentativas < 3)
       ORDER BY p.processar_apos, p.created_at
       LIMIT LEAST(GREATEST(COALESCE(p_limite, 10), 1), 50)
       FOR UPDATE SKIP LOCKED
    )
    UPDATE public.wa_agente_pedidos p
       SET status = 'processando',
           lock_ate = now() + interval '3 minutes',
           tentativas = p.tentativas + 1
      FROM alvo
     WHERE p.id = alvo.id
    RETURNING p.*;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_auto_alertas_ignorados_confere()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.tenant_id IS NULL THEN
    RAISE EXCEPTION 'Empresa não identificada.' USING ERRCODE = 'check_violation';
  END IF;
  -- Usuário logado só grava na própria empresa: recusa já aqui (antes do RLS) com
  -- a mesma resposta, para não revelar se um id existe em outra empresa.
  IF auth.uid() IS NOT NULL AND NEW.tenant_id IS DISTINCT FROM public.get_user_tenant_id() THEN
    RAISE EXCEPTION 'Cliente ou contato não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.client_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.clients c WHERE c.id = NEW.client_id AND c.tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'Cliente ou contato não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.contact_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.chat_contacts ct WHERE ct.id = NEW.contact_id AND ct.tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'Cliente ou contato não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;
  -- Quem está logado grava como ele mesmo; o servidor (sem sessão) fica NULL.
  NEW.criado_por := auth.uid();
  NEW.created_at := now();
  NEW.motivo := NULLIF(btrim(NEW.motivo), '');
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_auto_confere_grupo_gestor()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_inst_txt TEXT;
  v_inst     UUID;
  v_base     TEXT;
  v_nome     TEXT;
  v_chave    TEXT;
BEGIN
  -- Usuário logado só grava na própria empresa: recusa já aqui (antes do RLS), com
  -- resposta genérica, para não revelar se um grupo/id existe em outra empresa.
  IF auth.uid() IS NOT NULL AND NEW.tenant_id IS DISTINCT FROM public.get_user_tenant_id() THEN
    RAISE EXCEPTION 'Registro não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.tipo IS DISTINCT FROM 'grupo' THEN
    RETURN NEW; -- pessoa: os CHECKs da tabela bastam
  END IF;

  -- Pausar nunca é bloqueado (mesmo que o grupo tenha sido vinculado a cliente depois).
  IF TG_OP = 'UPDATE' AND NEW.ativo = false
     AND NEW.tipo IS NOT DISTINCT FROM OLD.tipo
     AND NEW.grupo_jid IS NOT DISTINCT FROM OLD.grupo_jid THEN
    RETURN NEW;
  END IF;

  NEW.grupo_jid := lower(btrim(coalesce(NEW.grupo_jid, '')));
  IF length(NEW.grupo_jid) > 60
     OR NEW.grupo_jid !~ '^(120363[0-9]{9,15}|[1-9][0-9]{9,14}-[0-9]{9,11})@g\.us$' THEN
    RAISE EXCEPTION 'Grupo inválido.' USING ERRCODE = 'check_violation';
  END IF;
  -- O Chat guarda o grupo sem o sufixo; aceitamos as duas formas.
  v_base := left(NEW.grupo_jid, length(NEW.grupo_jid) - length('@g.us'));

  SELECT c.uazapi_instance_id INTO v_inst_txt
    FROM public.wa_auto_config c
   WHERE c.tenant_id = NEW.tenant_id;
  IF v_inst_txt IS NULL THEN
    RAISE EXCEPTION 'Escolha primeiro o número que envia (aba Conexão): o grupo precisa ser desse número.'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT wi.id INTO v_inst
    FROM public.whatsapp_instances wi
   WHERE wi.tenant_id = NEW.tenant_id AND wi.instance_id = v_inst_txt;
  IF v_inst IS NULL THEN
    RAISE EXCEPTION 'O número que envia não foi encontrado nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;

  -- Precisa ser um GRUPO que aparece nas conversas do número que envia.
  IF NOT EXISTS (
    SELECT 1
      FROM public.chat_contacts ct
      JOIN public.chat_conversations cv
        ON cv.contact_id = ct.id AND cv.tenant_id = ct.tenant_id
     WHERE ct.tenant_id = NEW.tenant_id
       AND ct.instance_id = v_inst
       AND cv.instance_id = v_inst
       AND cv.is_group = true
       AND lower(btrim(ct.numero_whatsapp)) IN (v_base, NEW.grupo_jid)
  ) THEN
    RAISE EXCEPTION 'Grupo não encontrado nas conversas do número que envia. O número precisa estar no grupo.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- NUNCA grupo de cliente: nenhum contato da empresa com este grupo pode estar
  -- vinculado a cliente (direto ou por chat_contact_clients), em nenhum número.
  IF EXISTS (
    SELECT 1
      FROM public.chat_contacts ct
     WHERE ct.tenant_id = NEW.tenant_id
       AND lower(btrim(ct.numero_whatsapp)) IN (v_base, NEW.grupo_jid)
       AND (
         ct.client_id IS NOT NULL
         OR EXISTS (
           SELECT 1 FROM public.chat_contact_clients cc
            WHERE cc.tenant_id = NEW.tenant_id AND cc.contact_id = ct.id
         )
       )
  ) THEN
    RAISE EXCEPTION 'Este grupo está vinculado a um cliente. O relatório só pode ir para grupos internos da equipe.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Nome do grupo vem do Chat (não do que a tela mandou).
  SELECT nullif(btrim(ct.nome), '') INTO v_nome
    FROM public.chat_contacts ct
   WHERE ct.tenant_id = NEW.tenant_id
     AND ct.instance_id = v_inst
     AND lower(btrim(ct.numero_whatsapp)) IN (v_base, NEW.grupo_jid)
     AND nullif(btrim(ct.nome), '') IS NOT NULL
   ORDER BY ct.atualizado_em DESC NULLS LAST
   LIMIT 1;
  NEW.grupo_nome := left(coalesce(v_nome, nullif(btrim(NEW.grupo_nome), ''), 'Grupo sem nome'), 120);

  -- Nome do grupo igual ao de um cliente ativo ⇒ provavelmente grupo de cliente
  -- sem vínculo no Chat. Chave: minúsculo, sem acento, espaços colapsados
  -- (mesma de chaveNome no servidor). Cliente ativo = ativo IS DISTINCT FROM false.
  v_chave := btrim(regexp_replace(
    lower(extensions.unaccent('extensions.unaccent'::regdictionary, NEW.grupo_nome)), '\s+', ' ', 'g'));
  IF v_chave <> '' AND EXISTS (
    SELECT 1
      FROM public.clients cl
     WHERE cl.tenant_id = NEW.tenant_id
       AND cl.ativo IS DISTINCT FROM false
       AND btrim(regexp_replace(
             lower(extensions.unaccent('extensions.unaccent'::regdictionary, coalesce(cl.nome, ''))), '\s+', ' ', 'g'))
           = v_chave
  ) THEN
    RAISE EXCEPTION 'Este grupo tem o mesmo nome de um cliente. O relatório só pode ir para grupos internos da equipe.'
      USING ERRCODE = 'check_violation';
  END IF;

  IF nullif(btrim(NEW.nome), '') IS NULL THEN
    NEW.nome := left(NEW.grupo_nome, 80);
  END IF;
  NEW.telefone := NULL;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_auto_confere_instancia()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.uazapi_instance_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.whatsapp_instances wi
     WHERE wi.instance_id = NEW.uazapi_instance_id AND wi.tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'Instância de WhatsApp não encontrada nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_auto_cron_secret_confere(p_segredo text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_segredo text;
BEGIN
  IF p_segredo IS NULL OR length(p_segredo) < 32 OR length(p_segredo) > 256 THEN
    RETURN false;
  END IF;
  SELECT decrypted_secret INTO v_segredo
    FROM vault.decrypted_secrets
   WHERE name = 'wa_auto_cron_secret'
   LIMIT 1;
  IF v_segredo IS NULL OR length(v_segredo) < 32 THEN
    RETURN false;  -- sem segredo configurado, ninguém entra (falha fechada)
  END IF;
  -- Compara os resumos (tamanho fixo), não o texto: não vaza o tamanho/prefixo.
  RETURN sha256(convert_to(p_segredo, 'UTF8')) = sha256(convert_to(v_segredo, 'UTF8'));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_auto_grupos_sem_cliente(p_tenant uuid, p_dias integer DEFAULT 7, p_agora timestamp with time zone DEFAULT now(), p_limite integer DEFAULT 200)
 RETURNS TABLE(chave text, nome text, contato_id uuid, contato_ids uuid[], msgs integer, ultima_msg timestamp with time zone, sugestao_client_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH grupos AS (
    SELECT ct.id, ct.nome, ct.client_id, ct.restrito_admin,
           private.canal_chave(ct.numero_whatsapp, ct.group_size) AS chave
      FROM public.chat_contacts ct
     WHERE ct.tenant_id = p_tenant
       AND private.canal_tipo(ct.numero_whatsapp, ct.group_size) = 'grupo'
  ),
  atividade AS (
    SELECT g.chave, g.id AS contato_id, count(*)::integer AS n, max(m.criado_em) AS ult
      FROM grupos g
      JOIN public.chat_conversations cv ON cv.tenant_id = p_tenant AND cv.contact_id = g.id
      JOIN public.chat_messages m ON m.tenant_id = p_tenant AND m.conversation_id = cv.id
     WHERE g.chave IS NOT NULL
       AND m.criado_em >= coalesce(p_agora, now()) - make_interval(days => least(greatest(coalesce(p_dias, 7), 1), 90))
       AND m.criado_em <= coalesce(p_agora, now())
       AND coalesce(m.tipo, '') <> 'nota_interna'
     GROUP BY g.chave, g.id
  ),
  por_chave AS (
    SELECT a.chave, sum(a.n)::integer AS msgs, max(a.ult) AS ult,
           (array_agg(a.contato_id ORDER BY a.ult DESC, a.contato_id))[1] AS contato_id
      FROM atividade a
     GROUP BY a.chave
  )
  SELECT pc.chave,
         (SELECT g.nome FROM grupos g WHERE g.id = pc.contato_id),
         pc.contato_id,
         (SELECT array_agg(g.id ORDER BY g.id) FROM grupos g WHERE g.chave = pc.chave),
         pc.msgs,
         pc.ult,
         (SELECT c.client_id FROM public.cliente_canais c
           WHERE c.tenant_id = p_tenant AND c.tipo = 'grupo' AND c.chave = pc.chave AND c.status = 'sugerido'
           ORDER BY c.score DESC NULLS LAST, c.criado_em
           LIMIT 1)
    FROM por_chave pc
   WHERE NOT EXISTS (
           SELECT 1 FROM public.cliente_canais c
            WHERE c.tenant_id = p_tenant AND c.tipo = 'grupo' AND c.chave = pc.chave
              AND c.status IN ('confirmado', 'interno', 'nao_cliente'))
     AND NOT EXISTS (
           SELECT 1 FROM grupos g
            WHERE g.chave = pc.chave
              AND (g.restrito_admin IS TRUE OR g.client_id IS NOT NULL
                   OR EXISTS (SELECT 1 FROM public.chat_contact_clients cc
                               WHERE cc.tenant_id = p_tenant AND cc.contact_id = g.id)))
     AND NOT EXISTS (SELECT 1 FROM public.chat_grupos_restritos r
                      WHERE r.tenant_id = p_tenant AND private.canal_chave(r.grupo_base, 1) = pc.chave)
     AND NOT EXISTS (SELECT 1 FROM public.wa_agente_grupos ag
                      WHERE ag.tenant_id = p_tenant AND private.canal_chave(ag.grupo_jid, 1) = pc.chave)
     AND NOT EXISTS (SELECT 1 FROM public.wa_auto_gestores wg
                      WHERE wg.tenant_id = p_tenant AND wg.grupo_jid IS NOT NULL
                        AND private.canal_chave(wg.grupo_jid, 1) = pc.chave)
   ORDER BY pc.msgs DESC, pc.ult DESC, pc.chave
   LIMIT least(greatest(coalesce(p_limite, 200), 1), 500)
$function$
;

CREATE OR REPLACE FUNCTION public.wa_auto_limita_gestores()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- Trava por empresa: duas inserções simultâneas não furam o limite.
  PERFORM pg_advisory_xact_lock(hashtext(NEW.tenant_id::text));
  IF (SELECT count(*) FROM public.wa_auto_gestores WHERE tenant_id = NEW.tenant_id) >= 10 THEN
    RAISE EXCEPTION 'Limite de 10 destinos (pessoas e grupos) por empresa atingido.' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_auto_queda_volume(p_tenant_id uuid, p_limiar numeric, p_agora timestamp with time zone DEFAULT now())
 RETURNS TABLE(contact_id uuid, msgs_semana integer, media_semanal numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH canais AS (
    SELECT c.id AS conversation_id, ct.id AS contact_id,
           CASE
             WHEN c.is_group IS TRUE
              AND regexp_replace(btrim(ct.numero_whatsapp), '@g\.us$', '') ~ '^[0-9]{5,30}(-[0-9]{5,20})?$'
             THEN 'grupo:' || regexp_replace(btrim(ct.numero_whatsapp), '@g\.us$', '')
             ELSE 'contato:' || ct.id::text
           END AS canal,
           (
             EXISTS (SELECT 1 FROM public.clients cl
                      WHERE cl.id = ct.client_id AND cl.tenant_id = p_tenant_id)
             OR EXISTS (SELECT 1 FROM public.chat_contact_clients vinculo
                         JOIN public.clients cl ON cl.id = vinculo.client_id AND cl.tenant_id = p_tenant_id
                        WHERE vinculo.contact_id = ct.id AND vinculo.tenant_id = p_tenant_id)
           ) AS vinculado
      FROM public.chat_conversations c
      JOIN public.chat_contacts ct ON ct.id = c.contact_id AND ct.tenant_id = p_tenant_id
     WHERE c.tenant_id = p_tenant_id
       AND p_tenant_id IS NOT NULL
       AND COALESCE(c.arquivada, false) = false
  ), representantes AS (
    -- Pode representar pela origem vinculada mesmo sem mensagem nela nesta janela.
    -- Nenhuma associação é feita por nome, nem entre tenants ou contatos privados.
    SELECT DISTINCT ON (canal) canal, contact_id
      FROM canais
     ORDER BY canal, vinculado DESC, contact_id
  ), eventos AS (
    SELECT c.canal, m.id, m.criado_em,
           CASE WHEN NULLIF(btrim(m.message_id_wpp), '') IS NOT NULL
                THEN 'wpp:' || btrim(m.message_id_wpp)
                ELSE 'linha:' || m.id::text END AS chave_mensagem
      FROM public.chat_messages m
      JOIN canais c ON c.conversation_id = m.conversation_id
     WHERE m.tenant_id = p_tenant_id
       AND m.autor_tipo = 'cliente'
       AND m.criado_em >= p_agora - interval '35 days'
       AND m.criado_em < p_agora
  ), mensagens_unicas AS (
    -- Mesmo evento captado em duas instâncias conta uma vez; sem providerID usa a linha.
    SELECT DISTINCT ON (canal, chave_mensagem) canal, criado_em
      FROM eventos
     ORDER BY canal, chave_mensagem, criado_em, id
  ), por_canal AS (
    SELECT canal,
           count(*) FILTER (WHERE criado_em >= p_agora - interval '7 days') AS atual,
           count(*) FILTER (WHERE criado_em < p_agora - interval '7 days') AS anteriores
      FROM mensagens_unicas
     GROUP BY canal
  )
  SELECT r.contact_id,
         p.atual::integer,
         round(p.anteriores / 4.0, 1)
    FROM por_canal p
    JOIN representantes r ON r.canal = p.canal
   WHERE p.anteriores / 4.0 >= 5
     AND p.atual < (p.anteriores / 4.0) * (1 - LEAST(GREATEST(COALESCE(p_limiar, 50), 0), 100) / 100.0)
   ORDER BY (p.anteriores / 4.0 - p.atual) DESC, r.contact_id
   LIMIT 50;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_auto_satisfacao_confere()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.tenant_id IS NULL THEN
    RAISE EXCEPTION 'Empresa não identificada.' USING ERRCODE = 'check_violation';
  END IF;
  -- Usuário logado só grava na própria empresa: recusa já aqui (antes do RLS), com
  -- resposta genérica, para não revelar se um id existe em outra empresa.
  IF auth.uid() IS NOT NULL AND NEW.tenant_id IS DISTINCT FROM public.get_user_tenant_id() THEN
    RAISE EXCEPTION 'Registro não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.chat_conversations c WHERE c.id = NEW.conversation_id AND c.tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'Conversa não encontrada nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.contact_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.chat_contacts ct WHERE ct.id = NEW.contact_id AND ct.tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'Contato não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.client_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.clients cl WHERE cl.id = NEW.client_id AND cl.tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'Cliente não encontrado nesta empresa.' USING ERRCODE = 'check_violation';
  END IF;
  NEW.created_at := now();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_auto_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_base_url_permitida(p_provider text, p_url text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
  SELECT CASE p_provider
    WHEN 'uazapi' THEN p_url ~* '^https://([a-z0-9-]+\.)*uazapi\.com(/[a-z0-9._~/-]*)?$'
    WHEN 'zernio' THEN p_url ~* '^https://([a-z0-9-]+\.)*zernio\.com(/[a-z0-9._~/-]*)?$'
    ELSE true  -- 'empire' segue a regra antiga (sem allowlist aqui)
  END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_grupo_restrito_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.tipo = 'grupo' AND NEW.grupo_jid IS NOT NULL AND NEW.tenant_id IS NOT NULL THEN
    PERFORM private.marcar_grupo_restrito(NEW.tenant_id, NEW.grupo_jid, 'relatorio_diario');
  END IF;
  RETURN NULL; -- AFTER
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_webhook_instancia_do_token(p_token text)
 RETURNS TABLE(instance_uuid uuid, tenant_id uuid, instance_id text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
#variable_conflict use_column
DECLARE
  v_hash BYTEA;
  v_inst UUID;
BEGIN
  IF p_token IS NULL OR length(p_token) < 32 OR length(p_token) > 256 THEN
    RETURN;
  END IF;
  v_hash := sha256(convert_to(p_token, 'UTF8'));

  SELECT t.instance_id INTO v_inst
    FROM public.wa_webhook_tokens t
   WHERE t.token_hash = v_hash
      OR (t.token_hash_anterior = v_hash AND t.anterior_ate > now())
   LIMIT 1;
  IF v_inst IS NULL THEN
    RETURN;
  END IF;

  UPDATE public.wa_webhook_tokens t
     SET ultimo_uso_em = now()
   WHERE t.instance_id = v_inst
     AND (t.ultimo_uso_em IS NULL OR t.ultimo_uso_em < now() - interval '1 minute');

  RETURN QUERY
    SELECT wi.id, wi.tenant_id, wi.instance_id
      FROM public.whatsapp_instances wi
      JOIN public.wa_webhook_tokens t ON t.instance_id = wi.id AND t.tenant_id = wi.tenant_id
     WHERE wi.id = v_inst;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.wa_webhook_tokens_tenant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  SELECT wi.tenant_id INTO NEW.tenant_id FROM public.whatsapp_instances wi WHERE wi.id = NEW.instance_id;
  IF NEW.tenant_id IS NULL THEN
    RAISE EXCEPTION 'Instância não encontrada.' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$
