ALTER VIEW public."v_dept_member_metrics" SET (security_invoker = 'true');

DO $$ BEGIN
  CREATE CONSTRAINT TRIGGER desk_conta_nova_conferida AFTER INSERT ON auth.users DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION desk_conferir_conta_nova();
EXCEPTION WHEN insufficient_privilege THEN
  RAISE NOTICE 'Trigger em auth.* requer privilégio: %', SQLERRM;
END $$;
DO $$ BEGIN
  CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_new_user();
EXCEPTION WHEN insufficient_privilege THEN
  RAISE NOTICE 'Trigger em auth.* requer privilégio: %', SQLERRM;
END $$;
