CREATE POLICY "admin_manage_api_keys" ON public."api_keys" AS PERMISSIVE FOR ALL TO public USING ((EXISTS ( SELECT 1
   FROM users
  WHERE ((users.id = auth.uid()) AND (users.perfil = 'admin'::text)))));
CREATE POLICY "tenant_isolation" ON public."api_keys" AS RESTRICTIVE FOR ALL TO authenticated USING ((tenant_id = ( SELECT get_user_tenant_id() AS get_user_tenant_id))) WITH CHECK ((tenant_id = ( SELECT get_user_tenant_id() AS get_user_tenant_id)));
CREATE POLICY "admin_le_api_request_log" ON public."api_request_log" AS PERMISSIVE FOR SELECT TO public USING (((tenant_id = ( SELECT get_user_tenant_id() AS get_user_tenant_id)) AND (EXISTS ( SELECT 1
   FROM users
  WHERE ((users.id = auth.uid()) AND (users.perfil = 'admin'::text))))));
CREATE POLICY "app_logs_insert" ON public."app_logs" AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (true);
CREATE POLICY "app_logs_select_admin" ON public."app_logs" AS PERMISSIVE FOR SELECT TO authenticated USING (is_admin());
CREATE POLICY "app_logs_tenant_isolation" ON public."app_logs" AS RESTRICTIVE FOR ALL TO authenticated USING ((tenant_id = ( SELECT get_user_tenant_id() AS get_user_tenant_id))) WITH CHECK ((tenant_id = ( SELECT get_user_tenant_id() AS get_user_tenant_id)));
