CREATE POLICY "admin_view_webhook_logs" ON public."webhook_logs" AS PERMISSIVE FOR SELECT TO public USING ((EXISTS ( SELECT 1
   FROM users
  WHERE ((users.id = auth.uid()) AND (users.perfil = 'admin'::text)))));
CREATE POLICY "tenant_isolation" ON public."webhook_logs" AS RESTRICTIVE FOR ALL TO authenticated USING ((tenant_id = ( SELECT get_user_tenant_id() AS get_user_tenant_id))) WITH CHECK ((tenant_id = ( SELECT get_user_tenant_id() AS get_user_tenant_id)));
CREATE POLICY "admin_manage_webhooks" ON public."webhooks" AS PERMISSIVE FOR ALL TO public USING ((EXISTS ( SELECT 1
   FROM users
  WHERE ((users.id = auth.uid()) AND (users.perfil = 'admin'::text)))));
CREATE POLICY "tenant_isolation" ON public."webhooks" AS RESTRICTIVE FOR ALL TO authenticated USING ((tenant_id = ( SELECT get_user_tenant_id() AS get_user_tenant_id))) WITH CHECK ((tenant_id = ( SELECT get_user_tenant_id() AS get_user_tenant_id)));
CREATE POLICY "admin_manage_instances" ON public."whatsapp_instances" AS PERMISSIVE FOR ALL TO public USING ((( SELECT users.perfil
   FROM users
  WHERE (users.id = auth.uid())) = 'admin'::text));
CREATE POLICY "chat_read_instances" ON public."whatsapp_instances" AS PERMISSIVE FOR SELECT TO public USING (user_can_access_instance(id));
CREATE POLICY "tenant_isolation" ON public."whatsapp_instances" AS RESTRICTIVE FOR ALL TO authenticated USING ((tenant_id = ( SELECT get_user_tenant_id() AS get_user_tenant_id))) WITH CHECK ((tenant_id = ( SELECT get_user_tenant_id() AS get_user_tenant_id)));

-- GRANTs essenciais pro service_role (Edge Functions)
GRANT ALL ON ALL TABLES    IN SCHEMA public TO service_role, postgres;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO service_role, postgres;
GRANT ALL ON ALL FUNCTIONS IN SCHEMA public TO service_role, postgres;
GRANT USAGE ON SCHEMA public TO service_role, anon, authenticated;
-- Garantia pra tabelas/funções criadas no futuro
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES    TO service_role, postgres;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON SEQUENCES TO service_role, postgres;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON FUNCTIONS TO service_role, postgres;

-- private: schema interno (políticas e funções do app). Nada de PUBLIC; as
-- funções que o app precisa em anon/authenticated ganham EXECUTE logo abaixo.
REVOKE ALL ON SCHEMA private FROM PUBLIC;
GRANT USAGE ON SCHEMA private TO service_role, anon, authenticated;
GRANT ALL ON ALL TABLES    IN SCHEMA private TO service_role, postgres;
GRANT ALL ON ALL SEQUENCES IN SCHEMA private TO service_role, postgres;
ALTER DEFAULT PRIVILEGES IN SCHEMA private GRANT ALL ON TABLES    TO service_role, postgres;
ALTER DEFAULT PRIVILEGES IN SCHEMA private GRANT ALL ON SEQUENCES TO service_role, postgres;

